const results = await Promise.allSettled([
tools.exec_command({cmd:"git status --short --branch",max_output_tokens:2000}),
tools.exec_command({cmd:"cat AGENTS.md docs/architecture.md docs/local-development.md docs/testing.md .github/instructions/*",max_output_tokens:16000}),
tools.exec_command({cmd:"gh api repos/ohcnetwork/care/commits/9dad38e1f6c2190eaa56d3138597be191781d043 > /tmp/care-workspace-commit.json && python3 -c 'import json; d=json.load(open(\"/tmp/care-workspace-commit.json\")); print(d[\"commit\"][\"message\"]); print(\"\\n\".join(f[\"filename\"] for f in d[\"files\"]))'",max_output_tokens:4000}),
tools.exec_command({cmd:"cat /Users/bodhishthomas/.codex/skills/frontend-design/SKILL.md",max_output_tokens:6000})
]); results.forEach((r,i)=>text({i,...r}));
text(ALL_TOOLS.filter(x=>/plan/.test(x.name)&&! /plant|explain/.test(x.name)));

const results = await Promise.allSettled([
tools.exec_command({cmd:"rg -n -i 'workspace|resource.?config|observation.?definition' src/Routers/routes src/pages/Admin src/pages/Facility src/types | head -160",max_output_tokens:7500}),
tools.exec_command({cmd:"python3 - <<'PY'
import json
c=json.load(open('/tmp/care-workspace-commit.json'))
for f in c['files']:
 if f['filename'].endswith(('workspace.py','spec.py')):
  print(f['filename']); print(f.get('patch',''))
PY",max_output_tokens:15500}),
tools.exec_command({cmd:"rg --files -g AGENTS.md -g package.json -g '*playwright*' -g '*Workspace*' -g '*Tag*' -g '*ValueSet*' -g '*Questionnaire*' src tests .github | head -120; cat package.json; cat .github/instructions/pages.instructions.md",max_output_tokens:7000})
]); results.forEach((r,i)=>text({i,...r}));

