export function ValueSetList({ scope }: { scope: ValueSetScope }) {
  const { t } = useTranslation();
  const filterId = useId();
  const isFacility = scope.authContext === "facility";
  const { canWrite } = useCanWriteValueSet(scope);
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
  });

  // The admin area only ever lists instance sets; inside a facility the
  // Shared catalogue is read-only and offers facility customization.
  const source: Source =
    isFacility && qParams.source !== "instance" ? "facility" : "instance";

  const { data: response, isLoading } = useQuery({
    queryKey: ["valuesets", scope.authContext, scope.facilityId, qParams],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: {
        limit: resultsPerPage,
        offset: ((qParams.page || 1) - 1) * resultsPerPage,
        name: qParams.name,
        status: qParams.status || ValueSetStatus.ACTIVE,
        ...(source === "facility"
          ? { facility: scope.facilityId }
          : { auth_context: "instance" }),
      },
    }),
  });

  const valuesets = response?.results || [];

  const rowsProps: RowsProps = {
    valuesets,
    isLoading,
    emptyMessage:
      source === "facility" && canWrite
        ? t("no_facility_valuesets")
        : t("adjust_valueset_filters"),
    renderActions: (valueset) => (
      <ValueSetListActions
        valueset={valueset}
        scope={scope}
        isSharedCatalogue={source === "instance"}
        canWrite={canWrite}
      />
    ),
  };

  return (
    <div className="container mx-auto space-y-5 px-4 py-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0 flex-1">
          <h1 className="text-2xl font-semibold tracking-tight text-gray-950">
            {t("valuesets")}
          </h1>
          {!isFacility && (
            <p className="mt-1 text-sm text-gray-600">
              {t("manage_and_view_valuesets")}
            </p>
          )}
        </div>

        {/* The shared catalogue only offers customization, not instance creation. */}
        {canWrite && (!isFacility || source === "facility") && (
          <Button asChild className="h-10 shrink-0 sm:h-9">
            <Link href={`${scope.basePath}/create`} basePath="/">
              <PlusIcon className="size-4" aria-hidden="true" />
              {t("create_valueset")}
            </Link>
          </Button>
        )}
      </div>

      <div className="space-y-4">
        {isFacility ? (
          <div className="space-y-3 border-b border-gray-200 pb-4">
            <Tabs
              value={source}
              onValueChange={(value) =>
                updateQuery({
                  source: value === "instance" ? value : undefined,
                  page: 1,
                })
              }
            >
              <TabsList
                aria-label={t("source")}
                className="h-10 w-full sm:w-fit"
              >
                <TabsTrigger value="facility" className="flex-1 px-4">
                  {t("this_facility")}
                </TabsTrigger>
                <TabsTrigger value="instance" className="flex-1 px-4">
                  {t("valueset_shared_catalogue")}
                </TabsTrigger>
              </TabsList>
            </Tabs>
            <p className="max-w-3xl text-sm leading-5 text-gray-600">
              {source === "facility"
                ? t("manage_facility_valuesets")
                : t("valueset_shared_catalogue_description")}
            </p>
          </div>
        ) : (
          <div className="w-full overflow-x-auto pb-1">
            <Tabs
              value={qParams.status || ValueSetStatus.ACTIVE}
              onValueChange={(value) => updateQuery({ status: value, page: 1 })}
            >
              <div className="min-w-[480px]">
                <TabsList aria-label={t("status")} className="flex w-full">
                  {valuesOf(ValueSetStatus).map((status) => {
                    const IconComponent = VALUESET_STATUS_ICONS[status];
                    return (
                      <TabsTrigger
                        key={status}
                        value={status}
                        className="flex-1"
                      >
                        <IconComponent className="size-4" aria-hidden="true" />
                        {t(status)}
                      </TabsTrigger>
                    );
                  })}
                </TabsList>
              </div>
            </Tabs>
          </div>
        )}

        <div className="flex flex-col gap-3 sm:flex-row sm:items-end">
          <div className="w-full space-y-1.5 sm:max-w-md">
            <Label htmlFor={`${filterId}-search`} className="text-gray-700">
              {t("search")}
            </Label>
            <div className="relative">
              <Search
                className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-500"
                aria-hidden="true"
              />
              <Input
                id={`${filterId}-search`}
                aria-label={t("search_valuesets")}
                placeholder={t("search_valuesets")}
                className="h-10 w-full pl-9"
                value={qParams.name || ""}
                onChange={(e) => updateQuery({ name: e.target.value, page: 1 })}
              />
            </div>
          </div>

          {isFacility && (
            <div className="space-y-1.5 sm:w-40 sm:shrink-0">
              <Label htmlFor={`${filterId}-status`} className="text-gray-700">
                {t("status")}
              </Label>
              <Select
                value={qParams.status || ValueSetStatus.ACTIVE}
                onValueChange={(value) =>
                  updateQuery({ status: value, page: 1 })
                }
              >
                <SelectTrigger
                  id={`${filterId}-status`}
                  className="w-full data-[size=default]:h-10"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {valuesOf(ValueSetStatus).map((status) => {
                    const IconComponent = VALUESET_STATUS_ICONS[status];
                    return (
                      <SelectItem key={status} value={status}>
                        <IconComponent className="size-4" aria-hidden="true" />
                        {t(status)}
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>
          )}
        </div>
      </div>
      <RenderTable {...rowsProps} />
      <RenderCard {...rowsProps} />
      <Pagination totalCount={response?.count ?? 0} />
    </div>
  );
}
import { getPermissions } from "@/common/Permissions";

import { usePermissions } from "@/context/PermissionContext";

import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";

import { ValueSetScope } from "@/types/valueSet/valueSet";

/**
 * Whether the current user may create or edit value sets in `scope` — the
 * single gate for the list's Create button, the editor's save and the
 * departments field.
 *
 * Facility mounts gate on the facility's *object* permissions (the backend
 * checks `can_write_valueset` in the facility's root organization); the
 * admin mount falls back to the user's own permission union, since no
 * object-scoped permissions apply to an instance-wide list.
 *
 * `isLoading` is true while the facility (and its permissions) is still
 * being fetched on a facility mount, so callers can hold a skeleton instead
 * of flashing a denied state.
 */
export function useCanWriteValueSet(scope: ValueSetScope): {
  canWrite: boolean;
  isLoading: boolean;
} {
  const { hasPermission, userPermissions } = usePermissions();
  const { facility, isFacilityLoading } = useCurrentFacilitySilently();

  const { canWriteValueSet } = getPermissions(
    hasPermission,
    scope.authContext === "facility"
      ? (facility?.permissions ?? [])
      : userPermissions,
  );

  return {
    canWrite: canWriteValueSet,
    // Track the fetch, not data presence — a user who cannot read the
    // facility (404) would otherwise leave `!facility` true forever.
    isLoading: scope.authContext === "facility" && isFacilityLoading,
  };
}
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";

import FacilityOrganizationSelector from "@/pages/Facility/settings/organizations/components/FacilityOrganizationSelector";

import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

interface ValueSetOrganizationsFieldProps {
  facilityId: string;
  valuesetId: string;
  canWrite: boolean;
}

const valueSetOrganizationsKey = (valuesetId: string) =>
  ["valueset", valuesetId, "facility-organizations"] as const;

/**
 * Departments that can see and use a facility value set. A facility set
 * with no departments is visible to superusers only (the backend gates
 * reads on organization membership), so this is the first thing to fill in
 * after creating one.
 *
 * The organizations endpoints 403 for anything but a facility-context set;
 * a user's own set listed under the same facility therefore renders
 * nothing here rather than an error.
 */
export function ValueSetOrganizationsField({
  facilityId,
  valuesetId,
  canWrite,
}: ValueSetOrganizationsFieldProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const { data: current, isError } = useQuery({
    queryKey: valueSetOrganizationsKey(valuesetId),
    queryFn: query(valueSetApi.getFacilityOrganizations, {
      pathParams: { id: valuesetId },
      silent: true,
    }),
  });

  const { mutate: setFacilityOrganizations, isPending } = useMutation({
    mutationFn: mutate(valueSetApi.setFacilityOrganizations, {
      pathParams: { id: valuesetId },
    }),
    onSuccess: async () => {
      // Keep editing disabled until the controlled IDs reflect this save.
      await queryClient.invalidateQueries({
        queryKey: valueSetOrganizationsKey(valuesetId),
      });
      toast.success(t("organizations_updated"));
    },
  });

  if (isError) {
    return null;
  }

  const currentIds = current?.results.map((org) => org.id) ?? [];

  return (
    <div className="space-y-2">
      <p className="text-sm font-medium text-gray-800">
        {t("departments_with_access")}
      </p>
      <p className="text-sm text-gray-500">
        {t("departments_with_access_hint")}
      </p>
      {canWrite ? (
        <fieldset disabled={!current || isPending} aria-busy={isPending}>
          <FacilityOrganizationSelector
            facilityId={facilityId}
            value={currentIds}
            currentOrganizations={current?.results}
            optional
            onChange={(ids) => {
              // Portaled picker controls sit outside the disabled fieldset.
              if (!current || isPending) return;
              setFacilityOrganizations({ facility_organizations: ids ?? [] });
            }}
          />
        </fieldset>
      ) : (
        <div className="flex flex-wrap items-center gap-2 rounded-md border border-gray-200 p-1.5">
          {currentIds.length === 0 && (
            <p className="px-1.5 py-1 text-sm text-gray-500">
              {t("no_departments_assigned")}
            </p>
          )}
          {current?.results.map((org) => (
            <Badge key={org.id} variant="secondary">
              {org.name}
            </Badge>
          ))}
        </div>
      )}
    </div>
  );
}

