  const { mutate: update, isPending: isUpdating } = useMutation({
    mutationFn: mutate(actionConfigurationApi.update, {
      pathParams: { id: id ?? "" },
    }),
    onSuccess: (updated: ActionConfigurationRead) => {
      queryClient.setQueryData(
