import { UserReadMinimal } from "@/types/user/user";

export const WORKSPACE_AUTH_CONTEXTS = [
  "instance",
  "facility",
  "facility_organization",
  "user",
] as const;

export type WorkspaceAuthContext = (typeof WORKSPACE_AUTH_CONTEXTS)[number];

export type WorkspaceAdminScope = Extract<
  WorkspaceAuthContext,
  "instance" | "facility"
>;

export type WorkspaceScope =
  | {
      authContext: "instance";
      basePath: string;
      facilityId?: never;
    }
  | {
      authContext: "facility";
      basePath: string;
      facilityId: string;
    };

export const INSTANCE_WORKSPACE_SCOPE: WorkspaceScope = {
  authContext: "instance",
  basePath: "/admin/workspaces",
};

export function workspaceScopeForFacility(facilityId: string): WorkspaceScope {
  return {
    authContext: "facility",
    facilityId,
    basePath: `/facility/${facilityId}/settings/workspaces`,
  };
}

export const WORKSPACE_PERMISSIONS = {
  read: "can_read_workspace",
  write: "can_write_workspace",
} as const;

/** The backend accepts an arbitrary JSON object without prescribing its keys. */
export type WorkspaceTemplate = Record<string, unknown>;

export interface WorkspaceBase {
  name: string;
  description: string;
  template: WorkspaceTemplate;
}

export interface WorkspaceMinimalRead extends WorkspaceBase {
  id: string;
}

/**
 * Scope, facility, and organization are not included in the read specification.
 * Configuration pages must retain the scope used to query their workspaces.
 */
export interface WorkspaceRead extends WorkspaceMinimalRead {
  created_by: UserReadMinimal | null;
  updated_by: UserReadMinimal | null;
}

export interface WorkspaceCreate extends WorkspaceBase {
  auth_context: WorkspaceAuthContext;
  /** Required for facility and user workspaces. */
  facility?: string | null;
  /** Required for facility_organization workspaces. */
  facility_organization?: string | null;
  /** Required by the create specification; currently not persisted or returned. */
  inherited: boolean;
}

/** Scope and facility cannot be changed after creation. */
export type WorkspaceUpdate = WorkspaceBase;

export interface WorkspaceFacilityOrganizationsUpdate {
  /** Replaces the entire association list with organizations from this facility. */
  facility_organizations: string[];
}

export interface WorkspaceDefaultAttributesUpdate {
  attribute?: string | null;
  value: string;
}

export interface WorkspaceUserDefaultAttributes {
  attribute: string | null;
  value: string | null;
  workspace: WorkspaceMinimalRead;
}
import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";
import { FacilityOrganizationRead } from "@/types/facilityOrganization/facilityOrganization";

import {
  WorkspaceCreate,
  WorkspaceDefaultAttributesUpdate,
  WorkspaceFacilityOrganizationsUpdate,
  WorkspaceRead,
  WorkspaceUpdate,
  WorkspaceUserDefaultAttributes,
} from "./workspace";

export default {
  /** Filter configuration lists by auth_context and, for a facility, facility. */
  list: {
    path: "/api/v1/workspace/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<WorkspaceRead>>(),
  },
  get: {
    path: "/api/v1/workspace/{id}/",
    method: HttpMethod.GET,
    TRes: Type<WorkspaceRead>(),
  },
  create: {
    path: "/api/v1/workspace/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceCreate>(),
    TRes: Type<WorkspaceRead>(),
  },
  update: {
    path: "/api/v1/workspace/{id}/",
    method: HttpMethod.PUT,
    TBody: Type<WorkspaceUpdate>(),
    TRes: Type<WorkspaceRead>(),
  },
  delete: {
    path: "/api/v1/workspace/{id}/",
    method: HttpMethod.DELETE,
    TRes: Type<void>(),
  },
  /** Facility workspaces only; requires permission to write the workspace. */
  getFacilityOrganizations: {
    path: "/api/v1/workspace/{id}/get_facility_organizations/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<FacilityOrganizationRead>>(),
  },
  setFacilityOrganizations: {
    path: "/api/v1/workspace/{id}/set_facility_organizations/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceFacilityOrganizationsUpdate>(),
    TRes: Type<Record<string, never>>(),
  },
  setDefaultAttributes: {
    path: "/api/v1/workspace/{id}/set_default_attributes/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceDefaultAttributesUpdate>(),
    TRes: Type<Record<string, never>>(),
  },
  getUserDefaultAttributes: {
    path: "/api/v1/workspace/get_user_default_attributes/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<WorkspaceUserDefaultAttributes>>(),
  },
} as const;
type QueryParamValue =
  | string
  | number
  | boolean
  | null
  | undefined
  | Array<string | number | boolean | null | undefined>;

export type QueryParams = Record<string, QueryParamValue>;

export interface ApiRoute<TData, TBody = unknown> {
  baseUrl?: string;
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  TBody?: TBody;
  path: string;
  TRes: TData;
  noAuth?: boolean;
  defaultQueryParams?: QueryParams;
}

type ExtractRouteParams<T extends string> =
  T extends `${infer _Start}{${infer Param}}${infer Rest}`
    ? Param | ExtractRouteParams<Rest>
    : never;

type PathParams<T extends string> = {
  [_ in ExtractRouteParams<T>]: string;
};

export interface ApiCallOptions<Route extends ApiRoute<unknown, unknown>> {
  pathParams?: PathParams<Route["path"]>;
  queryParams?: QueryParams;
  body?: Route["TBody"];
  silent?: boolean | ((response: Response) => boolean);
  signal?: AbortSignal;
  headers?: HeadersInit;
}

export type StructuredError = Record<string, string | string[]>;

type HTTPErrorCause = StructuredError | Record<string, unknown> | undefined;

export class HTTPError extends Error {
  status: number;
  silent: boolean;
  cause?: HTTPErrorCause;

  constructor({
    message,
    status,
    silent,
    cause,
  }: {
    message: string;
    status: number;
    silent: boolean;
    cause?: Record<string, unknown>;
  }) {
    super(message, { cause });
    this.status = status;
    this.silent = silent;
    this.cause = cause;
  }
}

export interface PaginatedResponse<TItem> {
  count: number;
  results: TItem[];
}

export interface UpsertRequest<TCreate, TUpdate> {
  datapoints: (TCreate | (TUpdate & { id: string }))[];
}

/**
 * A fake function that returns an empty object casted to type T
 * @returns Empty object as type T
 */
export function Type<T>(): T {
  return {} as T;
}

export enum HttpMethod {
  GET = "GET",
  POST = "POST",
  PUT = "PUT",
  PATCH = "PATCH",
  DELETE = "DELETE",
}

