import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { ArrowLeft, Braces, Loader2, Trash2 } from "lucide-react";
import { Link, navigate, useNavigationPrompt } from "raviger";
import { useState } from "react";
import { flushSync } from "react-dom";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import Page from "@/components/Common/Page";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader,
  AlertDialogTitle, AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Form, FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

import mutate from "@/Utils/request/mutate";
import { WorkspaceRead, WorkspaceScope, WorkspaceTemplate } from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";

import { WorkspaceOrganizationsField } from "./WorkspaceOrganizationsField";

interface WorkspaceFormValues {
  name: string;
  description: string;
  template: string;
}

interface WorkspaceFormProps {
  scope: WorkspaceScope;
  existing?: WorkspaceRead;
  canWrite: boolean;
}

function parseTemplate(value: string): WorkspaceTemplate {
  const parsed: unknown = JSON.parse(value);
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Expected a JSON object");
  }
  return parsed as WorkspaceTemplate;
}

export function WorkspaceForm({ scope, existing, canWrite }: WorkspaceFormProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [accessState, setAccessState] = useState({ dirty: false, pending: false });
  const [deleteOpen, setDeleteOpen] = useState(false);
  const schema = z.object({
    name: z.string().trim().min(1, t("workspace_name_required")),
    description: z.string(),
    template: z.string().superRefine((value, ctx) => {
      try { parseTemplate(value); } catch {
        ctx.addIssue({ code: "custom", message: t("workspace_template_invalid") });
      }
    }),
  });
  const form = useForm<WorkspaceFormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      name: existing?.name ?? "",
      description: existing?.description ?? "",
      template: JSON.stringify(existing?.template ?? {}, null, 2),
    },
  });

  const title = t(existing ? (canWrite ? "edit_workspace" : "view_workspace") : "create_workspace");
  const dirty = form.formState.isDirty || accessState.dirty;
  useNavigationPrompt(canWrite && dirty, t("unsaved_changes_warning"));

  const save = useMutation({
    mutationFn: (values: WorkspaceFormValues) => {
      const body = {
        name: values.name,
        description: values.description,
        template: parseTemplate(values.template),
      };
      return existing
        ? mutate(workspaceApi.update, { pathParams: { id: existing.id } })(body)
        : mutate(workspaceApi.create)({
            ...body,
            auth_context: scope.authContext,
            ...(scope.authContext === "facility" ? { facility: scope.facilityId } : {}),
            // Required by the API, with no persisted inheritance behavior yet.
            inherited: false,
          });
    },
    onSuccess: (data) => {
      queryClient.setQueryData(["workspace", scope.authContext, scope.facilityId, data.id], data);
      queryClient.invalidateQueries({ queryKey: ["workspaces"] });
      flushSync(() => form.reset({ name: data.name, description: data.description, template: JSON.stringify(data.template, null, 2) }));
      toast.success(t(existing ? "workspace_updated" : "workspace_created"));
      if (!existing) navigate(`${scope.basePath}/${data.id}/edit`);
    },
  });

  const remove = useMutation({
    mutationFn: mutate(workspaceApi.delete, { pathParams: { id: existing?.id ?? "" } }),
    onSuccess: () => {
      queryClient.removeQueries({ queryKey: ["workspace", scope.authContext, scope.facilityId, existing?.id] });
      queryClient.invalidateQueries({ queryKey: ["workspaces"] });
      flushSync(() => {
        form.reset(form.getValues());
        setAccessState({ dirty: false, pending: false });
        setDeleteOpen(false);
      });
      toast.success(t("workspace_deleted"));
      navigate(scope.basePath);
    },
  });
  const busy = save.isPending || remove.isPending || accessState.pending;

  const formatTemplate = () => {
    try {
      form.setValue("template", JSON.stringify(parseTemplate(form.getValues("template")), null, 2), { shouldDirty: true, shouldValidate: true });
    } catch {
      form.setError("template", { message: t("workspace_template_invalid") }, { shouldFocus: true });
    }
  };

  return (
    <Page title={title} hideTitleOnPage>
      <div className="mx-auto max-w-6xl space-y-6 px-3 py-6 sm:px-0">
        <div className="flex flex-wrap items-center gap-3">
          <Button asChild variant="outline" size="sm" disabled={busy}>
            <Link href={scope.basePath} basePath="/" onClick={(event) => { if (busy) event.preventDefault(); }}>
              <ArrowLeft className="size-4" />{t("back")}
            </Link>
          </Button>
          <h1 className="flex-1 text-2xl font-semibold tracking-tight">{title}</h1>
          <Badge variant="secondary">{t(scope.authContext === "facility" ? "this_facility" : "workspace_instance_scope")}</Badge>
        </div>

        {!canWrite && <Alert><AlertDescription>{t("workspace_read_only")}</AlertDescription></Alert>}

        <Form {...form}>
          <form noValidate onSubmit={form.handleSubmit((values) => { if (canWrite && !busy) save.mutate(values); })} className="space-y-6">
            <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.6fr)]">
              <section className="space-y-5" aria-labelledby="workspace-details-heading">
                <div>
                  <h2 id="workspace-details-heading" className="font-semibold">{t("workspace_details")}</h2>
                  <p className="mt-1 text-sm text-gray-600">{t(scope.authContext === "facility" ? "workspace_facility_description" : "workspace_instance_description")}</p>
                </div>
                <FormField control={form.control} name="name" render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t("name")}</FormLabel>
                    <FormControl><Input {...field} readOnly={!canWrite} disabled={busy} autoComplete="off" /></FormControl>
                    <FormMessage />
                  </FormItem>
                )} />
                <FormField control={form.control} name="description" render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t("description")}</FormLabel>
                    <FormControl><Textarea {...field} readOnly={!canWrite} disabled={busy} rows={5} /></FormControl>
                    <FormDescription>{t("workspace_description_hint")}</FormDescription>
                    <FormMessage />
                  </FormItem>
                )} />
                {scope.authContext === "facility" && !existing && <Alert><AlertDescription>{t("workspace_access_after_create")}</AlertDescription></Alert>}
              </section>
              <section className="min-w-0 rounded-lg border bg-white p-4 sm:p-5">
                <FormField control={form.control} name="template" render={({ field }) => (
                  <FormItem>
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <FormLabel className="flex items-center gap-2 text-base"><Braces className="size-4" />{t("workspace_template")}</FormLabel>
                      {canWrite && <Button type="button" variant="outline" size="sm" onClick={formatTemplate} disabled={busy}>{t("workspace_format_json")}</Button>}
                    </div>
                    <FormDescription>{t("workspace_template_hint")}</FormDescription>
                    <FormControl><Textarea {...field} readOnly={!canWrite} disabled={busy} spellCheck={false} autoCapitalize="off" autoCorrect="off" rows={18} className="mt-3 min-h-80 resize-y font-mono text-sm leading-6" /></FormControl>
                    <FormMessage />
                  </FormItem>
                )} />
              </section>
            </div>

            {save.isError && <Alert variant="destructive"><AlertDescription>{t("workspace_save_error")}</AlertDescription></Alert>}
            {canWrite && (
              <div className="flex flex-wrap items-center justify-end gap-3 border-t pt-4">
                <span className="mr-auto text-sm text-gray-500">{t(form.formState.isDirty ? "workspace_unsaved_changes" : "no_changes_to_save")}</span>
                <Button type="submit" disabled={busy || (!!existing && !form.formState.isDirty)}>
                  {save.isPending && <Loader2 className="size-4 animate-spin" />}
                  {t(existing ? "save_changes" : "create_workspace")}
                </Button>
              </div>
            )}
          </form>
        </Form>

        {existing && scope.authContext === "facility" && canWrite && (
          <WorkspaceOrganizationsField scope={scope} workspaceId={existing.id} disabled={save.isPending || remove.isPending} onStateChange={setAccessState} />
        )}

        {existing && canWrite && (
          <div className="flex flex-wrap items-center justify-between gap-4 border-t pt-5">
            <p className="text-sm text-gray-600">{t("workspace_delete_hint")}</p>
            <AlertDialog open={deleteOpen} onOpenChange={(open) => { if (!remove.isPending) setDeleteOpen(open); }}>
              <AlertDialogTrigger asChild><Button variant="outline" disabled={busy}><Trash2 className="size-4" />{t("delete_workspace")}</Button></AlertDialogTrigger>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>{t("delete_workspace")}</AlertDialogTitle>
                  <AlertDialogDescription>{t("workspace_delete_confirm", { name: existing.name })}</AlertDialogDescription>
                </AlertDialogHeader>
                {remove.isError && <Alert variant="destructive"><AlertDescription>{t("workspace_delete_error")}</AlertDescription></Alert>}
                <AlertDialogFooter>
                  <AlertDialogCancel disabled={remove.isPending}>{t("cancel")}</AlertDialogCancel>
                  <AlertDialogAction disabled={busy} onClick={(event) => { event.preventDefault(); if (!busy && canWrite) remove.mutate(undefined); }}>
                    {remove.isPending && <Loader2 className="size-4 animate-spin" />}{t("delete")}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </div>
        )}
      </div>
    </Page>
  );
}

