                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{t("description")}</FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          readOnly={!canWrite}
                          disabled={busy}
                          rows={5}
                        />
                      </FormControl>
                      <FormDescription>
                        {t("workspace_description_hint")}
