                  >
                    {remove.isPending && (
                      <Loader2 className="size-4 animate-spin" />
                    )}
                    {t("delete")}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </div>
        )}
      </div>
    </Page>
  );
}
  };
};
