            )}
          </Badge>
        </div>

        {!canWrite && (
          <Alert>
            <AlertDescription>{t("workspace_read_only")}</AlertDescription>
          </Alert>
        )}

        <Form {...form}>
          <form
            noValidate
            onSubmit={form.handleSubmit((values) => {
              if (canWrite && !busy) save.mutate(values);
            })}
            className="space-y-6"
          >
            <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.6fr)]">
              <section
                className="space-y-5"
                aria-labelledby="workspace-details-heading"
              >
                <div>
                  <h2 id="workspace-details-heading" className="font-semibold">
                    {t("workspace_details")}
                  </h2>
                  <p className="mt-1 text-sm text-gray-600">
                    {t(
                      scope.authContext === "facility"
                        ? "workspace_facility_description"
                        : "workspace_instance_description",
                    )}
                  </p>
                </div>
                <FormField
                  control={form.control}
                  name="name"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{t("name")}</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          readOnly={!canWrite}
                          disabled={busy}
                          autoComplete="off"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{t("description")}</FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          readOnly={!canWrite}
                          disabled={busy}
                          rows={5}
                        />
                      </FormControl>
                      <FormDescription>
                        {t("workspace_description_hint")}
                      </FormDescription>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                {scope.authContext === "facility" && !existing && (
                  <Alert>
                    <AlertDescription>
                      {t("workspace_access_after_create")}
                    </AlertDescription>
                  </Alert>
                )}
              </section>
              <section className="min-w-0 rounded-lg border bg-white p-4 sm:p-5">
                <FormField
