                            onClick={formatTemplate}
                            disabled={busy}
                          >
                            {t("workspace_format_json")}
                          </Button>
                        )}
                      </div>
                      <FormDescription>
                        {t("workspace_template_hint")}
                      </FormDescription>
                      <FormControl>
                        <Textarea
                          {...field}
                          readOnly={!canWrite}
                          disabled={busy}
                          spellCheck={false}
                          autoCapitalize="off"
                          autoCorrect="off"
                          rows={18}
                          className="mt-3 min-h-80 resize-y font-mono text-sm leading-6"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </section>
            </div>

