    ).toBeVisible();
    await expect(
      page.getByRole("link", { name: anotherFacility.data.name, exact: true }),
    ).toHaveCount(0);
    await expect(
      page.getByRole("link", { name: instance.data.name, exact: true }),
    ).toHaveCount(0);
