for (const failure of ["request failure", "different scope"] as const) {
  test(`an edit ${failure} cannot become a new workspace`, async ({ page }) => {
    const record = workspace("facility", faker.string.uuid());
    const api = await mockWorkspaceApi(page, {
      records: [record],
      failedId: failure === "request failure" ? record.data.id : undefined,
    });
    await page.goto(`/admin/workspaces/${record.data.id}/edit`);
    await expect(page.getByRole("alert")).toContainText(
      "Unable to load this workspace",
    );
    await expect(
      page.getByRole("textbox", { name: "Name", exact: true }),
    ).toHaveCount(0);
    await expect(
      page.getByRole("button", { name: "Create workspace", exact: true }),
    ).toHaveCount(0);
    await page.getByRole("button", { name: "Try Again", exact: true }).click();
    await expect(page.getByRole("alert")).toContainText(
      "Unable to load this workspace",
    );
    expect(api.writes).toHaveLength(0);
  });
}

for (const hasRootPermission of [false, true]) {
  test(`facility workspace editing ${hasRootPermission ? "allows root" : "rejects department-only"} write permission`, async ({
    page,
  }) => {
    const facilityId = faker.string.uuid();
    const record = workspace("facility", facilityId);
    const api = await mockWorkspaceApi(page, {
      facilityId,
      records: [record],
      isSuperuser: false,
      rootPermissions: hasRootPermission
        ? ["can_read_workspace", "can_write_workspace"]
        : [],
    });
    await page.goto(
      `/facility/${facilityId}/settings/workspaces/${record.data.id}/edit`,
    );
    const description = page.getByRole("textbox", {
      name: "Description",
      exact: true,
    });
    await expect(description).toHaveValue(record.data.description);
    if (hasRootPermission) {
      const updatedDescription = faker.lorem.sentence();
      await description.fill(updatedDescription);
      await page
        .getByRole("button", { name: "Save Changes", exact: true })
        .click();
      await expect(
        page.getByText("Workspace updated", { exact: true }),
      ).toBeVisible();
      expect(api.writes).toHaveLength(1);
      expect(api.writes[0]).toMatchObject({
        method: "PUT",
        body: { description: updatedDescription },
      });
    } else {
      await expect(description).toHaveAttribute("readonly", "");
      await expect(
        page.getByRole("button", { name: "Save Changes", exact: true }),
      ).toHaveCount(0);
      await expect(
        page.getByRole("button", { name: "Delete workspace", exact: true }),
      ).toHaveCount(0);
      await expect(
        page.getByRole("button", { name: "Save access", exact: true }),
      ).toHaveCount(0);
      expect(api.writes).toHaveLength(0);
    }
  });
}
