from django.db.models import Q

from care.emr.models.organization import FacilityOrganizationUser
from care.security.authorization.base import (
    AuthorizationController,
    AuthorizationHandler,
)
from care.security.permissions.workspace import WorkspacePermissions


class WorkspaceAccess(AuthorizationHandler):
    def can_access_facility_workspace(self, user, facility, workspace, read_only):
        """
        Permission to access a workspace for a specific facility
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
            return self.check_permission_in_facility_organization(
                permission,
                user,
                facility=facility,
                orgs=workspace.internal_organization_cache,
            )
        permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission, user, facility=facility, root=True
        )

    def can_access_facility_organization_workspace(
        self, user, facility_organization, read_only
    ):
        """
        Permission to access a workspace for a specific facility organization
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
        else:
            permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission,
            user,
            facility=facility_organization.facility,
            orgs=[*facility_organization.parent_cache, facility_organization.id],
        )

    def can_access_user_workspace_in_facility(self, user, facility, read_only):
        """
        Permission to write a workspace for a specific facility as a user
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
        else:
            permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission,
            user,
            facility=facility,
        )

    def get_filtered_workspaces(self, qs, user):
        if user.is_superuser:
            return qs
        roles = self.get_role_from_permissions(
            [WorkspacePermissions.can_read_workspace.name]
        )
        facility_organization_ids = list(
            FacilityOrganizationUser.objects.filter(
                user=user, role_id__in=roles
            ).values_list("organization_id", flat=True)
        )
        write_roles = self.get_role_from_permissions(
            [WorkspacePermissions.can_write_workspace.name]
        )
        writable_facility_ids = FacilityOrganizationUser.objects.filter(
            user=user,
            role_id__in=write_roles,
            organization__org_type="root",
        ).values_list("organization__facility_id", flat=True)
        return qs.filter(
            Q(auth_context="instance")
            | Q(internal_organization_cache__overlap=facility_organization_ids)
            | Q(auth_context="user", created_by=user)
            | Q(auth_context="facility", facility_id__in=writable_facility_ids)
        )


AuthorizationController.register_internal_controller(WorkspaceAccess)
from django.core.cache import cache
from django.core.exceptions import PermissionDenied
from django.db import transaction
from django_filters import rest_framework as filters
from django_filters.rest_framework import DjangoFilterBackend
from drf_spectacular.utils import extend_schema
from pydantic import UUID4, BaseModel
from rest_framework.decorators import action
from rest_framework.response import Response

from care.emr.api.viewsets.base import EMRModelViewSet
from care.emr.models.organization import FacilityOrganization
from care.emr.models.workspace import (
    Workspace,
    WorkspaceFacilityOrganization,
    WorkSpaceUserDefault,
)
from care.emr.resources.facility_organization.spec import FacilityOrganizationReadSpec
from care.emr.resources.workspace.spec import (
    WorkspaceAuthContext,
    WorkspaceCreateSpec,
    WorkspaceMinimalReadSpec,
    WorkspaceReadSpec,
    WorkspaceUpdateSpec,
)
from care.facility.models.facility import Facility
from care.security.authorization.base import AuthorizationController
from care.utils.shortcuts import get_object_or_404


class WorkspaceFilter(filters.FilterSet):
    name = filters.CharFilter(field_name="name", lookup_expr="icontains")
    auth_context = filters.CharFilter(field_name="auth_context", lookup_expr="iexact")
    facility = filters.UUIDFilter(field_name="facility__external_id")


class WorkspaceViewSet(EMRModelViewSet):
    database_model = Workspace
    pydantic_model = WorkspaceCreateSpec
    pydantic_update_model = WorkspaceUpdateSpec
    pydantic_read_model = WorkspaceReadSpec
    filterset_class = WorkspaceFilter
    filter_backends = [DjangoFilterBackend]

    def authorize_create(self, instance):
        if (
            instance.auth_context == WorkspaceAuthContext.instance
            and not self.request.user.is_superuser
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.facility:
            facility = get_object_or_404(Facility, external_id=instance.facility)
            if not AuthorizationController.call(
                "can_access_facility_workspace",
                self.request.user,
                facility,
                None,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.facility_organization:
            facility_organization = get_object_or_404(
                FacilityOrganization, external_id=instance.facility_organization
            )
            if not AuthorizationController.call(
                "can_access_facility_organization_workspace",
                self.request.user,
                facility_organization,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.user:
            facility = get_object_or_404(Facility, external_id=instance.facility)
            if not AuthorizationController.call(
                "can_access_user_workspace_in_facility",
                self.request.user,
                facility,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")

        return super().authorize_create(instance)

    def authorize_update(self, request_obj, model_instance):
        if (
            model_instance.auth_context == WorkspaceAuthContext.instance
            and not self.request.user.is_superuser
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.facility
            and not AuthorizationController.call(
                "can_access_facility_workspace",
                self.request.user,
                model_instance.facility,
                None,
                read_only=False,
            )
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.facility_organization
            and not AuthorizationController.call(
                "can_access_facility_organization_workspace",
                self.request.user,
                model_instance.facility_organization,
                read_only=False,
            )
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.user
            and not AuthorizationController.call(
                "can_access_user_workspace_in_facility",
                self.request.user,
                model_instance.facility,
                read_only=False,
            )
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.user
            and model_instance.created_by != self.request.user
        ):
            raise PermissionDenied("Only the creator of the workspace can update it")

    def authorize_destroy(self, instance):
        self.authorize_update(self.request, instance)

    def perform_create(self, instance):
        super().perform_create(instance)
        instance.sync_facility_org_cache()

    def get_queryset(self):
        queryset = super().get_queryset()
        return AuthorizationController.call(
            "get_filtered_workspaces", queryset, self.request.user
