import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowLeft, Braces, Loader2, Trash2 } from "lucide-react";
import { Link, navigate, useNavigationPrompt } from "raviger";
import { useState } from "react";
import { flushSync } from "react-dom";
import { useForm, useWatch } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import Page from "@/components/Common/Page";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

import { usePermissions } from "@/context/PermissionContext";
import FacilityOrganizationSelector from "@/pages/Facility/settings/organizations/components/FacilityOrganizationSelector";
import facilityOrganizationApi from "@/types/facilityOrganization/facilityOrganizationApi";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import {
  WORKSPACE_AUTH_CONTEXTS,
  WorkspaceAuthContext,
  WorkspaceRead,
  WorkspaceScope,
  WorkspaceTemplate,
} from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";

import { WorkspaceOrganizationsField } from "./WorkspaceOrganizationsField";
import { WorkspaceDefaults } from "./WorkspaceDefaults";

interface WorkspaceFormValues {
  name: string;
  description: string;
  template: string;
  authContext: WorkspaceAuthContext;
  departmentId: string;
}

interface WorkspaceFormProps {
  scope: WorkspaceScope;
  existing?: WorkspaceRead;
  canWrite: boolean;
  initialContext?: WorkspaceAuthContext;
  allowedContexts: WorkspaceAuthContext[];
}

function parseTemplate(value: string): WorkspaceTemplate {
  const parsed: unknown = JSON.parse(value);
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Expected a JSON object");
  }
  return parsed as WorkspaceTemplate;
}

export function WorkspaceForm({
  scope,
  existing,
  canWrite,
  initialContext,
  allowedContexts,
}: WorkspaceFormProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { isSuperAdmin } = usePermissions();
  const [accessState, setAccessState] = useState({
    dirty: false,
    pending: false,
  });
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [defaultsState, setDefaultsState] = useState({ dirty: false, pending: false });
  const schema = z.object({
    name: z
      .string()
      .trim()
      .min(1, t("workspace_name_required"))
      .max(255, t("workspace_name_too_long")),
    description: z.string(),
    template: z.string().superRefine((value, ctx) => {
      try {
        parseTemplate(value);
      } catch {
        ctx.addIssue({
          code: "custom",
          message: t("workspace_template_invalid"),
        });
      }
    }),
    authContext: z.enum(WORKSPACE_AUTH_CONTEXTS),
    departmentId: z.string(),
  }).superRefine((values, ctx) => {
    if (values.authContext === "facility_organization" && !values.departmentId) {
      ctx.addIssue({ code: "custom", path: ["departmentId"], message: t("workspace_department_required") });
    }
  });
  const form = useForm<WorkspaceFormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      name: existing?.name ?? "",
      description: existing?.description ?? "",
      template: JSON.stringify(existing?.template ?? {}, null, 2),
      authContext: existing?.auth_context ?? initialContext ?? scope.authContext,
      departmentId: existing?.facility_organization ?? "",
    },
  });
  const authContext = useWatch({ control: form.control, name: "authContext" });
  const departmentId = useWatch({ control: form.control, name: "departmentId" });
  const department = useQuery({
    queryKey: ["workspace-department", scope.facilityId, departmentId],
    queryFn: query(facilityOrganizationApi.get, { pathParams: { facilityId: scope.facilityId ?? "", organizationId: departmentId } }),
    enabled: scope.authContext === "facility" && authContext === "facility_organization" && !!departmentId,
    retry: false,
  });
  const canWriteDepartment = !!department.data && (isSuperAdmin || department.data.permissions.includes("can_write_workspace"));
  const returnPath = scope.authContext === "facility" && authContext !== "facility"
    ? `${scope.basePath}?context=${authContext}` : scope.basePath;
  const contextLabel = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };
  const contextDescription = {
    instance: t("workspace_instance_description"),
    facility: t("workspace_facility_description"),
    facility_organization: t("workspace_department_description"),
    user: t("workspace_personal_description"),
  };

  const title = t(
    existing
      ? canWrite
        ? "edit_workspace"
        : "view_workspace"
      : "create_workspace",
  );
  const dirty = (canWrite && (form.formState.isDirty || accessState.dirty)) || defaultsState.dirty;
  useNavigationPrompt(dirty, t("unsaved_changes_warning"));

  const save = useMutation({
    mutationFn: (values: WorkspaceFormValues) => {
      const body = {
        name: values.name,
        description: values.description,
        template: parseTemplate(values.template),
      };
      return existing
        ? mutate(workspaceApi.update, { pathParams: { id: existing.id } })(body)
        : mutate(workspaceApi.create)({
            ...body,
            auth_context: values.authContext,
            ...(scope.authContext === "facility"
              ? { facility: scope.facilityId }
              : {}),
            ...(values.authContext === "facility_organization" ? { facility_organization: values.departmentId } : {}),
          });
    },
    onSuccess: (data) => {
      queryClient.setQueryData(
        ["workspace", "configuration", scope.authContext, scope.facilityId, data.id],
        data,
      );
      queryClient.invalidateQueries({ queryKey: ["workspaces"] });
      flushSync(() =>
        form.reset({
          name: data.name,
          description: data.description,
          template: JSON.stringify(data.template, null, 2),
          authContext: data.auth_context,
          departmentId: data.facility_organization ?? "",
        }),
      );
      toast.success(t(existing ? "workspace_updated" : "workspace_created"));
      if (!existing) navigate(`${scope.basePath}/${data.id}/edit`);
    },
  });

  const remove = useMutation({
    mutationFn: mutate(workspaceApi.delete, {
      pathParams: { id: existing?.id ?? "" },
    }),
    onSuccess: () => {
      queryClient.removeQueries({
        queryKey: [
          "workspace",
          "configuration",
          scope.authContext,
          scope.facilityId,
          existing?.id,
        ],
      });
      queryClient.invalidateQueries({ queryKey: ["workspaces"] });
      flushSync(() => {
        form.reset(form.getValues());
        setAccessState({ dirty: false, pending: false });
        setDefaultsState({ dirty: false, pending: false });
        setDeleteOpen(false);
      });
      toast.success(t("workspace_deleted"));
      navigate(returnPath);
