  const save = useMutation({
    mutationFn: mutate(workspaceApi.setDefaultAttributes, {
      pathParams: { id: workspaceId },
    }),
    onSuccess: (_, variables) => {
      const attribute = variables.attribute ?? null;
      queryClient.setQueryData<WorkspaceDefault[]>(queryKey, (current) => [
        ...(current ?? []).filter((item) => item.attribute !== attribute),
        { attribute, value: variables.value },
      ]);
      form.reset({ attribute: "", value: "" });
      setEditor(null);
      toast.success(t("workspace_default_saved"));
      return queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults"],
      });
    },
  });
  const reset = useMutation({
    mutationFn: mutate(workspaceApi.resetDefaultAttributes, {
      pathParams: { id: workspaceId },
    }),
    onSuccess: (_, variables) => {
      queryClient.setQueryData<WorkspaceDefault[]>(queryKey, (current) =>
        (current ?? []).filter(
          (item) => item.attribute !== (variables.attribute ?? null),
        ),
      );
      toast.success(t("workspace_default_removed"));
