                          }
                        }}
                      >
                        {reset.isPending &&
                          reset.variables.attribute === item.attribute && (
                            <Loader2 className="size-4 animate-spin" />
                          )}
                        {t("remove")}
                      </Button>
                    </div>
                  </li>
                );
              })}
            </ul>
          ) : (
            <p className="rounded-md border border-dashed p-4 text-sm text-gray-500">
              {t("workspace_no_defaults")}
