          )}
          {reset.isError && (
            <Alert variant="destructive">
              <AlertDescription>
                {t("workspace_default_remove_error")}
              </AlertDescription>
            </Alert>
          )}
          {editor && (
            <Form {...form}>
              <form
                noValidate
                className="space-y-4 border-t pt-4"
                onSubmit={form.handleSubmit((values) => {
                  if (!busy) {
                    save.mutate({
                      attribute:
                        editor.mode === "edit"
                          ? editor.attribute
                          : values.attribute || null,
                      value: values.value,
                    });
                  }
                })}
              >
                <h3 className="text-sm font-semibold">
                  {t(
                    editor.mode === "add"
                      ? "workspace_add_default"
                      : "workspace_edit_default",
                  )}
                </h3>
                <div className="grid gap-4 sm:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="attribute"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>
                          {t("workspace_default_attribute")}
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            disabled={busy}
                            readOnly={editor.mode === "edit"}
                            autoComplete="off"
                            maxLength={255}
                            placeholder={t("workspace_default_slot")}
                          />
                        </FormControl>
                        <FormDescription>
                          {t("workspace_default_attribute_hint")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="value"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t("value")}</FormLabel>
                        <FormControl>
                          <Textarea
                            {...field}
                            disabled={busy}
                            maxLength={255}
                            rows={2}
                          />
                        </FormControl>
                        <FormDescription>
                          {t("workspace_default_value_hint")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
                {save.isError && (
                  <Alert variant="destructive">
                    <AlertDescription>
