test("department creation checks the selected department and keeps ownership fixed", async ({
  page,
}) => {
  const api = await mockWorkspaceApi(page, {
    isSuperuser: false,
    organizationPermissions: [
      ["can_read_workspace"],
      ["can_read_workspace", "can_write_workspace"],
    ],
  });
  const basePath = `/facility/${api.facilityId}/settings/workspaces`;
  const name = `Department workspace ${faker.string.alphanumeric(8)}`;
  const create = page.getByRole("button", {
    name: "Create workspace",
    exact: true,
  });

  await page.goto(basePath);
  await page
    .getByRole("tab", { name: "Department workspaces", exact: true })
    .click();
  await page
    .getByRole("link", { name: "Create workspace", exact: true })
    .click();
  await expect(
    page.getByRole("combobox", { name: "Workspace ownership", exact: true }),
  ).toHaveText("Department workspace");
  await page.getByRole("textbox", { name: "Name", exact: true }).fill(name);

  await test.step("Missing or read-only department cannot create a workspace", async () => {
    await create.click();
    await expect(
      page.getByText("Select the department that owns this workspace.", {
        exact: true,
      }),
    ).toBeVisible();
    expect(api.writes).toHaveLength(0);
    await page
      .getByRole("combobox", { name: "Select Department", exact: true })
      .click();
    await page
      .getByRole("option", { name: api.organizations[0].name, exact: true })
      .click();
    await expect(
      page.getByText(
        "You need workspace write access in the selected department.",
        { exact: true },
      ),
    ).toBeVisible();
    await create.click();
    expect(api.writes).toHaveLength(0);
  });

  await test.step("A writable department is recorded as the owner", async () => {
    await page
      .getByRole("combobox", { name: api.organizations[0].name, exact: true })
      .click();
    await page
      .getByRole("option", { name: api.organizations[1].name, exact: true })
      .click();
    await create.click();
    await page.waitForURL(new RegExp(`${basePath}/[\\da-f-]+/edit$`));
    expect(api.writes).toEqual([
      {
        method: "POST",
        pathname: "/api/v1/workspace/",
        body: {
          name,
          description: "",
          template: {},
          auth_context: "facility_organization",
          facility: api.facilityId,
          facility_organization: api.organizations[1].id,
        },
      },
    ]);
    await expect(
      page.getByRole("combobox", { name: "Workspace ownership", exact: true }),
    ).toHaveCount(0);
    await expect(
      page.getByText(api.organizations[1].name, { exact: true }),
    ).toBeVisible();
    await expect(
      page.getByRole("region", {
        name: "Departments with access",
        exact: true,
      }),
    ).toHaveCount(0);
    await page.reload();
    await expect(
      page.getByText(api.organizations[1].name, { exact: true }),
    ).toBeVisible();
  });

  await test.step("Editing configuration preserves the owner and returns to its list", async () => {
    await page
      .getByRole("textbox", { name: "Name", exact: true })
      .fill(`${name} revised`);
    await page
      .getByRole("button", { name: "Save Changes", exact: true })
      .click();
    await expect(
      page.getByText("Workspace updated", { exact: true }),
    ).toBeVisible();
    expect(api.writes[1]).toEqual({
      method: "PUT",
      pathname: `/api/v1/workspace/${api.records[0].data.id}/`,
      body: { name: `${name} revised`, description: "", template: {} },
    });
    await expect(
      page.getByRole("button", { name: "Delete workspace", exact: true }),
    ).toBeVisible();
    await page.getByRole("link", { name: "Back", exact: true }).click();
    await expect(
      page.getByRole("tab", { name: "Department workspaces", exact: true }),
    ).toHaveAttribute("aria-selected", "true");
    await expect(
      page.getByRole("link", { name: `${name} revised`, exact: true }),
    ).toBeVisible();
  });
});

