  foreign.data.permissions = ["can_read_workspace"];
  const otherFacility = workspace("user", faker.string.uuid());
  otherFacility.data.created_by = owner;
  const facilityWorkspace = workspace("facility", facilityId);
  const departmentWorkspace = workspace("facility_organization", facilityId);
  const api = await mockWorkspaceApi(page, {
    facilityId,
    userId: owner.id,
    records: [
      own,
      foreign,
      otherFacility,
      facilityWorkspace,
      departmentWorkspace,
    ],
  });
  const basePath = `/facility/${facilityId}/settings/workspaces`;

  await test.step("Switching to My workspaces resets pagination and excludes other owners and scopes", async () => {
    await page.goto(`${basePath}?page=2`);
    await page.getByRole("tab", { name: "My workspaces", exact: true }).click();
    await expect(
      page.getByRole("link", { name: own.data.name, exact: true }),
    ).toBeVisible();
    for (const excluded of [
      foreign,
      otherFacility,
      facilityWorkspace,
      departmentWorkspace,
    ]) {
      await expect(
        page.getByRole("link", { name: excluded.data.name, exact: true }),
      ).toHaveCount(0);
    }
    const personalList = api.reads.find(
      (url) =>
        url.pathname === "/api/v1/workspace/" &&
        url.searchParams.get("auth_context") === "user",
    );
    expect(personalList?.searchParams.get("facility")).toBe(facilityId);
    expect(personalList?.searchParams.get("created_by")).toBe(owner.id);
    expect(personalList?.searchParams.get("offset")).toBe("0");
  });

  await test.step("Personal creation retains ownership and returns to My workspaces", async () => {
    await page
      .getByRole("link", { name: "Create workspace", exact: true })
      .click();
    await expect(
      page.getByRole("combobox", { name: "Workspace ownership", exact: true }),
    ).toHaveText("Personal workspace");
    const name = `Personal workspace ${faker.string.alphanumeric(8)}`;
    await page.getByRole("textbox", { name: "Name", exact: true }).fill(name);
    await page
      .getByRole("button", { name: "Create workspace", exact: true })
      .click();
    await page.waitForURL(new RegExp(`${basePath}/[\\da-f-]+/edit$`));
    expect(api.writes[0]).toEqual({
      method: "POST",
      pathname: "/api/v1/workspace/",
      body: {
        name,
        description: "",
        template: {},
        auth_context: "user",
        facility: facilityId,
      },
    });
    await expect(
      page.getByRole("button", { name: "Delete workspace", exact: true }),
    ).toBeVisible();
    await page.getByRole("link", { name: "Back", exact: true }).click();
    await expect(
      page.getByRole("tab", { name: "My workspaces", exact: true }),
    ).toHaveAttribute("aria-selected", "true");
    await expect(page.getByRole("link", { name, exact: true })).toBeVisible();
  });

  await test.step("Opening another owner's workspace does not grant a superuser write controls", async () => {
    await page.goto(`${basePath}/${foreign.data.id}/edit`);
    await expect(
      page.getByRole("textbox", { name: "Name", exact: true }),
    ).toHaveValue(foreign.data.name);
    await expect(
      page.getByRole("textbox", { name: "Name", exact: true }),
    ).toHaveAttribute("readonly", "");
    await expect(
      page.getByRole("button", { name: "Save Changes", exact: true }),
    ).toHaveCount(0);
    await expect(
      page.getByRole("button", { name: "Delete workspace", exact: true }),
    ).toHaveCount(0);
    await expect(
      page.getByRole("button", { name: "Add default", exact: true }),
    ).toBeVisible();
    expect(api.writes).toHaveLength(1);
  });
});

