import { useTranslation } from "react-i18next";

import { Skeleton } from "@/components/ui/skeleton";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import {
  EncounterWorkspaceCustomPage,
  isEncounterWidgetVisible,
} from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspaceWidget } from "./EncounterWorkspaceWidgets";

interface EncounterWorkspacePageProps {
  page: EncounterWorkspaceCustomPage;
}

export function EncounterWorkspacePage({ page }: EncounterWorkspacePageProps) {
  const { t } = useTranslation();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();

  if (isSelectedEncounterLoading) {
    return <Skeleton className="h-64 w-full" />;
  }
  if (!selectedEncounter) {
    return <p role="alert">{t("encounter_not_found")}</p>;
  }

  const columns = page.columns
    .map((column) => ({
      ...column,
      widgets: column.widgets.filter((widget) =>
        isEncounterWidgetVisible(widget, selectedEncounter.status),
      ),
    }))
    .filter((column) => column.widgets.length > 0);

  if (!columns.length) {
    return <p className="rounded-lg border border-dashed p-6 text-sm text-gray-600">{t("encounter_workspace_empty_page")}</p>;
  }

  return (
    <div className="@container">
      <div
        className="grid min-w-0 grid-cols-1 items-start gap-3 @xl:grid-cols-2 @4xl:grid-cols-[var(--workspace-columns)]"
        style={{ "--workspace-columns": columns.map(({ span }) => `minmax(0, ${span}fr)`).join(" ") } as React.CSSProperties}
      >
        {columns.map((column, columnIndex) => (
          <div key={columnIndex} className="min-w-0 space-y-3">
            {column.widgets.map((widget, widgetIndex) => (
              <EncounterWorkspaceWidget key={`${widgetIndex}:${widget.type}`} widget={widget} />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

import {
  Activity, ClipboardList, HeartPulse, LayoutDashboard, PanelsTopLeft, Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate, useQueryParams } from "raviger";
import { useEffect, useId } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";

import EncounterNavigation, { EncounterTab } from "@/pages/Encounters/EncounterNavigation";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  "stethoscope": Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  "activity": Activity,
  "heart-pulse": HeartPulse,
};
const BUILT_IN_WORKSPACE = "system";

interface EncounterWorkspaceContentProps {
  facilityId: string;
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({ facilityId, systemTabs, currentTab }: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const selectorId = useId();
  const [{ workspace: workspaceId }] = useQueryParams<{ workspace?: string }>();
  const { list, selected } = useEncounterWorkspaces(facilityId, workspaceId);
  const parsed = selected.data && !selected.isError
    ? parseEncounterWorkspaceTemplate(selected.data.template, Object.keys(systemTabs))
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed?.success) {
    for (const page of parsed.template.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab) tabs[page.key] = { ...systemTab, visible: !page.hidden && systemTab.visible !== false };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon: customPageIcons[page.icon ?? ""] ?? LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      }
    }
  }
  for (const [key, tab] of Object.entries(systemTabs)) {
    if (!Object.hasOwn(tabs, key)) tabs[key] = tab;
  }

  const firstVisibleTab = Object.keys(tabs).find((key) => tabs[key].visible !== false) ?? "updates";
  const activeTab = tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab) ? currentTab : firstVisibleTab;
  const isLoadingSelection = !!workspaceId && selected.isLoading;
  const options = [...(list.data ?? [])];
  if (selected.data && !selected.isError && !options.some(({ id }) => id === selected.data.id)) options.push(selected.data);

  const navigateToTab = (tab: string, workspace = workspaceId, replace = false) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    if (workspace) target.searchParams.set("workspace", workspace);
    else target.searchParams.delete("workspace");
    if (target.href !== window.location.href) navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (!isLoadingSelection && activeTab !== currentTab) navigateToTab(activeTab, workspaceId, true);
  });

  const scopeLabels = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-end gap-2">
        <Label htmlFor={selectorId}>{t("encounter_workspace")}</Label>
        <Select value={workspaceId ?? BUILT_IN_WORKSPACE} onValueChange={(value) => {
          const nextId = value === BUILT_IN_WORKSPACE ? undefined : value;
          const next = options.find(({ id }) => id === nextId);
          const template = next && parseEncounterWorkspaceTemplate(next.template, Object.keys(systemTabs));
          const page = template?.success && template.template.pages.find((entry) => entry.kind === "custom" || (!entry.hidden && systemTabs[entry.key]?.visible !== false));
          navigateToTab(page ? page.key : "updates", nextId);
        }}>
          <SelectTrigger id={selectorId} className="w-full sm:w-72"><SelectValue placeholder={t("encounter_workspace_loading")} /></SelectTrigger>
          <SelectContent>
            <SelectItem value={BUILT_IN_WORKSPACE}>{t("encounter_workspace_standard")}</SelectItem>
            {workspaceId && !options.some(({ id }) => id === workspaceId) && <SelectItem value={workspaceId} disabled>{t(isLoadingSelection ? "encounter_workspace_loading" : "encounter_workspace_unavailable")}</SelectItem>}
            {options.map((workspace) => <SelectItem key={workspace.id} value={workspace.id}>{workspace.name} · {scopeLabels[workspace.auth_context]}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {(list.isError || (!!workspaceId && selected.isError)) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t(selected.isError ? "encounter_workspace_load_error" : "encounter_workspace_list_error")}</span>
            <Button type="button" size="sm" variant="outline" onClick={() => { list.refetch(); if (workspaceId) selected.refetch(); }}>{t("try_again")}</Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && <Alert><AlertDescription>{t(parsed.error === "unsupported_schema" ? "encounter_workspace_schema_unsupported" : "encounter_workspace_invalid")}</AlertDescription></Alert>}
      {isLoadingSelection ? <Skeleton className="h-64 w-full" /> : (
        <EncounterNavigation tabs={tabs} currentTab={activeTab} onTabChange={(tab) => navigateToTab(tab)} />
      )}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";

import useAuthUser from "@/hooks/useAuthUser";

import { WorkspaceRead } from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";
import query, { callApi } from "@/Utils/request/query";

export function useEncounterWorkspaces(facilityId: string, workspaceId?: string) {
  const user = useAuthUser();
  const list = useQuery({
    queryKey: ["workspaces", "encounter", user.id, facilityId],
    queryFn: async ({ signal }) => {
      const filters = [
        { auth_context: "instance" },
        { auth_context: "facility", facility: facilityId },
        { auth_context: "facility_organization", facility: facilityId },
        { auth_context: "user", facility: facilityId, created_by: user.id },
      ];
      const responses = await Promise.all(
        filters.map((queryParams) =>
          query.paginated(workspaceApi.list, { queryParams, silent: true })({ signal }),
        ),
      );
      return responses.flatMap(({ results }) => results).filter(isEncounterConfiguration);
    },
    retry: false,
  });
  const selected = useQuery({
    queryKey: ["workspace", "encounter", user.id, facilityId, workspaceId],
    queryFn: async ({ signal }) => {
      const workspace = await callApi(workspaceApi.get, {
        pathParams: { id: workspaceId ?? "" },
        signal,
        silent: true,
      });
      if (
        (workspace.auth_context !== "instance" && workspace.facility !== facilityId) ||
        (workspace.auth_context === "user" && workspace.created_by?.id !== user.id)
      ) {
        throw new Error("Workspace is outside the current encounter scope");
      }
      return workspace;
    },
    enabled: !!workspaceId,
    retry: false,
  });

  return { list, selected };
}

function isEncounterConfiguration(workspace: WorkspaceRead) {
  return "schema_version" in workspace.template || "pages" in workspace.template;
}

