import { z } from "zod";

import { EncounterStatus } from "@/types/emr/encounter/encounter";

/** Existing encounter pages keep their application-owned layout and behavior. */
export const ENCOUNTER_SYSTEM_PAGE_KEYS = [
  "updates",
  "responses",
  "observations",
  "medicines",
  "service_requests",
  "diagnostic_reports",
  "plots",
  "files",
  "notes",
  "devices",
  "consents",
] as const;

const RESERVED_ENCOUNTER_ROUTE_KEYS = [
  "prescriptions",
  "questionnaire",
  "questionnaire_response",
  "type",
  "report",
  "constructor",
  "prototype",
];

export type SupportedEncounterWidgetType =
  "allergies" | "symptoms" | "diagnosis";

export interface EncounterWorkspaceWidget {
  type: string;
  title?: string;
  config?: Record<string, unknown>;
  visible_when?: { "encounter.status": EncounterStatus[] };
}

export interface EncounterWorkspaceColumn {
  span: number;
  widgets: EncounterWorkspaceWidget[];
}

export interface EncounterWorkspaceCustomPage {
  key: string;
  kind: "custom";
  title: string;
  icon?: string;
  columns: EncounterWorkspaceColumn[];
}

export interface EncounterWorkspaceSystemPage {
  key: string;
  kind: "system";
  hidden?: boolean;
}

export type EncounterWorkspacePage =
  EncounterWorkspaceCustomPage | EncounterWorkspaceSystemPage;

export interface EncounterWorkspaceTemplate {
  schema_version: 1;
  pages: EncounterWorkspacePage[];
}

export type EncounterWorkspaceParseResult =
  | {
      success: true;
      template: EncounterWorkspaceTemplate;
      unsupportedWidgetTypes: string[];
    }
  | {
      success: false;
      error: "invalid_template" | "unsupported_schema";
    };

export function normalizeEncounterSystemPageKey(key: string): string {
  return key === "medications" ? "medicines" : key;
}

/** Aliases keep templates readable without creating separate clinical widgets. */
export function normalizeEncounterWidgetType(
  type: string,
): SupportedEncounterWidgetType | undefined {
  switch (type) {
    case "allergy":
    case "allergies":
      return "allergies";
    case "symptom":
    case "symptoms":
      return "symptoms";
    case "diagnosis":
    case "diagnoses":
    case "active_problems":
      return "diagnosis";
    default:
      return undefined;
  }
}

export function isEncounterWidgetVisible(
  widget: EncounterWorkspaceWidget,
  encounterStatus: string | undefined,
): boolean {
  const statuses = widget.visible_when?.["encounter.status"];
  return !statuses || statuses.some((status) => status === encounterStatus);
}

const titleSchema = z.string().trim().min(1).max(120);
const widgetSchema = z
  .object({
    type: z.string().regex(/^[a-z][a-z0-9_]{0,63}$/),
    title: titleSchema.optional(),
    config: z.record(z.string(), z.unknown()).optional(),
    visible_when: z
      .object({
        "encounter.status": z
          .array(z.enum(EncounterStatus))
          .min(1)
          .max(Object.values(EncounterStatus).length),
      })
      .strict()
      .optional(),
  })
  .strict();

const customPageSchema = z
  .object({
    key: z.string().regex(/^[a-z][a-z0-9_-]{0,63}$/),
    kind: z.literal("custom"),
    title: titleSchema,
    icon: z.string().min(1).max(64).optional(),
    columns: z
      .array(
        z
          .object({
            span: z.number().int().min(1).max(12),
            widgets: z.array(widgetSchema).max(50),
          })
          .strict(),
      )
      .min(1)
      .max(12)
      .refine(
        (columns) => columns.reduce((sum, col) => sum + col.span, 0) <= 12,
      ),
  })
  .strict();

const systemPageSchema = z
  .object({
    key: z.string().min(1).max(64),
    kind: z.literal("system"),
    hidden: z.boolean().optional(),
  })
  .strict();

const templateSchema = z
  .object({
    schema_version: z.literal(1),
    pages: z
      .array(z.discriminatedUnion("kind", [customPageSchema, systemPageSchema]))
      .min(1)
      .max(50),
  })
  .strict();

/**
 * Invalid templates leave the caller free to show the standard encounter.
 * Unknown widgets stay in the result so they can render an explicit placeholder.
 * System pages may be ordered or hidden, but cannot override their content.
 */
export function parseEncounterWorkspaceTemplate(
  input: unknown,
  additionalSystemPageKeys: readonly string[] = [],
): EncounterWorkspaceParseResult {
  if (
    input !== null &&
    typeof input === "object" &&
    !Array.isArray(input) &&
    "schema_version" in input &&
    input.schema_version !== 1
  ) {
    return { success: false, error: "unsupported_schema" };
  }

  const parsed = templateSchema.safeParse(input);
  if (!parsed.success) {
    return { success: false, error: "invalid_template" };
  }

  const systemKeys = new Set<string>([
    ...ENCOUNTER_SYSTEM_PAGE_KEYS,
    ...additionalSystemPageKeys.map(normalizeEncounterSystemPageKey),
  ]);
  const reservedCustomKeys = new Set([
    ...systemKeys,
    "medications",
    ...RESERVED_ENCOUNTER_ROUTE_KEYS,
  ]);
  const pageKeys = new Set<string>();
  const unsupportedWidgetTypes = new Set<string>();
  const pages: EncounterWorkspacePage[] = [];
  let widgetCount = 0;

  for (const page of parsed.data.pages) {
    const key = normalizeEncounterSystemPageKey(page.key);
    if (pageKeys.has(key)) {
      return { success: false, error: "invalid_template" };
    }
    pageKeys.add(key);

    if (page.kind === "system") {
      if (!systemKeys.has(key)) {
        return { success: false, error: "invalid_template" };
      }
      pages.push({ ...page, key });
      continue;
    }

    if (reservedCustomKeys.has(page.key)) {
      return { success: false, error: "invalid_template" };
    }
    for (const column of page.columns) {
      widgetCount += column.widgets.length;
      if (widgetCount > 200) {
        return { success: false, error: "invalid_template" };
      }
      for (const widget of column.widgets) {
        if (!normalizeEncounterWidgetType(widget.type)) {
          unsupportedWidgetTypes.add(widget.type);
        }
      }
    }
    pages.push(page);
  }

  return {
    success: true,
    template: { schema_version: 1, pages },
    unsupportedWidgetTypes: [...unsupportedWidgetTypes],
  };
}
# Playwright E2E Testing

E2E setup, commands, and workflows for the CARE frontend. See [`AGENTS.md`](../AGENTS.md) for the top-level agent guidance that links here, and [`tests/PLAYWRIGHT_GUIDE.md`](../tests/PLAYWRIGHT_GUIDE.md) for complete patterns covering form interactions, selectors, assertions, and helpers.

**Prerequisites:** Backend must be running on port 9000 (see [`local-development.md`](./local-development.md)), and a production build must exist (`npm run build`).

CI uses the `CARE_BACKEND_REF` default in [the Playwright workflow](../.github/workflows/playwright.yaml). It currently points to `ENG-737`, the companion backend required by questionnaire actions; restore `develop` once that dependency lands. Manual **Playwright Tests** runs can override it with the `backend_ref` input and run regardless of changed-file filters.

```bash
npm run playwright:install                              # Install browsers (first time)
npm run build                                           # Build app (tests run against production build)
npm run playwright:test                                 # Run all tests
npm run playwright:test -- tests/auth/login.spec.ts     # Run a single test file
npm run playwright:test -- -g "test name"               # Run tests matching a pattern
npm run playwright:test -- --workers=4                   # Run with 4 parallel workers
npm run playwright:test -- --shard=1/3                   # Run shard 1 of 3
npm run playwright:test:ui                              # Interactive Playwright UI mode
```

**Playwright E2E test credentials (local/test only; do not use on deployed instances)** (used in `tests/setup/*.setup.ts`):

| Storage State                    | Username         | Password   |
| -------------------------------- | ---------------- | ---------- |
| `tests/.auth/user.json`          | `admin`          | `admin`    |
| `tests/.auth/nurse.json`         | `care-nurse`     | `Ohcn@123` |
| `tests/.auth/facilityAdmin.json` | `care-fac-admin` | `Ohcn@123` |

## Running tests efficiently

- Use `--workers=4` for parallel execution (CI runs setup with 1 worker, then chromium with 4 workers)
- Use `--shard=N/TOTAL` to split across multiple processes
- Run specific test directories to iterate faster: `npx playwright test tests/auth/`
- The `setup` project runs first to authenticate test users and save storage state

## Database management for re-runs

Tests create data (patients, roles, locations, etc.) that can cause conflicts on re-run. Use the DB snapshot system:

```bash
# Set CARE_BACKEND_DIR to your care backend checkout (required for db-reset)
export CARE_BACKEND_DIR=/path/to/care

npm run playwright:db-reset      # First time: migrate + fixtures + snapshot (~30s)
npm run playwright:db-restore    # Before re-runs: restore clean state (~2s)
npm run playwright:db-snapshot   # Save current state as new baseline
npm run playwright:db-status     # Check snapshot info
```

The `globalSetup` automatically restores the DB snapshot before each local test run (skipped on CI). To set up for the first time:

```bash
npm run playwright:db-reset      # Creates snapshot with fixtures
npm run playwright:test           # Tests run against clean DB, auto-restores on next run
```

## Test structure

- `tests/setup/` — Authentication & fixture setup (runs before tests)
- `tests/auth/` — Login, session, homepage tests
- `tests/facility/` — Facility management, settings, patients, encounters
- `tests/admin/` — Admin panel tests
- `tests/organization/` — Organization management
- `tests/helper/` — Shared test utilities
- `tests/support/` — ID management (facility, patient, encounter IDs)

## Writing new tests

- Use `faker` for data generation — avoid hardcoded names/slugs that collide on re-run
- Use `Date.now()` or `faker.string.alphanumeric()` for unique identifiers
- Don't rely on cleanup — the DB snapshot system handles state reset
- Use `getFacilityId()`, `getPatientId()`, `getEncounterId()` from `tests/support/` for fixture IDs
import { faker } from "@faker-js/faker";
