import { useTranslation } from "react-i18next";

import { AllergyTable } from "@/components/Patient/allergy/AllergyTable";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import allergyIntoleranceApi from "@/types/emr/allergyIntolerance/allergyIntoleranceApi";
import { completedEncounterStatus } from "@/types/emr/encounter/encounter";

import { WorkspaceClinicalWidgetPanel } from "./WorkspaceClinicalWidgetPanel";
import { useWorkspaceClinicalQuery } from "./useWorkspaceClinicalQuery";

export function WorkspaceAllergiesWidget({ title }: { title?: string }) {
  const { t } = useTranslation();
  const { patientId, selectedEncounterId, selectedEncounter } = useEncounter();
  const status = selectedEncounter?.status;
  const queryState = useWorkspaceClinicalQuery(
    allergyIntoleranceApi.getAllergy,
    ["infinite-allergies", patientId, selectedEncounterId, status],
    patientId,
    {
      encounter:
        status && completedEncounterStatus.includes(status)
          ? selectedEncounterId
          : undefined,
    },
  );

  return (
    <WorkspaceClinicalWidgetPanel
      title={title ?? t("allergies")}
      questionnaire="allergy_intolerance"
      history="allergies"
      emptyMessage={t("no_allergies_recorded_description")}
      queryState={queryState}
    >
      <AllergyTable
        patientId={patientId}
        allergies={queryState.data?.pages.flatMap((page) => page.results) ?? []}
        showViewEncounter={false}
        compact
      />
    </WorkspaceClinicalWidgetPanel>
  );
}
