  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};
const BUILT_IN_WORKSPACE = "system";

interface EncounterWorkspaceContentProps {
  facilityId: string;
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  facilityId,
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const selectorId = useId();
  const [{ workspace: workspaceId }] = useQueryParams<{ workspace?: string }>();
  const { list, selected } = useEncounterWorkspaces(facilityId, workspaceId);
  const parsed =
    selected.data && !selected.isError
      ? parseEncounterWorkspaceTemplate(
          selected.data.template,
          Object.keys(systemTabs),
        )
      : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed?.success) {
    for (const page of parsed.template.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon: customPageIcons[page.icon ?? ""] ?? LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      }
    }
  }
  for (const [key, tab] of Object.entries(systemTabs)) {
    if (!Object.hasOwn(tabs, key)) tabs[key] = tab;
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection = !!workspaceId && selected.isLoading;
  const options = [...(list.data ?? [])];
  if (
    selected.data &&
    !selected.isError &&
    !options.some(({ id }) => id === selected.data.id)
  )
    options.push(selected.data);

  const navigateToTab = (
    tab: string,
    workspace: string | undefined,
    replace = false,
  ) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    if (workspace) target.searchParams.set("workspace", workspace);
    else target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (!isLoadingSelection && firstVisibleTab && activeTab !== currentTab)
      navigateToTab(activeTab, workspaceId, true);
  });

  const scopeLabels = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-end gap-2">
        <Label htmlFor={selectorId}>{t("encounter_workspace")}</Label>
        <Select
          value={workspaceId ?? BUILT_IN_WORKSPACE}
          onValueChange={(value) => {
            const nextId = value === BUILT_IN_WORKSPACE ? undefined : value;
            const next = options.find(({ id }) => id === nextId);
            const template =
              next &&
              parseEncounterWorkspaceTemplate(
                next.template,
                Object.keys(systemTabs),
              );
            const page =
              template?.success &&
              template.template.pages.find(
                (entry) =>
                  entry.kind === "custom" ||
                  (!entry.hidden && systemTabs[entry.key]?.visible !== false),
              );
            navigateToTab(page ? page.key : "updates", nextId);
          }}
        >
          <SelectTrigger id={selectorId} className="w-full sm:w-72">
            <SelectValue placeholder={t("encounter_workspace_loading")} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={BUILT_IN_WORKSPACE}>
              {t("encounter_workspace_standard")}
            </SelectItem>
            {workspaceId && !options.some(({ id }) => id === workspaceId) && (
              <SelectItem value={workspaceId} disabled>
                {t(
                  isLoadingSelection
                    ? "encounter_workspace_loading"
                    : "encounter_workspace_unavailable",
                )}
              </SelectItem>
            )}
            {options.map((workspace) => (
              <SelectItem key={workspace.id} value={workspace.id}>
                {workspace.name} · {scopeLabels[workspace.auth_context]}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {(list.isError || (!!workspaceId && selected.isError)) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>
              {t(
                selected.isError
                  ? "encounter_workspace_load_error"
                  : "encounter_workspace_list_error",
              )}
            </span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                list.refetch();
                if (workspaceId) selected.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.error === "unsupported_schema"
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab, workspaceId)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
