test("instance admins can validate, create, reopen, update, and delete a workspace", async ({
  page,
}, testInfo) => {
  const api = await mockWorkspaceApi(page);
  const name = `Workspace ${faker.word.words(2)} ${faker.string.alphanumeric(6)}`;
  const description = faker.lorem.sentence();
  const template = {
    sections: [{ id: "overview", enabled: true }],
    extensions: { nested: [1, null, "value"] },
  };
  const nameField = page.getByRole("textbox", { name: "Name", exact: true });
  const templateField = page.getByRole("textbox", {
    name: "Template (JSON)",
    exact: true,
  });

  await test.step("Reject malformed JSON before creating a configuration", async () => {
    await page.goto("/admin/workspaces");
    await page
      .getByRole("link", { name: "Create workspace", exact: true })
      .click();
    await nameField.fill(name);
    await page
      .getByRole("textbox", { name: "Description", exact: true })
      .fill(description);
    for (const invalidTemplate of ["{ invalid JSON }", "[]", "null"]) {
      await templateField.fill(invalidTemplate);
      await page
        .getByRole("button", { name: "Create workspace", exact: true })
        .click();
      await expect(
        page.getByText(
          "Enter valid JSON with an object at the top level. Arrays, null, and other values are not supported.",
          { exact: true },
        ),
      ).toBeVisible();
      expect(api.writes).toHaveLength(0);
    }
  });

  await test.step("Create and reload preserves arbitrary nested template properties", async () => {
    await templateField.fill(JSON.stringify(template));
    await page
      .getByRole("button", { name: "Create workspace", exact: true })
      .click();
    await page.waitForURL(/\/admin\/workspaces\/[\da-f-]+\/edit$/);
    expect(api.writes).toHaveLength(1);
    expect(api.writes[0]).toMatchObject({
      method: "POST",
      pathname: "/api/v1/workspace/",
      body: {
        name,
        description,
        template,
        auth_context: "instance",
      },
    });
    await page.reload();
    await expect(nameField).toHaveValue(name);
    await expect(templateField).toHaveValue(JSON.stringify(template, null, 2));
    await page.screenshot({
      path: testInfo.outputPath("workspace-desktop.png"),
      fullPage: true,
    });
    await page.setViewportSize({ width: 390, height: 844 });
    await page.screenshot({
      path: testInfo.outputPath("workspace-mobile.png"),
      fullPage: true,
    });
    await page.setViewportSize({ width: 1440, height: 1000 });
  });

  await test.step("Save updates the existing workspace while preserving scope", async () => {
    const updatedName = `${name} revised`;
    const updatedTemplate = {
      ...template,
      sections: [{ id: "overview", enabled: false }],
    };
    await nameField.fill(updatedName);
    await templateField.fill(JSON.stringify(updatedTemplate));
    await page
      .getByRole("button", { name: "Save Changes", exact: true })
      .click();
    await expect(
      page.getByText("Workspace updated", { exact: true }),
    ).toBeVisible();
    expect(api.writes).toHaveLength(2);
    expect(api.writes[1]).toMatchObject({
      method: "PUT",
      await route.fulfill({ json: { count: 0, results: [] } });
    },
  );

  return {
    actor,
    facility,
    patient,
    currentEncounter,
    pastEncounter,
    workspace,
    records,
    clinicalNames,
    clinicalReads,
    writes,
    basePath: `/facility/${facility.id}/patient/${patient.id}/encounter/${currentEncounter.id}`,
  };
}

test.describe("Encounter workspace rendering", () => {
  test("renders configured clinical data while retaining system pages and encounter navigation", async ({
    page,
  }) => {
    const fixture = await mockEncounterWorkspaceApi(page);
    await page.goto(`${fixture.basePath}/devices`);
    await expect(
      page.getByRole("tab", { name: "Devices", exact: true }),
    ).toBeVisible();
    await page
      .getByRole("combobox", { name: "Workspace", exact: true })
      .click();
    await page
      .getByRole("option", { name: new RegExp(fixture.workspace.name) })
      .click();
    await expect(page).toHaveURL(
      (url) =>
        url.pathname.endsWith("/rounds") &&
        url.searchParams.get("workspace") === fixture.workspace.id,
    );
    await expect(
      page.getByRole("heading", { name: "Ward rounds", exact: true }),
    ).toBeVisible();
    await expect(
      page.getByText(fixture.patient.name, { exact: true }).first(),
    ).toBeVisible();
    for (const [panel, clinicalType] of [
      ["Allergy review", "allergy_intolerance"],
      ["Symptoms today", "symptom"],
      ["Diagnoses", "diagnosis"],
    ] as const) {
      const region = page.getByRole("region", { name: panel, exact: true });
      await expect(
        region
          .getByText(fixture.clinicalNames.current[clinicalType], {
            exact: true,
          })
          .first(),
      ).toBeVisible();
      await expect(
        region.getByRole("link", { name: "Edit", exact: true }),
      ).toBeVisible();
    }
    await expect(
      page.getByText("Active encounter tools", { exact: true }),
    ).toBeVisible();
    await expect(
      page.getByText("Ward phone list", { exact: true }),
    ).toBeVisible();
    await expect(
      page
        .getByText("This widget is not supported yet.", { exact: true })
        .first(),
    ).toBeVisible();
    await expect(
      page.getByRole("tab", { name: "Devices", exact: true }),
    ).toHaveCount(0);
    await expect(
      page.getByRole("tab", { name: "Overview", exact: true }),
    ).toBeVisible();

    await test.step("Return to the configured page after opening a clinical form", async () => {
      await page
        .getByRole("region", { name: "Symptoms today", exact: true })
        .getByRole("link", { name: "Edit", exact: true })
        .click();
      await expect(page).toHaveURL(
        (url) =>
          url.pathname.endsWith("/questionnaire/symptom") &&
          url.searchParams.get("workspace") === fixture.workspace.id,
      );
      await expect(page.getByRole("alert")).toContainText("No data found");
      await page.getByRole("button", { name: "Back", exact: true }).click();
      await expect(page).toHaveURL(
        (url) =>
          url.pathname.endsWith("/rounds") &&
          url.searchParams.get("workspace") === fixture.workspace.id,
      );
      await expect(
        page.getByRole("heading", { name: "Ward rounds", exact: true }),
      ).toBeVisible();
    });

    await test.step("Keep clinical cards usable at a narrow width", async () => {
      await page.setViewportSize({ width: 390, height: 844 });
      await expect(
        page
          .getByRole("region", { name: "Symptoms today", exact: true })
          .getByText("Fever today", { exact: true })
          .first(),
      ).toBeVisible();
      await expect
        .poll(() =>
          page.evaluate(
            () => document.documentElement.scrollWidth - window.innerWidth,
          ),
        )
        .toBeLessThanOrEqual(0);
      await page.setViewportSize({ width: 1440, height: 1000 });
    });

    await page.getByRole("button", { name: /Encounter History/i }).click();
    await page
      .getByRole("dialog")
      .locator('button[aria-pressed="false"]')
      .click();
    await expect(page).toHaveURL(
      (url) =>
        url.searchParams.get("selectedEncounter") ===
          fixture.pastEncounter.id &&
        url.searchParams.get("workspace") === fixture.workspace.id,
    );
    const symptoms = page.getByRole("region", {
      name: "Symptoms today",
      exact: true,
    });
    await expect(
      symptoms.getByText("Cough last admission", { exact: true }).first(),
    ).toBeVisible();
    await expect(
      symptoms.getByText("Fever today", { exact: true }),
    ).toHaveCount(0);
    await expect(
      symptoms.getByRole("link", { name: "Edit", exact: true }),
    ).toHaveCount(0);
    await expect(
      page
        .getByRole("region", { name: "Diagnoses", exact: true })
        .getByText("Previous asthma", { exact: true })
        .first(),
    ).toBeVisible();
    await expect(
      page.getByText("Active encounter tools", { exact: true }),
    ).toHaveCount(0);

    await page
      .getByRole("button", { name: "Encounter Actions", exact: true })
      .click();
    await page
      .getByRole("dialog")
      .getByRole("option", { name: /^Medicines/ })
      .click();
