from care.emr.models import EMRBaseModel
from care.emr.models.organization import FacilityOrganization
from care.users.models import User

WORKSPACE_USER_DEFAULT_CACHE_KEY = "workspace_user_default:{user_id}"


class Workspace(EMRBaseModel):
    facility = models.ForeignKey(
        "facility.Facility", on_delete=models.CASCADE, null=True, blank=True
    )
    facility_organization = models.ForeignKey(
        "emr.FacilityOrganization", on_delete=models.CASCADE, null=True, blank=True
    )
    auth_context = models.CharField(max_length=255, default="instance")
    name = models.CharField(max_length=255)
    description = models.TextField(default="")
    template = models.JSONField(default=dict)
    internal_organization_cache = ArrayField(models.IntegerField(), default=list)

    def sync_facility_org_cache(self):
        from care.emr.resources.workspace.spec import WorkspaceAuthContext

        if self.auth_context == WorkspaceAuthContext.facility_organization:
            organization_ids = [
                *self.facility_organization.parent_cache,
                self.facility_organization.id,
            ]
        elif self.auth_context == WorkspaceAuthContext.facility:
            workspace_organization_objects = (
                WorkspaceFacilityOrganization.objects.filter(
                    workspace=self
                ).select_related("organization")
            )
            organization_ids = []
            for workspace_organization_object in workspace_organization_objects:
                organization_ids.extend(
                    workspace_organization_object.organization.parent_cache
                )
                organization_ids.append(workspace_organization_object.organization.id)
        else:
            return
        self.internal_organization_cache = list(set(organization_ids))
        self.save(update_fields=["internal_organization_cache"])

    def save(self, *args, **kwargs):
        super().save(*args, **kwargs)
        self.invalidate_user_default_cache()

    def invalidate_user_default_cache(self):
        user_ids = WorkSpaceUserDefault.objects.filter(
            workspace_id=self.id
        ).values_list("user_id", flat=True)
        cache.delete_many(
            [WorkSpaceUserDefault.get_cache_key(user_id) for user_id in user_ids]
        )


class WorkspaceFacilityOrganization(EMRBaseModel):
    workspace = models.ForeignKey(Workspace, on_delete=models.CASCADE)
    organization = models.ForeignKey(FacilityOrganization, on_delete=models.CASCADE)


class WorkSpaceUserDefault(EMRBaseModel):
    workspace = models.ForeignKey(Workspace, on_delete=models.CASCADE)
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    attribute = models.CharField(max_length=255, null=True, blank=True)
    value = models.CharField(max_length=255, null=True, blank=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["workspace", "user", "attribute", "value"],
                condition=models.Q(deleted=False),
                nulls_distinct=False,
                name="unique_workspace_user_attribute_value",
            )
        ]

    @classmethod
    def get_cache_key(cls, user_id):
        return WORKSPACE_USER_DEFAULT_CACHE_KEY.format(user_id=user_id)

    def save(self, *args, **kwargs):
        super().save(*args, **kwargs)
        self.invalidate_cache()

    def invalidate_cache(self):
        if self.user_id:
            cache.delete(self.get_cache_key(self.user_id))


@receiver(post_delete, sender=WorkSpaceUserDefault)
def invalidate_workspace_user_default_cache(sender, instance, **kwargs):
    instance.invalidate_cache()
from django.db.models import Q

from care.emr.models.organization import FacilityOrganizationUser
from care.security.authorization.base import (
    AuthorizationController,
    AuthorizationHandler,
)
from care.security.permissions.workspace import WorkspacePermissions


class WorkspaceAccess(AuthorizationHandler):
    def can_write_workspace(self, user, workspace):
        if workspace.auth_context == "instance":
            return user.is_superuser
        if workspace.auth_context == "facility":
            return AuthorizationController.call(
                "can_access_facility_workspace",
                user,
                workspace.facility,
                workspace,
                read_only=False,
            )
        if workspace.auth_context == "facility_organization":
            return AuthorizationController.call(
                "can_access_facility_organization_workspace",
                user,
                workspace.facility_organization,
                read_only=False,
            )
        if workspace.auth_context == "user":
            return workspace.created_by_id == user.id and AuthorizationController.call(
                "can_access_user_workspace_in_facility",
                user,
                workspace.facility,
                read_only=False,
            )
        return False

    def can_access_facility_workspace(self, user, facility, workspace, read_only):
        """
        Permission to access a workspace for a specific facility
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
            return self.check_permission_in_facility_organization(
                permission,
                user,
                facility=facility,
                orgs=workspace.internal_organization_cache,
            )
        permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission, user, facility=facility, root=True
        )

    def can_access_facility_organization_workspace(
        self, user, facility_organization, read_only
    ):
        """
        Permission to access a workspace for a specific facility organization
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
        else:
            permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission,
            user,
            facility=facility_organization.facility,
            orgs=[*facility_organization.parent_cache, facility_organization.id],
        )

    def can_access_user_workspace_in_facility(self, user, facility, read_only):
        """
        Permission to write a workspace for a specific facility as a user
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
        else:
            permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission,
            user,
            facility=facility,
        )

    def get_filtered_workspaces(self, qs, user):
        if user.is_superuser:
            return qs
        roles = self.get_role_from_permissions(
            [WorkspacePermissions.can_read_workspace.name]
        )
        facility_organization_ids = list(
            FacilityOrganizationUser.objects.filter(
                user=user, role_id__in=roles
            ).values_list("organization_id", flat=True)
        )
        write_roles = self.get_role_from_permissions(
            [WorkspacePermissions.can_write_workspace.name]
        )
        writable_facility_ids = FacilityOrganizationUser.objects.filter(
            user=user,
            role_id__in=write_roles,
            organization__org_type="root",
        ).values_list("organization__facility_id", flat=True)
        return qs.filter(
            Q(auth_context="instance")
            | Q(internal_organization_cache__overlap=facility_organization_ids)
            | Q(auth_context="user", created_by=user)
            | Q(auth_context="facility", facility_id__in=writable_facility_ids)
        )


AuthorizationController.register_internal_controller(WorkspaceAccess)

