import { useQuery } from "@tanstack/react-query";
import { LayoutDashboard, Plus, Search } from "lucide-react";
import { Link } from "raviger";
import { useId } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import useAuthUser from "@/hooks/useAuthUser";
import useFilters from "@/hooks/useFilters";

import {
  WORKSPACE_PERMISSIONS,
  WorkspaceAuthContext,
  WorkspaceScope,
} from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";
import query from "@/Utils/request/query";

import { useWorkspacePermissions } from "./useWorkspacePermissions";

interface WorkspaceListProps {
  scope: WorkspaceScope;
}

export function WorkspaceList({ scope }: WorkspaceListProps) {
  const { t } = useTranslation();
  const user = useAuthUser();
  const searchId = useId();
  const {
    canWrite,
    canCreateFacility,
    canCreateDepartment,
    canCreatePersonal,
  } = useWorkspacePermissions(scope);
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
  });
  const authContext: WorkspaceAuthContext =
    scope.authContext === "instance"
      ? "instance"
      : qParams.context === "facility_organization" ||
          qParams.context === "user"
        ? qParams.context
        : "facility";
  const canCreate =
    authContext === "instance"
      ? canWrite
      : authContext === "facility"
        ? canCreateFacility
        : authContext === "facility_organization"
          ? canCreateDepartment
          : canCreatePersonal;
  const listDescription = {
    instance: "workspace_instance_description",
    facility: "workspace_facility_description",
    facility_organization: "workspace_department_description",
    user: "workspace_personal_description",
  }[authContext];
  const name = qParams.name || "";
  const page = Math.max(1, Number(qParams.page) || 1);
  const {
    data: response,
    isLoading,
    isError,
    refetch,
  } = useQuery({
    queryKey: [
      "workspaces",
      user.id,
      authContext,
      scope.facilityId,
      { name, page },
    ],
    queryFn: query.debounced(workspaceApi.list, {
      queryParams: {
        auth_context: authContext,
        ...(scope.authContext === "facility"
          ? { facility: scope.facilityId }
          : {}),
        ...(authContext === "user" ? { created_by: user.id } : {}),
        name: name || undefined,
        limit: resultsPerPage,
        offset: (page - 1) * resultsPerPage,
      },
    }),
  });
  const workspaces = response?.results ?? [];

  return (
    <div className="container mx-auto space-y-5 px-4 py-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0 flex-1">
          <h1 className="text-2xl font-semibold tracking-tight text-gray-950">
            {t("workspaces")}
          </h1>
          <p className="mt-1 max-w-2xl text-sm text-gray-600">
            {t(listDescription)}
          </p>
        </div>
        {canCreate && (
          <Button asChild className="h-10 shrink-0 sm:h-9">
            <Link
              href={`${scope.basePath}/create${scope.authContext === "facility" ? `?context=${authContext}` : ""}`}
              basePath="/"
            >
              <Plus className="size-4" aria-hidden="true" />
              {t("create_workspace")}
            </Link>
          </Button>
        )}
      </div>

      {scope.authContext === "facility" && (
        <Tabs
          value={authContext}
          onValueChange={(context) => updateQuery({ context, page: 1 })}
        >
          <TabsList
            className="h-auto w-full flex-wrap justify-start gap-1 sm:w-fit"
            aria-label={t("workspace_scope")}
          >
            <TabsTrigger
              value="facility"
              className="min-h-10 flex-1 sm:flex-none"
            >
              {t("workspace_facility_tab")}
            </TabsTrigger>
            <TabsTrigger
              value="facility_organization"
              className="min-h-10 flex-1 sm:flex-none"
            >
              {t("workspace_department_tab")}
            </TabsTrigger>
            <TabsTrigger value="user" className="min-h-10 flex-1 sm:flex-none">
              {t("workspace_personal_tab")}
            </TabsTrigger>
          </TabsList>
        </Tabs>
      )}

      <div className="w-full space-y-1.5 sm:max-w-md">
        <Label htmlFor={searchId}>{t("search")}</Label>
        <div className="relative">
          <Search
            className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-500"
            aria-hidden="true"
          />
          <Input
            id={searchId}
            className="h-10 pl-9"
            value={name}
            placeholder={t("search_workspaces")}
            onChange={(event) =>
              updateQuery({ name: event.target.value, page: 1 })
            }
          />
        </div>
      </div>

      {isLoading ? (
        <div role="status" aria-label={t("loading")}>
          <TableSkeleton count={5} />
        </div>
      ) : isError ? (
        <div
          role="alert"
          className="rounded-lg border border-gray-200 bg-white p-8 text-center"
        >
          <p className="mb-4 text-sm text-gray-700">
            {t("workspace_list_error")}
          </p>
          <Button variant="outline" onClick={() => refetch()}>
            {t("try_again")}
          </Button>
        </div>
      ) : workspaces.length === 0 ? (
        <div className="rounded-lg border border-dashed border-gray-300 p-8 text-center">
          <LayoutDashboard
            className="mx-auto mb-3 size-8 text-gray-400"
            aria-hidden="true"
          />
          <h2 className="text-lg font-semibold text-gray-900">
            {t("no_workspaces_found")}
          </h2>
          <p className="mt-1 text-sm text-gray-600">
            {t(name ? "workspace_search_empty_hint" : "workspace_empty_hint")}
          </p>
        </div>
      ) : (
        <div className="overflow-hidden rounded-lg border border-gray-200 bg-white">
          <Table>
            <TableHeader>
              <TableRow className="bg-gray-50 hover:bg-gray-50">
                <TableHead className="px-4">{t("name")}</TableHead>
                <TableHead className="hidden px-4 sm:table-cell">
                  {t("description")}
                </TableHead>
                <TableHead className="px-4 text-right">
                  {t("actions")}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {workspaces.map((workspace) => (
                <TableRow key={workspace.id}>
                  <TableCell className="max-w-xs px-4 py-3 whitespace-normal">
                    <Link
                      href={`${scope.basePath}/${workspace.id}/edit`}
                      basePath="/"
                      className="break-words font-medium text-gray-950 underline-offset-4 hover:underline focus-visible:underline"
                    >
                      {workspace.name}
                    </Link>
                    <p className="mt-1 line-clamp-3 text-sm text-gray-600 sm:hidden">
                      {workspace.description || t("no_description")}
                    </p>
                  </TableCell>
                  <TableCell className="hidden max-w-xl px-4 py-3 whitespace-normal sm:table-cell">
                    <p className="line-clamp-3 break-words text-sm text-gray-600">
                      {workspace.description || t("no_description")}
                    </p>
                  </TableCell>
                  <TableCell className="px-4 py-3 text-right">
                    <Button asChild variant="outline" size="sm">
                      <Link
                        href={`${scope.basePath}/${workspace.id}/edit`}
                        basePath="/"
                        aria-label={`${t(workspace.permissions.includes(WORKSPACE_PERMISSIONS.write) ? "edit" : "view")}: ${workspace.name}`}
                      >
                        {t(
                          workspace.permissions.includes(
                            WORKSPACE_PERMISSIONS.write,
                          )
                            ? "edit"
                            : "view",
                        )}
                      </Link>
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
      {!isLoading && !isError && (
        <Pagination totalCount={response?.count ?? 0} />
      )}
    </div>
  );
}
import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";
import { FacilityOrganizationRead } from "@/types/facilityOrganization/facilityOrganization";

import {
  WorkspaceCreate,
  WorkspaceDefaultAttributesReset,
  WorkspaceDefaultAttributesUpdate,
  WorkspaceFacilityOrganizationsUpdate,
  WorkspaceRead,
  WorkspaceUpdate,
  WorkspaceUserDefaultAttributes,
} from "./workspace";

export default {
  /** Filter configuration lists by auth_context and, for a facility, facility. */
  list: {
    path: "/api/v1/workspace/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<WorkspaceRead>>(),
  },
  get: {
    path: "/api/v1/workspace/{id}/",
    method: HttpMethod.GET,
    TRes: Type<WorkspaceRead>(),
  },
  create: {
    path: "/api/v1/workspace/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceCreate>(),
    TRes: Type<WorkspaceRead>(),
  },
  update: {
    path: "/api/v1/workspace/{id}/",
    method: HttpMethod.PUT,
    TBody: Type<WorkspaceUpdate>(),
    TRes: Type<WorkspaceRead>(),
  },
  delete: {
    path: "/api/v1/workspace/{id}/",
    method: HttpMethod.DELETE,
    TRes: Type<void>(),
  },
  /** Facility workspaces only; requires permission to write the workspace. */
  getFacilityOrganizations: {
    path: "/api/v1/workspace/{id}/get_facility_organizations/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<FacilityOrganizationRead>>(),
  },
  setFacilityOrganizations: {
    path: "/api/v1/workspace/{id}/set_facility_organizations/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceFacilityOrganizationsUpdate>(),
    TRes: Type<Record<string, never>>(),
  },
  setDefaultAttributes: {
    path: "/api/v1/workspace/{id}/set_default_attributes/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceDefaultAttributesUpdate>(),
    TRes: Type<Record<string, never>>(),
  },
  getUserDefaultAttributes: {
    path: "/api/v1/workspace/get_user_default_attributes/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<WorkspaceUserDefaultAttributes>>(),
  },
  resetDefaultAttributes: {
    path: "/api/v1/workspace/{id}/reset_default_attributes/",
    method: HttpMethod.POST,
    TBody: Type<WorkspaceDefaultAttributesReset>(),
    TRes: Type<Record<string, never>>(),
  },
} as const;
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Loader2, Plus } from "lucide-react";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";

import useAuthUser from "@/hooks/useAuthUser";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import {
  WorkspaceDefaultAttributesReset,
  WorkspaceDefaultAttributesUpdate,
  WorkspaceUserDefaultAttributes,
} from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";

interface WorkspaceDefaultsProps {
  workspaceId: string;
  disabled: boolean;
  onStateChange: (state: { dirty: boolean; pending: boolean }) => void;
}

interface DefaultFormValues {
  attribute: string;
  value: string;
}

interface DefaultEditor {
  mode: "add" | "edit";
  attribute: string | null;
}

type WorkspaceDefault = Pick<
  WorkspaceUserDefaultAttributes,
  "attribute" | "value"
>;

export function WorkspaceDefaults(props: WorkspaceDefaultsProps) {
  const { id: userId } = useAuthUser();

  return (
    <WorkspaceDefaultsContent
      key={`${userId}:${props.workspaceId}`}
      {...props}
      userId={userId}
    />
  );
}

interface WorkspaceDefaultsContentProps extends WorkspaceDefaultsProps {
  userId: string;
}

function WorkspaceDefaultsContent({
  workspaceId,
  disabled,
  onStateChange,
  userId,
}: WorkspaceDefaultsContentProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const queryKey = ["workspace-user-defaults", userId, workspaceId];
  const [editor, setEditor] = useState<DefaultEditor | null>(null);
  const { data, isLoading, isError, refetch } = useQuery({
    queryKey,
    queryFn: async ({ signal }): Promise<WorkspaceDefault[]> => {
      const response = await query(workspaceApi.getUserDefaultAttributes)({
        signal,
      });
      return response.results
        .filter((item) => item.workspace.id === workspaceId)
        .map(({ attribute, value }) => ({ attribute, value }));
    },
    retry: false,
  });
  const schema = z
    .object({
      attribute: z
        .string()
        .trim()
        .max(255, t("workspace_default_attribute_too_long")),
      value: z.string().max(255, t("workspace_default_value_too_long")),
    })
    .superRefine((values, context) => {
      if (
        editor?.mode === "add" &&
        data?.some((item) => item.attribute === (values.attribute || null))
      ) {
        context.addIssue({
          code: "custom",
          path: ["attribute"],
          message: t("workspace_default_already_exists"),
        });
      }
    });
  const form = useForm<DefaultFormValues>({
    resolver: zodResolver(schema),
    defaultValues: { attribute: "", value: "" },
  });

  const save = useMutation({
    mutationFn: mutate(workspaceApi.setDefaultAttributes, {
      pathParams: { id: workspaceId },
    }),
    onSuccess: (_, variables: WorkspaceDefaultAttributesUpdate) => {
      const attribute = variables.attribute ?? null;
      queryClient.setQueryData<WorkspaceDefault[]>(queryKey, (current) => [
        ...(current ?? []).filter((item) => item.attribute !== attribute),
        { attribute, value: variables.value },
      ]);
      form.reset({ attribute: "", value: "" });
      setEditor(null);
      toast.success(t("workspace_default_saved"));
      return queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", userId],
      });
    },
  });
  const reset = useMutation({
    mutationFn: mutate(workspaceApi.resetDefaultAttributes, {
      pathParams: { id: workspaceId },
    }),
    onSuccess: (_, variables: WorkspaceDefaultAttributesReset) => {
      queryClient.setQueryData<WorkspaceDefault[]>(queryKey, (current) =>
        (current ?? []).filter(
          (item) => item.attribute !== (variables.attribute ?? null),
        ),
      );
      toast.success(t("workspace_default_removed"));
      return queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", userId],
      });
    },
  });
  const pending = save.isPending || reset.isPending;
  const busy = disabled || pending;
  const dirty = editor !== null && form.formState.isDirty;

  useEffect(() => {
    onStateChange({ dirty, pending });
  }, [dirty, pending, onStateChange]);

  const handleEdit = (item?: WorkspaceDefault) => {
    if (busy || dirty) return;
    save.reset();
    reset.reset();
    form.reset({ attribute: item?.attribute ?? "", value: item?.value ?? "" });
    setEditor({
      mode: item ? "edit" : "add",
      attribute: item?.attribute ?? null,
    });
  };

  return (
    <section
      className="space-y-4 rounded-lg border bg-white p-4 sm:p-5"
      aria-labelledby="workspace-defaults-heading"
    >
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2
            id="workspace-defaults-heading"
            className="text-base font-semibold"
          >
            {t("workspace_my_defaults")}
          </h2>
          <p className="mt-1 text-sm text-gray-600">
            {t("workspace_my_defaults_hint")}
          </p>
        </div>
        {data && (
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={busy || editor !== null}
            onClick={() => handleEdit()}
          >
            <Plus className="size-4" />
            {t("workspace_add_default")}
          </Button>
        )}
      </div>

      {isLoading && <Skeleton className="h-24 w-full" />}
      {isError && (
        <Alert variant="destructive">
          <AlertDescription className="space-y-3">
            <p>{t("workspace_defaults_load_error")}</p>
            <Button type="button" variant="outline" onClick={() => refetch()}>
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {data && (
        <>
          {data.length ? (
            <ul className="divide-y rounded-md border">
              {data.map((item) => {
                const label = item.attribute ?? t("workspace_default_slot");
                return (
                  <li
                    key={JSON.stringify(item.attribute)}
                    className="flex flex-wrap items-start justify-between gap-3 p-3"
                  >
                    <div className="min-w-0 flex-1 space-y-1">
                      <p className="break-all text-sm font-medium">{label}</p>
                      <p className="whitespace-pre-wrap break-all text-sm text-gray-600">
                        {item.value || t("workspace_default_empty_value")}
                      </p>
                    </div>
                    <div className="flex shrink-0 gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        disabled={busy || dirty}
                        aria-label={t("workspace_edit_default_label", {
                          attribute: label,
                        })}
                        onClick={() => handleEdit(item)}
                      >
                        {t("edit")}
                      </Button>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        disabled={busy || editor !== null}
                        aria-label={t("workspace_remove_default_label", {
                          attribute: label,
                        })}
                        onClick={() => {
                          if (!busy && editor === null) {
                            reset.mutate({ attribute: item.attribute });
                          }
                        }}
                      >
                        {reset.isPending &&
                          reset.variables.attribute === item.attribute && (
                            <Loader2 className="size-4 animate-spin" />
                          )}
                        {t("remove")}
                      </Button>
                    </div>
                  </li>
                );
              })}
            </ul>
          ) : (
            <p className="rounded-md border border-dashed p-4 text-sm text-gray-500">
              {t("workspace_no_defaults")}
            </p>
          )}
          {reset.isError && (
            <Alert variant="destructive">
              <AlertDescription>
                {t("workspace_default_remove_error")}
              </AlertDescription>
            </Alert>
          )}
          {editor && (
            <Form {...form}>
              <form
                noValidate
                className="space-y-4 border-t pt-4"
                onSubmit={form.handleSubmit((values) => {
                  if (!busy) {
                    save.mutate({
                      attribute:
                        editor.mode === "edit"
                          ? editor.attribute
                          : values.attribute || null,
                      value: values.value,
                    });
                  }
                })}
              >
                <h3 className="text-sm font-semibold">
                  {t(
                    editor.mode === "add"
                      ? "workspace_add_default"
                      : "workspace_edit_default",
                  )}
                </h3>
                <div className="grid gap-4 sm:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="attribute"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>
                          {t("workspace_default_attribute")}
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            disabled={busy}
                            readOnly={editor.mode === "edit"}
                            autoComplete="off"
                            maxLength={255}
                            placeholder={t("workspace_default_slot")}
                          />
                        </FormControl>
                        <FormDescription>
                          {t("workspace_default_attribute_hint")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="value"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t("value")}</FormLabel>
                        <FormControl>
                          <Textarea
                            {...field}
                            disabled={busy}
                            maxLength={255}
                            rows={2}
                          />
                        </FormControl>
                        <FormDescription>
                          {t("workspace_default_value_hint")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
                {save.isError && (
                  <Alert variant="destructive">
                    <AlertDescription>
                      {t("workspace_default_save_error")}
                    </AlertDescription>
                  </Alert>
                )}
                <div className="flex justify-end gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    disabled={busy}
                    onClick={() => {
                      form.reset({ attribute: "", value: "" });
                      setEditor(null);
                    }}
                  >
                    {t("cancel")}
                  </Button>
                  <Button
                    type="submit"
                    disabled={busy || (editor.mode === "edit" && !dirty)}
                  >
