import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Loader2, Plus } from "lucide-react";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";

import useAuthUser from "@/hooks/useAuthUser";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import {
  WorkspaceDefaultAttributesReset,
  WorkspaceDefaultAttributesUpdate,
  WorkspaceUserDefaultAttributes,
} from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";

interface WorkspaceDefaultsProps {
  workspaceId: string;
  disabled: boolean;
  onStateChange: (state: { dirty: boolean; pending: boolean }) => void;
}

interface DefaultFormValues {
  attribute: string;
  value: string;
}

interface DefaultEditor {
  mode: "add" | "edit";
  attribute: string | null;
}

type WorkspaceDefault = Pick<
  WorkspaceUserDefaultAttributes,
  "attribute" | "value"
>;

export function WorkspaceDefaults(props: WorkspaceDefaultsProps) {
  const { id: userId } = useAuthUser();

  return (
    <WorkspaceDefaultsContent
      key={`${userId}:${props.workspaceId}`}
      {...props}
      userId={userId}
    />
  );
}

interface WorkspaceDefaultsContentProps extends WorkspaceDefaultsProps {
  userId: string;
}

function WorkspaceDefaultsContent({
  workspaceId,
  disabled,
  onStateChange,
  userId,
}: WorkspaceDefaultsContentProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const queryKey = ["workspace-user-defaults", userId, workspaceId];
  const [editor, setEditor] = useState<DefaultEditor | null>(null);
  const { data, isLoading, isError, refetch } = useQuery({
    queryKey,
    queryFn: async ({ signal }): Promise<WorkspaceDefault[]> => {
      const response = await query(workspaceApi.getUserDefaultAttributes)({
        signal,
      });
      return response.results
        .filter((item) => item.workspace.id === workspaceId)
        .map(({ attribute, value }) => ({ attribute, value }));
    },
    retry: false,
  });
  const schema = z
    .object({
      attribute: z
        .string()
        .trim()
        .max(255, t("workspace_default_attribute_too_long")),
      value: z.string().max(255, t("workspace_default_value_too_long")),
    })
    .superRefine((values, context) => {
      if (
        editor?.mode === "add" &&
        data?.some((item) => item.attribute === (values.attribute || null))
      ) {
        context.addIssue({
          code: "custom",
          path: ["attribute"],
          message: t("workspace_default_already_exists"),
        });
      }
    });
  const form = useForm<DefaultFormValues>({
    resolver: zodResolver(schema),
    defaultValues: { attribute: "", value: "" },
  });

  const save = useMutation({
    mutationFn: mutate(workspaceApi.setDefaultAttributes, {
      pathParams: { id: workspaceId },
    }),
    onSuccess: (_, variables: WorkspaceDefaultAttributesUpdate) => {
      const attribute = variables.attribute ?? null;
      queryClient.setQueryData<WorkspaceDefault[]>(queryKey, (current) => [
        ...(current ?? []).filter((item) => item.attribute !== attribute),
        { attribute, value: variables.value },
      ]);
      form.reset({ attribute: "", value: "" });
      setEditor(null);
      toast.success(t("workspace_default_saved"));
      return queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", userId],
      });
    },
  });
  const reset = useMutation({
    mutationFn: mutate(workspaceApi.resetDefaultAttributes, {
      pathParams: { id: workspaceId },
    }),
    onSuccess: (_, variables: WorkspaceDefaultAttributesReset) => {
      queryClient.setQueryData<WorkspaceDefault[]>(queryKey, (current) =>
        (current ?? []).filter(
          (item) => item.attribute !== (variables.attribute ?? null),
        ),
      );
      toast.success(t("workspace_default_removed"));
      return queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", userId],
      });
    },
  });
  const pending = save.isPending || reset.isPending;
  const busy = disabled || pending;
  const dirty = editor !== null && form.formState.isDirty;

  useEffect(() => {
    onStateChange({ dirty, pending });
  }, [dirty, pending, onStateChange]);

  const handleEdit = (item?: WorkspaceDefault) => {
    if (busy || dirty) return;
    save.reset();
    reset.reset();
    form.reset({ attribute: item?.attribute ?? "", value: item?.value ?? "" });
    setEditor({
      mode: item ? "edit" : "add",
      attribute: item?.attribute ?? null,
    });
  };

  return (
    <section
      className="space-y-4 rounded-lg border bg-white p-4 sm:p-5"
      aria-labelledby="workspace-defaults-heading"
    >
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2
            id="workspace-defaults-heading"
            className="text-base font-semibold"
          >
            {t("workspace_my_defaults")}
          </h2>
          <p className="mt-1 text-sm text-gray-600">
            {t("workspace_my_defaults_hint")}
          </p>
        </div>
        {data && (
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={busy || editor !== null}
            onClick={() => handleEdit()}
          >
            <Plus className="size-4" />
            {t("workspace_add_default")}
          </Button>
        )}
      </div>

      {isLoading && <Skeleton className="h-24 w-full" />}
      {isError && (
        <Alert variant="destructive">
          <AlertDescription className="space-y-3">
            <p>{t("workspace_defaults_load_error")}</p>
            <Button type="button" variant="outline" onClick={() => refetch()}>
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {data && (
        <>
          {data.length ? (
            <ul className="divide-y rounded-md border">
              {data.map((item) => {
                const label = item.attribute ?? t("workspace_default_slot");
                return (
                  <li
                    key={JSON.stringify(item.attribute)}
                    className="flex flex-wrap items-start justify-between gap-3 p-3"
                  >
                    <div className="min-w-0 flex-1 space-y-1">
                      <p className="break-all text-sm font-medium">{label}</p>
                      <p className="whitespace-pre-wrap break-all text-sm text-gray-600">
                        {item.value || t("workspace_default_empty_value")}
                      </p>
                    </div>
                    <div className="flex shrink-0 gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        disabled={busy || dirty}
                        aria-label={t("workspace_edit_default_label", {
                          attribute: label,
                        })}
                        onClick={() => handleEdit(item)}
                      >
                        {t("edit")}
                      </Button>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        disabled={busy || editor !== null}
                        aria-label={t("workspace_remove_default_label", {
                          attribute: label,
                        })}
                        onClick={() => {
                          if (!busy && editor === null) {
                            reset.mutate({ attribute: item.attribute });
                          }
                        }}
                      >
                        {reset.isPending &&
                          reset.variables.attribute === item.attribute && (
                            <Loader2 className="size-4 animate-spin" />
                          )}
                        {t("remove")}
                      </Button>
                    </div>
                  </li>
                );
              })}
            </ul>
          ) : (
            <p className="rounded-md border border-dashed p-4 text-sm text-gray-500">
              {t("workspace_no_defaults")}
            </p>
          )}
          {reset.isError && (
            <Alert variant="destructive">
              <AlertDescription>
                {t("workspace_default_remove_error")}
              </AlertDescription>
            </Alert>
          )}
          {editor && (
            <Form {...form}>
              <form
                noValidate
                className="space-y-4 border-t pt-4"
                onSubmit={form.handleSubmit((values) => {
                  if (!busy) {
                    save.mutate({
                      attribute:
                        editor.mode === "edit"
                          ? editor.attribute
                          : values.attribute || null,
                      value: values.value,
                    });
                  }
                })}
              >
                <h3 className="text-sm font-semibold">
                  {t(
                    editor.mode === "add"
                      ? "workspace_add_default"
                      : "workspace_edit_default",
                  )}
                </h3>
                <div className="grid gap-4 sm:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="attribute"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>
                          {t("workspace_default_attribute")}
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            disabled={busy}
                            readOnly={editor.mode === "edit"}
                            autoComplete="off"
                            maxLength={255}
                            placeholder={t("workspace_default_slot")}
                          />
                        </FormControl>
                        <FormDescription>
                          {t("workspace_default_attribute_hint")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="value"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t("value")}</FormLabel>
                        <FormControl>
                          <Textarea
                            {...field}
                            disabled={busy}
                            maxLength={255}
                            rows={2}
                          />
                        </FormControl>
                        <FormDescription>
                          {t("workspace_default_value_hint")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
                {save.isError && (
                  <Alert variant="destructive">
                    <AlertDescription>
                      {t("workspace_default_save_error")}
                    </AlertDescription>
                  </Alert>
                )}
                <div className="flex justify-end gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    disabled={busy}
                    onClick={() => {
                      form.reset({ attribute: "", value: "" });
                      setEditor(null);
                    }}
                  >
                    {t("cancel")}
                  </Button>
                  <Button
                    type="submit"
                    disabled={busy || (editor.mode === "edit" && !dirty)}
                  >
                    {save.isPending && (
                      <Loader2 className="size-4 animate-spin" />
                    )}
                    {t("workspace_save_default")}
                  </Button>
                </div>
              </form>
            </Form>
          )}
        </>
      )}
    </section>
  );
}

