  test("does not request or render clinical records without clinical read permission", async ({
    page,
  }) => {
    const fixture = await mockEncounterWorkspaceApi(page, {
      clinicalRead: false,
    });
    await page.goto(
      `${fixture.basePath}/rounds?workspace=${fixture.workspace.id}`,
    );
    await expect(
      page.getByRole("heading", { name: "Ward rounds", exact: true }),
    ).toBeVisible();
    await expect(
      page.getByText(
        "You do not have permission to view clinical data for this encounter",
        { exact: true },
      ),
    ).toHaveCount(3);
    await expect(page.getByText("Fever today", { exact: true })).toHaveCount(0);
    await expect(
      page
        .getByRole("tabpanel")
        .getByRole("link", { name: "Edit", exact: true }),
    ).toHaveCount(0);
    expect(fixture.clinicalReads).toEqual([]);
  });

  test("retries a failed workspace read without losing the requested page", async ({
    page,
  }) => {
    const fixture = await mockEncounterWorkspaceApi(page, {
      selectedLoadFailures: 1,
    });
    await page.goto(
      `${fixture.basePath}/rounds?workspace=${fixture.workspace.id}`,
    );
    await expect(
      page.getByRole("alert").filter({
        hasText: "This workspace is unavailable for this encounter.",
      }),
    ).toBeVisible();
    await expect(page).toHaveURL((url) => url.pathname.endsWith("/rounds"));
    await page.getByRole("button", { name: "Try again", exact: true }).click();
    await expect(
      page.getByRole("heading", { name: "Ward rounds", exact: true }),
    ).toBeVisible();
    await expect(
      page
        .getByRole("region", { name: "Symptoms today", exact: true })
        .getByText("Fever today", { exact: true })
        .first(),
    ).toBeVisible();
    await expect(page).toHaveURL(
      (url) =>
        url.pathname.endsWith("/rounds") &&
        url.searchParams.get("workspace") === fixture.workspace.id,
    );
  });

  test("falls back to standard pages for invalid or unsupported templates", async ({
    page,
  }) => {
    const fixture = await mockEncounterWorkspaceApi(page);
    const invalidTemplates: WorkspaceTemplate[] = [
      { schema_version: 2, pages: [] },
      {
        schema_version: 1,
        pages: [
          {
            kind: "system",
            key: "medications",
            title: "Overridden medications",
            columns: [],
          },
        ],
      },
      {
        schema_version: 1,
        pages: [
          {
            kind: "custom",
            key: "questionnaire",
            title: "Reserved route",
            columns: [{ span: 1, widgets: [] }],
          },
        ],
      },
      {
        schema_version: 1,
        pages: [
          {
            kind: "custom",
            key: "rounds",
            title: "Ward rounds",
            columns: [{ span: 0, widgets: [] }],
          },
        ],
      },
    ];
    for (const template of invalidTemplates) {
      fixture.workspace.template = template;
      await page.goto(
        `${fixture.basePath}/medicines?workspace=${fixture.workspace.id}`,
      );
      await expect(
        page.getByRole("alert").filter({ hasText: /workspace/i }),
      ).toBeVisible();
      await expect(
        page.getByRole("heading", { name: "Medications", exact: true }),
      ).toBeVisible();
      await expect(
        page.getByRole("tab", { name: "Devices", exact: true }),
      ).toBeVisible();
      await expect(
        page.getByText("Overridden medications", { exact: true }),
      ).toHaveCount(0);
      await expect(
        page.getByRole("tab", { name: "Ward rounds", exact: true }),
      ).toHaveCount(0);
    }
  });

  test("rejects direct links to other facilities and another user's personal workspace", async ({
    page,
  }) => {
    const fixture = await mockEncounterWorkspaceApi(page);
    const outOfScope: WorkspaceRead[] = [
      {
        ...fixture.workspace,
        id: faker.string.uuid(),
        facility: faker.string.uuid(),
      },
      {
        ...fixture.workspace,
        id: faker.string.uuid(),
        auth_context: "user",
        created_by: user(),
      },
    ];
    fixture.records.push(...outOfScope);
    for (const workspace of outOfScope) {
      await page.goto(
        `${fixture.basePath}/medicines?workspace=${workspace.id}`,
      );
      await expect(
        page.getByRole("alert").filter({ hasText: /workspace/i }),
      ).toBeVisible();
      await expect(
        page.getByRole("heading", { name: "Medications", exact: true }),
      ).toBeVisible();
      await expect(
        page.getByRole("tab", { name: "Ward rounds", exact: true }),
      ).toHaveCount(0);
      await expect(
        page.getByRole("tab", { name: "Devices", exact: true }),
      ).toBeVisible();
    }
  });
});
