          name: payload.name,
          description: payload.description,
          template: payload.template,
          facility_organization: payload.facility_organization ?? null,
          created_by: user,
        };
        records.push(created);
        // Mutations omit computed permissions; detail reads supply them.
        await route.fulfill({
          status: 201,
          json: { ...created.data, permissions: [] },
        });
        return;
      }
      const record = records.find((item) =>
        pathname.startsWith(`/api/v1/workspace/${item.data.id}/`),
      );
      if (
