      ) {
        await route.fulfill({
          status: 500,
          json: { detail: "Workspace temporarily unavailable" },
        });
        return;
      }
      if (!record) {
        await route.fulfill({ status: 404, json: { detail: "Not found" } });
        return;
      }
      if (method === "POST" && pathname.endsWith("/set_default_attributes/")) {
        if (defaultSaveFailures > 0) {
          defaultSaveFailures -= 1;
          await route.fulfill({
            status: 500,
            json: { detail: "Default temporarily unavailable" },
          });
          return;
        }
        const payload = request.postDataJSON() as {
          attribute: string | null;
          value: string;
        };
        defaults = defaults.filter(
          (item) =>
            item.workspace.id !== record.data.id ||
            item.attribute !== payload.attribute,
        );
        defaults.push({ ...payload, workspace: record.data });
        await route.fulfill({ json: {} });
        return;
      }
      if (
        method === "POST" &&
        pathname.endsWith("/reset_default_attributes/")
      ) {
        const payload = request.postDataJSON() as { attribute: string | null };
        defaults = defaults.filter(
          (item) =>
            item.workspace.id !== record.data.id ||
            item.attribute !== payload.attribute,
        );
        await route.fulfill({ json: {} });
        return;
      }
      if (
        method === "GET" &&
        pathname.endsWith("/get_facility_organizations/")
      ) {
        const selected = organizations.filter((org) =>
          assignments.get(record.data.id)?.includes(org.id),
        );
        await route.fulfill({
          json: { count: selected.length, results: selected },
        });
      } else if (
        method === "POST" &&
        pathname.endsWith("/set_facility_organizations/")
      ) {
        const payload = request.postDataJSON() as {
          facility_organizations: string[];
        };
        assignments.set(record.data.id, payload.facility_organizations);
        await route.fulfill({ json: {} });
      } else if (pathname === `/api/v1/workspace/${record.data.id}/`) {
        if (method === "GET") {
          // As in the backend, a detail read alone does not enforce list filters.
          await route.fulfill({ json: record.data });
        } else if (method === "PUT") {
          const payload = request.postDataJSON() as WorkspaceUpdate;
          record.data = { ...record.data, ...payload };
          await route.fulfill({ json: { ...record.data, permissions: [] } });
        } else if (method === "DELETE") {
          records.splice(records.indexOf(record), 1);
          await route.fulfill({ status: 204 });
        } else {
          await route.abort();
        }
      } else {
        await route.abort();
      }
    },
  );

  return { facilityId, records, writes, reads, organizations, user };
}

