class WorkspaceViewSet(EMRModelViewSet):
    database_model = Workspace
    pydantic_model = WorkspaceCreateSpec
    pydantic_update_model = WorkspaceUpdateSpec
    pydantic_read_model = WorkspaceReadSpec
    filterset_class = WorkspaceFilter
    filter_backends = [DjangoFilterBackend]

    def authorize_create(self, instance):
        if (
            instance.auth_context == WorkspaceAuthContext.instance
            and not self.request.user.is_superuser
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.facility:
            facility = get_object_or_404(Facility, external_id=instance.facility)
            if not AuthorizationController.call(
                "can_access_facility_workspace",
                self.request.user,
                facility,
                None,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.facility_organization:
            facility_organization = get_object_or_404(
                FacilityOrganization, external_id=instance.facility_organization
            )
            if not AuthorizationController.call(
                "can_access_facility_organization_workspace",
                self.request.user,
                facility_organization,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.user:
            facility = get_object_or_404(Facility, external_id=instance.facility)
            if not AuthorizationController.call(
                "can_access_user_workspace_in_facility",
                self.request.user,
                facility,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")

        return super().authorize_create(instance)

    def authorize_update(self, request_obj, model_instance):
        if not AuthorizationController.call(
            "can_write_workspace", self.request.user, model_instance
        ):
            raise PermissionDenied("You are not authorized to update this workspace")

    def authorize_destroy(self, instance):
        self.authorize_update(self.request, instance)

    def perform_create(self, instance):
        super().perform_create(instance)
        return Response({})

    class WorkspaceDefaultAttributeSchema(BaseModel):
        attribute: str | None = Field(default=None, max_length=255)

        @field_validator("attribute", mode="before")
        @classmethod
        def normalize_attribute(cls, attribute):
            return _normalize_default_attribute(attribute)

    class WorkspaceDefaultSetSchema(WorkspaceDefaultAttributeSchema):
        value: str = Field(max_length=255)

    class WorkspaceDefaultResetSchema(WorkspaceDefaultAttributeSchema):
        value: str | None = Field(default=None, max_length=255)

    def _delete_default_attribute(
        self, workspace, attribute, *, value=None, match_facility=False
    ):
        defaults = WorkSpaceUserDefault.objects.filter(user=self.request.user)
        if match_facility:
            defaults = defaults.filter(workspace__facility_id=workspace.facility_id)
        else:
            defaults = defaults.filter(workspace=workspace)
        if value is not None:
            defaults = defaults.filter(value=value)
        # Older clients could store blank or padded keys. Treat their rows as
        # the same slot, including Unicode whitespace, when editing or resetting.
        matching_ids = [
            default_id
            for default_id, stored_attribute in defaults.values_list("id", "attribute")
            if _normalize_default_attribute(stored_attribute) == attribute
        ]
        defaults.filter(id__in=matching_ids).delete()

    def _invalidate_default_cache_after_commit(self):
        cache_key = WorkSpaceUserDefault.get_cache_key(self.request.user.id)
        transaction.on_commit(lambda: cache.delete(cache_key))

    @extend_schema(request=WorkspaceDefaultSetSchema)
    @action(detail=True, methods=["POST"])
    def set_default_attributes(self, request, *args, **kwargs):
        workspace = self.get_object()
        request_params = self.WorkspaceDefaultSetSchema(**request.data)
        with transaction.atomic():
            # A class may select a different workspace in each facility. Lock
            # the user so simultaneous choices on different workspaces cannot
            # leave two defaults for the same facility and encounter class.
            User.objects.select_for_update().get(id=self.request.user.id)
            if request_params.attribute == "encounter_class":
                self._delete_default_attribute(
                    workspace,
                    request_params.attribute,
                    value=request_params.value,
                    match_facility=True,
                )
            else:
                self._delete_default_attribute(workspace, request_params.attribute)
            WorkSpaceUserDefault.objects.create(
                workspace=workspace,
                attribute=request_params.attribute,
                value=request_params.value,
                user=self.request.user,
            )
            self._invalidate_default_cache_after_commit()
        return Response({})

    @extend_schema(request=WorkspaceDefaultResetSchema)
    @action(detail=True, methods=["POST"])
    def reset_default_attributes(self, request, *args, **kwargs):
        workspace = self.get_object()
        request_params = self.WorkspaceDefaultResetSchema(**request.data)
        with transaction.atomic():
            User.objects.select_for_update().get(id=self.request.user.id)
            self._delete_default_attribute(
                workspace, request_params.attribute, value=request_params.value
            )
            self._invalidate_default_cache_after_commit()
        return Response({})

    @action(detail=False, methods=["GET"])
    def get_user_default_attributes(self, request, *args, **kwargs):
        cache_key = WorkSpaceUserDefault.get_cache_key(self.request.user.id)
        results = cache.get(cache_key)
        if results is not None:
            canonical_keys = {
                _default_slot(
                    item["workspace"]["id"],
                    item["attribute"],
                    item["value"],
                )
                for item in results
            }
            if len(canonical_keys) != len(results) or any(
                item["attribute"] != _normalize_default_attribute(item["attribute"])
                or "auth_context" not in item["workspace"]
                for item in results
            ):
                # Legacy cached responses lack ordering metadata; reload so the
                # most recently modified row wins consistently for each slot.
                results = None
