import careConfig from "@careConfig";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Loader2 } from "lucide-react";
import { useId, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";

import useAuthUser from "@/hooks/useAuthUser";
import { useCareAppTabs } from "@/hooks/useCareApps";

import query, { callApi } from "@/Utils/request/query";
import { EncounterClass } from "@/types/emr/encounter/encounter";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";
import { WorkspaceScope } from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";

const STANDARD_WORKSPACE = "standard";
const CONFLICTING_WORKSPACES = "conflict";

interface WorkspaceEncounterDefaultsProps {
  scope: WorkspaceScope;
}

export function WorkspaceEncounterDefaults({
  scope,
}: WorkspaceEncounterDefaultsProps) {
  const user = useAuthUser();

  return scope.authContext === "facility" ? (
    <WorkspaceEncounterDefaultsContent
      key={`${user.id}:${scope.facilityId}`}
      facilityId={scope.facilityId}
    />
  ) : null;
}

function WorkspaceEncounterDefaultsContent({
  facilityId,
}: {
  facilityId: string;
}) {
  const { t } = useTranslation();
  const user = useAuthUser();
  const pluginTabs = useCareAppTabs("encounterTabs");
  const queryClient = useQueryClient();
  const headingId = useId();
  const classId = useId();
  const workspaceId = useId();
  const [encounterClass, setEncounterClass] = useState<EncounterClass>(
    careConfig.encounterClasses[0],
  );
  const [draftWorkspace, setDraftWorkspace] = useState<string>();
  const defaults = useQuery({
    queryKey: [
      "workspace-user-defaults",
      user.id,
      "encounter-settings",
      facilityId,
    ],
    queryFn: query(workspaceApi.getUserDefaultAttributes, { silent: true }),
    retry: false,
  });
  const workspaces = useQuery({
    queryKey: ["workspaces", user.id, "encounter-default-options", facilityId],
    queryFn: async ({ signal }) => {
      const filters = [
        { auth_context: "facility", facility: facilityId },
        { auth_context: "facility_organization", facility: facilityId },
        { auth_context: "user", facility: facilityId, created_by: user.id },
      ];
      const responses = await Promise.all(
        filters.map((queryParams) =>
          query.paginated(workspaceApi.list, { queryParams, silent: true })({
            signal,
          }),
        ),
      );
      return responses
        .flatMap(({ results }) => results)
        .filter(
          (workspace) =>
            workspace.facility === facilityId &&
            workspace.auth_context !== "instance" &&
            (workspace.auth_context !== "user" ||
              workspace.created_by?.id === user.id),
        );
    },
    retry: false,
  });
  const options = (workspaces.data ?? []).filter(
    (workspace) =>
      parseEncounterWorkspaceTemplate(
        workspace.template,
        Object.keys(pluginTabs),
      ).success,
  );
  const matchingDefaults = (defaults.data?.results ?? []).filter(
    (item) =>
      item.attribute === "encounter_class" &&
      item.value === encounterClass &&
      item.workspace.facility === facilityId &&
      item.workspace.auth_context !== "instance",
  );
  const savedWorkspace =
    matchingDefaults.length > 1
      ? CONFLICTING_WORKSPACES
      : (matchingDefaults[0]?.workspace.id ?? STANDARD_WORKSPACE);
  const selectedWorkspace = draftWorkspace ?? savedWorkspace;
  const loading = defaults.isLoading || workspaces.isLoading;
  const loadError = defaults.isError || workspaces.isError;
  const save = useMutation({
    mutationFn: async ({
      selection,
      encounterClass: value,
    }: {
      selection: string;
      encounterClass: EncounterClass;
    }) => {
      if (selection === STANDARD_WORKSPACE) {
        const matching = (defaults.data?.results ?? []).filter(
          (item) =>
            item.attribute === "encounter_class" &&
            item.value === value &&
            item.workspace.facility === facilityId &&
            item.workspace.auth_context !== "instance",
        );
        for (const item of matching) {
          await callApi(workspaceApi.resetDefaultAttributes, {
            pathParams: { id: item.workspace.id },
            body: { attribute: "encounter_class", value },
            silent: true,
          });
        }
      } else {
        const workspace = options.find((item) => item.id === selection);
        if (!workspace) throw new Error("Workspace is unavailable");
        await callApi(workspaceApi.setDefaultAttributes, {
          pathParams: { id: workspace.id },
          body: { attribute: "encounter_class", value },
          silent: true,
        });
      }
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", user.id],
      });
      setDraftWorkspace(undefined);
      toast.success(t("workspace_encounter_default_saved"));
    },
    onError: () => {
      // A retry must read any successful resets if clearing legacy duplicates partly failed.
      queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", user.id],
      });
    },
  });
  const busy = loading || loadError || save.isPending;
  const scopeLabels = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };

  return (
    <section
      className="space-y-4 rounded-lg border bg-white p-4 sm:p-5"
      aria-labelledby={headingId}
    >
      <div>
        <h2 id={headingId} className="text-base font-semibold">
          {t("workspace_encounter_defaults")}
        </h2>
        <p className="mt-1 max-w-2xl text-sm text-gray-600">
          {t("workspace_encounter_defaults_hint")}
        </p>
      </div>
      {loading ? (
        <Skeleton className="h-24 w-full" />
      ) : (
        <form
          className="space-y-4"
          onSubmit={(event) => {
            event.preventDefault();
            if (
              !busy &&
              selectedWorkspace !== CONFLICTING_WORKSPACES &&
              selectedWorkspace !== savedWorkspace
            ) {
              save.mutate({ selection: selectedWorkspace, encounterClass });
            }
          }}
        >
          {loadError && (
            <Alert variant="destructive">
              <AlertDescription className="space-y-2">
                <p>{t("workspace_encounter_defaults_load_error")}</p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    defaults.refetch();
                    workspaces.refetch();
                  }}
                >
                  {t("try_again")}
                </Button>
              </AlertDescription>
            </Alert>
          )}
          {savedWorkspace === CONFLICTING_WORKSPACES && (
            <Alert>
              <AlertDescription>
                {t("workspace_encounter_defaults_conflict")}
              </AlertDescription>
            </Alert>
          )}
          <div className="grid items-end gap-4 sm:grid-cols-[minmax(0,1fr)_minmax(0,2fr)_auto]">
            <div className="space-y-1.5">
              <Label htmlFor={classId}>{t("encounter_class")}</Label>
              <Select
                value={encounterClass}
                disabled={busy}
                onValueChange={(value) => {
                  if (
                    !careConfig.encounterClasses.includes(
                      value as EncounterClass,
                    )
                  )
                    return;
                  setEncounterClass(value as EncounterClass);
                  setDraftWorkspace(undefined);
                  save.reset();
                }}
              >
                <SelectTrigger id={classId} className="w-full">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {careConfig.encounterClasses.map((value) => (
                    <SelectItem key={value} value={value}>
                      {t(`encounter_class__${value}`)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor={workspaceId}>
                {t("workspace_encounter_default")}
              </Label>
              <Select
                value={selectedWorkspace}
                disabled={busy}
                onValueChange={(value) => {
                  setDraftWorkspace(value);
                  save.reset();
                }}
              >
                <SelectTrigger id={workspaceId} className="w-full">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value={STANDARD_WORKSPACE}>
                    {t("encounter_workspace_standard")}
                  </SelectItem>
                  {savedWorkspace === CONFLICTING_WORKSPACES && (
                    <SelectItem value={CONFLICTING_WORKSPACES} disabled>
                      {t("workspace_encounter_defaults_choose")}
                    </SelectItem>
                  )}
                  {savedWorkspace !== STANDARD_WORKSPACE &&
                    savedWorkspace !== CONFLICTING_WORKSPACES &&
                    !options.some((item) => item.id === savedWorkspace) && (
                      <SelectItem value={savedWorkspace} disabled>
                        {matchingDefaults[0].workspace.name} ·{" "}
                        {t("encounter_workspace_unavailable")}
                      </SelectItem>
                    )}
                  {options.map((workspace) => (
                    <SelectItem key={workspace.id} value={workspace.id}>
                      {workspace.name} · {scopeLabels[workspace.auth_context]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <Button
              type="submit"
              disabled={
                busy ||
                selectedWorkspace === savedWorkspace ||
                selectedWorkspace === CONFLICTING_WORKSPACES
              }
            >
              {save.isPending && (
                <Loader2 className="size-4 animate-spin" aria-hidden="true" />
              )}
              {t("save")}
            </Button>
          </div>
          {save.isError && (
            <Alert variant="destructive">
              <AlertDescription>
                {t("workspace_encounter_default_save_error")}
              </AlertDescription>
            </Alert>
          )}
        </form>
      )}
    </section>
  );
}
{
  "workspace_default_class_already_exists": "This workspace is already your default for this encounter class.",
  "workspace_default_class_label": "Encounter class: {{value}}",
  "workspace_encounter_default": "Default workspace",
  "workspace_encounter_default_save_error": "Could not save your encounter workspace. Your selection is still here; try again.",
  "workspace_encounter_default_saved": "Your encounter workspace has been saved",
  "workspace_encounter_defaults": "My encounter workspaces",
  "workspace_encounter_defaults_choose": "Choose a workspace",
  "workspace_encounter_defaults_conflict": "More than one workspace is saved for this encounter class. Choose one workspace or Standard encounter to replace these defaults.",
  "workspace_encounter_defaults_hint": "Choose the workspace used for each encounter class in this facility. These choices apply only to your account.",
  "workspace_encounter_defaults_load_error": "Could not load your encounter workspace choices. Try again."
}
