  useLayoutEffect(() => {
    const shell = shellRef.current;
    const header = headerRef.current;
    if (!shell || !header) return;

    const measureHeader = () => {
      const height = Math.ceil(header.getBoundingClientRect().height);
      if (height > 0) {
        shell.style.setProperty("--fill-shell-header-height", `${height}px`);
      }
    };
    measureHeader();
