)
from care.facility.models.facility import Facility
from care.security.authorization.base import AuthorizationController
from care.utils.shortcuts import get_object_or_404


class WorkspaceFilter(filters.FilterSet):
    name = filters.CharFilter(field_name="name", lookup_expr="icontains")
    status = filters.CharFilter(field_name="status", lookup_expr="iexact")
    auth_context = filters.CharFilter(field_name="auth_context", lookup_expr="iexact")
    facility = filters.UUIDFilter(field_name="facility__external_id")


class WorkspaceViewSet(EMRModelViewSet):
    database_model = Workspace
    pydantic_model = WorkspaceCreateSpec
    pydantic_update_model = WorkspaceUpdateSpec
    pydantic_read_model = WorkspaceReadSpec
    filterset_class = WorkspaceFilter
    filter_backends = [DjangoFilterBackend]

    def authorize_create(self, instance):
        if (
            instance.auth_context == WorkspaceAuthContext.instance
            and not self.request.user.is_superuser
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.facility:
            facility = get_object_or_404(Facility, external_id=instance.facility)
            if not AuthorizationController.call(
                "can_access_facility_workspace",
                self.request.user,
                facility,
                None,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.facility_organization:
            facility_organization = get_object_or_404(
                FacilityOrganization, external_id=instance.facility_organization
            )
            if not AuthorizationController.call(
                "can_access_facility_organization_workspace",
                self.request.user,
                facility_organization,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")
        if instance.auth_context == WorkspaceAuthContext.user:
            facility = get_object_or_404(Facility, external_id=instance.facility)
            if not AuthorizationController.call(
                "can_access_user_workspace_in_facility",
                self.request.user,
                facility,
                read_only=False,
            ):
                raise PermissionDenied("You are not authorized to create a workspace")

        return super().authorize_create(instance)

    def authorize_update(self, request_obj, model_instance):
        if (
            model_instance.auth_context == WorkspaceAuthContext.instance
            and not self.request.user.is_superuser
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.facility
            and not AuthorizationController.call(
                "can_access_facility_workspace",
                self.request.user,
                model_instance.facility,
                None,
                read_only=False,
            )
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.facility_organization
            and not AuthorizationController.call(
                "can_access_facility_organization_workspace",
                self.request.user,
                model_instance.facility_organization,
                read_only=False,
            )
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.user
            and not AuthorizationController.call(
                "can_access_user_workspace_in_facility",
                self.request.user,
                model_instance.facility,
                read_only=False,
            )
        ):
            raise PermissionDenied("You are not authorized to create a workspace")
        if (
            model_instance.auth_context == WorkspaceAuthContext.user
            and model_instance.created_by != self.request.user
        ):
            raise PermissionDenied("Only the creator of the workspace can update it")

    def authorize_destroy(self, instance):
        self.authorize_update(self.request, instance)

    def perform_create(self, instance):
        super().perform_create(instance)
        instance.sync_facility_org_cache()

    def get_queryset(self):
        queryset = super().get_queryset()
        return AuthorizationController.call(
            "get_filtered_workspaces", queryset, self.request.user
        )

    @action(detail=True, methods=["GET"])
    def get_facility_organizations(self, request, *args, **kwargs):
        workspace = self.get_object()
        if not workspace.auth_context == WorkspaceAuthContext.facility:
            raise PermissionDenied(
                "Facility organizations can only be set for facility level workspaces"
            )
        self.authorize_update(None, workspace)
        workspace_organizations = WorkspaceFacilityOrganization.objects.filter(
            workspace=workspace
        ).select_related("organization")
        organizations = [
            FacilityOrganizationReadSpec.serialize(obj.organization).to_json()
            for obj in workspace_organizations
        ]
        return Response(
            {
                "count": len(organizations),
                "results": organizations,
            }
        )

    class WorkspaceFacilityOrganizationUpdateSchema(BaseModel):
        facility_organizations: list[UUID4]

    @extend_schema(request=WorkspaceFacilityOrganizationUpdateSchema)
    @action(detail=True, methods=["POST"])
    def set_facility_organizations(self, request, *args, **kwargs):
        workspace = self.get_object()
        if not workspace.auth_context == WorkspaceAuthContext.facility:
            raise PermissionDenied(
                "Facility organizations can only be set for facility level workspaces"
            )
        self.authorize_update(None, workspace)
        request_params = self.WorkspaceFacilityOrganizationUpdateSchema(**request.data)
        with transaction.atomic():
            WorkspaceFacilityOrganization.objects.filter(workspace=workspace).delete()
            for org in request_params.facility_organizations:
                organization = get_object_or_404(
                    FacilityOrganization.objects.only("id"),
                    external_id=org,
                    facility=workspace.facility,
                )
                WorkspaceFacilityOrganization.objects.create(
                    workspace=workspace, organization=organization
                )
            workspace.sync_facility_org_cache()
        return Response({})

    class WorkspaceDefaultSetSchema(BaseModel):
        attribute: str | None = None
        value: str

    @extend_schema(request=WorkspaceDefaultSetSchema)
    @action(detail=True, methods=["POST"])
    def set_default_attributes(self, request, *args, **kwargs):
        workspace = self.get_object()
        request_params = self.WorkspaceDefaultSetSchema(**request.data)
        with transaction.atomic():
            workspace_qs = WorkSpaceUserDefault.objects.filter(
                workspace=workspace, user=self.request.user
            )
            if request_params.attribute:
                workspace_qs = workspace_qs.filter(attribute=request_params.attribute)
            else:
                workspace_qs = workspace_qs.filter(attribute__isnull=True)
            workspace_qs.delete()
            WorkSpaceUserDefault.objects.create(
                workspace=workspace,
                attribute=request_params.attribute,
                value=request_params.value,
                user=self.request.user,
            )
        return Response({})

    @action(detail=False, methods=["GET"])
    def get_user_default_attributes(self, request, *args, **kwargs):
        cache_key = WorkSpaceUserDefault.get_cache_key(self.request.user.id)
        results = cache.get(cache_key)
        if results is None:
            user_default_attributes = WorkSpaceUserDefault.objects.filter(
                user=self.request.user
            ).select_related("workspace")
            results = [
                {
                    "attribute": obj.attribute,
                    "value": obj.value,
                    "workspace": WorkspaceMinimalReadSpec.serialize(
                        obj.workspace
                    ).to_json(),
                }
                for obj in user_default_attributes
            ]
            cache.set(cache_key, results)
        return Response({"count": len(results), "results": results})
from django.contrib.postgres.fields import ArrayField
from django.core.cache import cache
from django.db import models
from django.db.models.signals import post_delete
from django.dispatch import receiver

from care.emr.models import EMRBaseModel
from care.emr.models.organization import FacilityOrganization
from care.users.models import User

WORKSPACE_USER_DEFAULT_CACHE_KEY = "workspace_user_default:{user_id}"


class Workspace(EMRBaseModel):
    facility = models.ForeignKey(
        "facility.Facility", on_delete=models.CASCADE, null=True, blank=True
    )
    facility_organization = models.ForeignKey(
        "emr.FacilityOrganization", on_delete=models.CASCADE, null=True, blank=True
    )
    auth_context = models.CharField(max_length=255, default="instance")
    name = models.CharField(max_length=255)
    description = models.TextField(default="")
    template = models.JSONField(default=dict)
    internal_organization_cache = ArrayField(models.IntegerField(), default=list)

    def sync_facility_org_cache(self):
        from care.emr.resources.workspace.spec import WorkspaceAuthContext

        if self.auth_context == WorkspaceAuthContext.facility_organization:
            organization_ids = [
                *self.facility_organization.parent_cache,
                self.facility_organization.id,
            ]
        elif self.auth_context == WorkspaceAuthContext.facility:
            workspace_organization_objects = (
                WorkspaceFacilityOrganization.objects.filter(
                    workspace=self
                ).select_related("organization")
            )
            organization_ids = []
            for workspace_organization_object in workspace_organization_objects:
                organization_ids.extend(
                    workspace_organization_object.organization.parent_cache
                )
                organization_ids.append(workspace_organization_object.organization.id)
        else:
            return
        self.internal_organization_cache = list(set(organization_ids))
        self.save(update_fields=["internal_organization_cache"])

    def save(self, *args, **kwargs):
        super().save(*args, **kwargs)
        self.invalidate_user_default_cache()

    def invalidate_user_default_cache(self):
        user_ids = WorkSpaceUserDefault.objects.filter(
            workspace_id=self.id
        ).values_list("user_id", flat=True)
        cache.delete_many(
            [WorkSpaceUserDefault.get_cache_key(user_id) for user_id in user_ids]
        )


class WorkspaceFacilityOrganization(EMRBaseModel):
    workspace = models.ForeignKey(Workspace, on_delete=models.CASCADE)
    organization = models.ForeignKey(FacilityOrganization, on_delete=models.CASCADE)


class WorkSpaceUserDefault(EMRBaseModel):
    workspace = models.ForeignKey(Workspace, on_delete=models.CASCADE)
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    attribute = models.CharField(max_length=255, null=True, blank=True)
    value = models.CharField(max_length=255, null=True, blank=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["workspace", "user", "attribute", "value"],
                condition=models.Q(deleted=False),
                nulls_distinct=False,
                name="unique_workspace_user_attribute_value",
            )
        ]

    @classmethod
    def get_cache_key(cls, user_id):
        return WORKSPACE_USER_DEFAULT_CACHE_KEY.format(user_id=user_id)

    def save(self, *args, **kwargs):
        super().save(*args, **kwargs)
        self.invalidate_cache()

    def invalidate_cache(self):
        if self.user_id:
            cache.delete(self.get_cache_key(self.user_id))


@receiver(post_delete, sender=WorkSpaceUserDefault)
def invalidate_workspace_user_default_cache(sender, instance, **kwargs):
    instance.invalidate_cache()
from enum import Enum

from pydantic import UUID4, field_validator, model_validator

from care.emr.models.organization import FacilityOrganization
from care.emr.models.workspace import Workspace
from care.emr.resources.base import EMRResource
from care.facility.models.facility import Facility
from care.utils.shortcuts import get_object_or_404


class WorkspaceAuthContext(str, Enum):
    instance = "instance"
    facility_organization = "facility_organization"
    facility = "facility"
    user = "user"


class WorkspaceBaseSpec(EMRResource):
    __model__ = Workspace

    id: UUID4 = None
    name: str
    description: str
    template: dict


class WorkspaceCreateSpec(WorkspaceBaseSpec):
    auth_context: WorkspaceAuthContext
    facility: UUID4 | None = None
    facility_organization: UUID4 | None = None
    inherited: bool

    def perform_extra_deserialization(self, is_update, obj):
        if obj.auth_context in (
            WorkspaceAuthContext.facility,
            WorkspaceAuthContext.user,
        ):
            obj.facility = get_object_or_404(
                Facility.objects.only("id"), external_id=self.facility
            )

        if obj.auth_context == WorkspaceAuthContext.facility_organization:
            obj.facility_organization = get_object_or_404(
                FacilityOrganization, external_id=self.facility_organization
            )
            obj.facility = obj.facility_organization.facility
            obj.internal_organization_cache = [
                *obj.facility_organization.parent_cache,
                obj.facility_organization.id,
            ]

    @field_validator("facility")
    @classmethod
    def validate_facility(cls, facility: UUID4):
        if facility and not Facility.objects.filter(external_id=facility).exists():
            err = "Facility not found"
            raise ValueError(err)
        return facility

    @field_validator("facility_organization")
    @classmethod
    def validate_facility_organization(cls, facility_organization: UUID4):
        if (
            facility_organization
            and not FacilityOrganization.objects.filter(
                external_id=facility_organization
            ).exists()
        ):
            err = "Facility organization not found"
            raise ValueError(err)
        return facility_organization

    @model_validator(mode="after")
    def validate_unique_id(self):
