        </Alert>
      )}
      {hasConflictingDefaults && (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_conflicting_defaults")}
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.error === "unsupported_schema"
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
