import { useQuery } from "@tanstack/react-query";

import useAuthUser from "@/hooks/useAuthUser";

import { EncounterClass } from "@/types/emr/encounter/encounter";
import workspaceApi from "@/types/workspace/workspaceApi";
import query from "@/Utils/request/query";

/** Defaults are encounter matching rules; facility scope belongs to the workspace. */
export function useEncounterWorkspaces(
  facilityId: string,
  encounterClass?: EncounterClass,
) {
  const user = useAuthUser();
  const defaults = useQuery({
    queryKey: ["workspace-user-defaults", user.id, "encounter"],
    queryFn: query(workspaceApi.getUserDefaultAttributes, { silent: true }),
    retry: false,
  });
  const matches =
    defaults.data?.results.filter(
      ({ attribute, value, workspace }) =>
        attribute === "encounter_class" &&
        value === encounterClass &&
        workspace.facility === facilityId &&
        (workspace.auth_context !== "user" ||
          workspace.created_by?.id === user.id),
    ) ?? [];
  const workspaces = [
    ...new Map(
      matches.map(({ workspace }) => [workspace.id, workspace]),
    ).values(),
  ];

  return {
    defaults,
    workspace:
      !defaults.isError && workspaces.length === 1 ? workspaces[0] : undefined,
    hasConflictingDefaults: workspaces.length > 1,
  };
}
import {
  Activity,
  ClipboardList,
  HeartPulse,
  LayoutDashboard,
  PanelsTopLeft,
  Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate } from "raviger";
import { useEffect } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};

interface EncounterWorkspaceContentProps {
  facilityId: string;
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  facilityId,
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const { defaults, workspace, hasConflictingDefaults } =
    useEncounterWorkspaces(facilityId, selectedEncounter?.encounter_class);
  const parsed = workspace
    ? parseEncounterWorkspaceTemplate(
        workspace.template,
        Object.keys(systemTabs),
      )
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed?.success) {
    for (const page of parsed.template.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon:
            page.icon && Object.hasOwn(customPageIcons, page.icon)
              ? customPageIcons[page.icon]
              : LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      }
    }
  }
  for (const [key, tab] of Object.entries(systemTabs)) {
    if (!Object.hasOwn(tabs, key)) tabs[key] = tab;
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection = defaults.isLoading || isSelectedEncounterLoading;

  const navigateToTab = (tab: string, replace = false) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (!isLoadingSelection) {
      if (!defaults.isError && firstVisibleTab && activeTab !== currentTab)
        navigateToTab(activeTab, true);
      else if (new URLSearchParams(window.location.search).has("workspace"))
        navigateToTab(currentTab, true);
    }
  });

  return (
    <div className="space-y-3">
      {defaults.isError && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => defaults.refetch()}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {hasConflictingDefaults && (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_conflicting_defaults")}
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.error === "unsupported_schema"
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
import { UserReadMinimal } from "@/types/user/user";

export const WORKSPACE_AUTH_CONTEXTS = [
  "instance",
  "facility",
  "facility_organization",
  "user",
] as const;

export type WorkspaceAuthContext = (typeof WORKSPACE_AUTH_CONTEXTS)[number];

export type WorkspaceAdminScope = Extract<
  WorkspaceAuthContext,
  "instance" | "facility"
>;

export type WorkspaceScope =
  | {
      authContext: "instance";
      basePath: string;
      facilityId?: never;
    }
  | {
      authContext: "facility";
      basePath: string;
      facilityId: string;
    };

export const INSTANCE_WORKSPACE_SCOPE: WorkspaceScope = {
  authContext: "instance",
  basePath: "/admin/workspaces",
};

export function workspaceScopeForFacility(facilityId: string): WorkspaceScope {
  return {
    authContext: "facility",
    facilityId,
    basePath: `/facility/${facilityId}/settings/workspaces`,
  };
}

export const WORKSPACE_PERMISSIONS = {
  read: "can_read_workspace",
  write: "can_write_workspace",
} as const;

/** The backend accepts an arbitrary JSON object without prescribing its keys. */
export type WorkspaceTemplate = Record<string, unknown>;

export interface WorkspaceBase {
  name: string;
  description: string;
  template: WorkspaceTemplate;
}

export interface WorkspaceMinimalRead extends WorkspaceBase {
  id: string;
}

export interface WorkspaceRead extends WorkspaceMinimalRead {
  auth_context: WorkspaceAuthContext;
  facility: string | null;
  facility_organization: string | null;
  permissions: string[];
  created_by: UserReadMinimal | null;
  updated_by: UserReadMinimal | null;
}

export interface WorkspaceCreate extends WorkspaceBase {
  auth_context: WorkspaceAuthContext;
  /** Required for facility and user workspaces. */
  facility?: string | null;
  /** Required for facility_organization workspaces. */
  facility_organization?: string | null;
}

/** Scope and facility cannot be changed after creation. */
export type WorkspaceUpdate = WorkspaceBase;

export interface WorkspaceFacilityOrganizationsUpdate {
  /** Replaces the entire association list with organizations from this facility. */
  facility_organizations: string[];
}

export interface WorkspaceDefaultAttributesUpdate {
  attribute?: string | null;
  value: string;
}

export interface WorkspaceDefaultAttributesReset {
  attribute?: string | null;
  /** Omit to clear all values for the attribute. */
  value?: string | null;
}

export interface WorkspaceUserDefaultAttributes {
  attribute: string | null;
  value: string | null;
  workspace: WorkspaceRead;
}

