import workspaceApi from "@/types/workspace/workspaceApi";

export async function loadScopedWorkspace(
  scope: WorkspaceScope,
  id: string,
  signal: AbortSignal,
) {
  const workspace = await callApi(workspaceApi.get, {
    pathParams: { id },
    signal,
  });

  // Detail lookups do not apply list filters. Check the returned ownership
  // before mounting an editor, including when opening a copied URL.
  const matchesScope =
    scope.authContext === "instance"
      ? workspace.auth_context === "instance"
      : workspace.auth_context !== "instance" &&
        workspace.facility === scope.facilityId;
