import { Check, Loader2 } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

import { WorkspaceRead } from "@/types/workspace/workspace";

interface EncounterWorkspacePickerProps {
  workspaces: WorkspaceRead[];
  workspaceId?: string;
  isLoading: boolean;
  isError: boolean;
  onRetry: () => void;
  onSelect: (workspace: WorkspaceRead) => void;
  isSaving: boolean;
  saveError: boolean;
  onSelectStandard?: () => void;
}

export function EncounterWorkspacePicker({
  workspaces,
  workspaceId,
  isLoading,
  isError,
  onRetry,
  onSelect,
  isSaving,
  saveError,
  onSelectStandard,
}: EncounterWorkspacePickerProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const wasSaving = useRef(false);
  const currentWorkspace = workspaces.find(({ id }) => id === workspaceId);
  const currentName = workspaceId
    ? (currentWorkspace?.name ?? t("encounter_workspace_unavailable"))
    : t("encounter_workspace_standard");
  const busy = isLoading || isError || isSaving;
  const scopeLabels = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };

  useEffect(() => {
    if (wasSaving.current && !isSaving && !saveError) setOpen(false);
    wasSaving.current = isSaving;
  }, [isSaving, saveError]);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="outline"
              size="icon"
              aria-label={t("encounter_workspace")}
              className="size-9 shrink-0 rounded-lg border-gray-200 bg-white text-sm font-bold text-gray-700 shadow-none"
            >
              {isSaving ? (
                <Loader2 className="size-4 animate-spin" aria-hidden="true" />
              ) : (
                <span aria-hidden="true">W</span>
              )}
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent side="bottom">
          {isLoading
            ? t("encounter_workspace_loading")
            : t("encounter_workspace_current", { name: currentName })}
        </TooltipContent>
      </Tooltip>
      <PopoverContent
        align="end"
        className="w-80 max-w-[calc(100vw-2rem)] p-0"
        aria-label={t("encounter_workspace")}
      >
        <div className="border-b px-3 py-2.5">
          <h2 className="text-sm font-semibold">{t("encounter_workspace")}</h2>
          <p className="mt-0.5 text-xs text-gray-500">
            {t("encounter_workspace_picker_hint")}
          </p>
        </div>
        {isError && (
          <div className="p-2">
            <Alert variant="destructive">
              <AlertDescription className="space-y-2">
                <p>{t("encounter_workspace_list_error")}</p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={onRetry}
                >
                  {t("try_again")}
                </Button>
              </AlertDescription>
            </Alert>
          </div>
        )}
        {saveError && (
          <div className="p-2">
            <Alert variant="destructive">
              <AlertDescription>
                {t("encounter_workspace_select_error")}
              </AlertDescription>
            </Alert>
          </div>
        )}
        <Command>
          <CommandInput
            placeholder={t("search_workspaces")}
            aria-label={t("search_workspaces")}
            disabled={isLoading || isSaving}
          />
          <CommandList aria-label={t("workspaces")}>
            {isLoading ? (
              <div
                className="space-y-2 p-3"
                role="status"
                aria-label={t("encounter_workspace_loading")}
              >
                <Skeleton className="h-12 w-full" />
                <Skeleton className="h-12 w-full" />
              </div>
            ) : (
              <>
                <CommandEmpty>{t("no_workspaces_found")}</CommandEmpty>
                <CommandGroup>
                  <CommandItem
                    value="standard-encounter"
                    keywords={[t("encounter_workspace_standard")]}
                    disabled={busy || !onSelectStandard}
                    onSelect={() => {
                      if (!busy && onSelectStandard) onSelectStandard();
                    }}
                    className="items-start gap-2 px-3 py-2.5"
                  >
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-medium">
                        {t("encounter_workspace_standard")}
                      </p>
                      <p className="mt-0.5 text-xs text-gray-500">
                        {t("encounter_workspace_standard_hint")}
                      </p>
                    </div>
                    {!workspaceId && (
                      <Check
                        className="mt-0.5 size-4 text-primary-600"
                        aria-label={t("selected")}
                      />
                    )}
                  </CommandItem>
                  {workspaces.map((workspace) => (
                    <CommandItem
                      key={workspace.id}
                      value={workspace.id}
                      keywords={[
                        workspace.name,
                        workspace.description,
                        scopeLabels[workspace.auth_context],
                      ]}
                      disabled={busy}
                      onSelect={() => {
                        if (busy) return;
                        if (workspace.id === workspaceId) setOpen(false);
                        else onSelect(workspace);
                      }}
                      className="items-start gap-2 px-3 py-2.5"
                    >
                      <div className="min-w-0 flex-1">
                        <p className="break-words text-sm font-medium">
                          {workspace.name}
                        </p>
                        <p className="mt-0.5 text-xs text-gray-500">
                          {scopeLabels[workspace.auth_context]}
                        </p>
                        {workspace.description && (
                          <p className="mt-1 line-clamp-2 break-words text-xs text-gray-600">
                            {workspace.description}
                          </p>
                        )}
                      </div>
                      {workspace.id === workspaceId && (
                        <Check
                          className="mt-0.5 size-4 text-primary-600"
                          aria-label={t("selected")}
                        />
                      )}
                    </CommandItem>
                  ))}
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
{
  "encounter_workspace_current": "Workspace: {{name}}",
  "encounter_workspace_picker_hint": "Choose a workspace for your encounters.",
  "encounter_workspace_select_error": "Could not select this workspace. Please try again.",
  "encounter_workspace_standard_hint": "Built-in encounter pages"
}
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
