from django.db.models import Q

from care.emr.models.organization import FacilityOrganizationUser
from care.security.authorization.base import (
    AuthorizationController,
    AuthorizationHandler,
)
from care.security.permissions.workspace import WorkspacePermissions


class WorkspaceAccess(AuthorizationHandler):
    def can_access_facility_workspace(self, user, facility, workspace, read_only):
        """
        Permission to access a workspace for a specific facility
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
            return self.check_permission_in_facility_organization(
                permission,
                user,
                facility=facility,
                orgs=workspace.internal_organization_cache,
            )
        permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission, user, facility=facility, root=True
        )

    def can_access_facility_organization_workspace(
        self, user, facility_organization, read_only
    ):
        """
        Permission to access a workspace for a specific facility organization
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
        else:
            permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission,
            user,
            facility=facility_organization.facility,
            orgs=[*facility_organization.parent_cache, facility_organization.id],
        )

    def can_access_user_workspace_in_facility(self, user, facility, read_only):
        """
        Permission to write a workspace for a specific facility as a user
        """
        if read_only:
            permission = [WorkspacePermissions.can_read_workspace.name]
        else:
            permission = [WorkspacePermissions.can_write_workspace.name]
        return self.check_permission_in_facility_organization(
            permission,
            user,
            facility=facility,
        )

    def get_filtered_workspaces(self, qs, user):
        if user.is_superuser:
            return qs
        roles = self.get_role_from_permissions(
            [WorkspacePermissions.can_read_workspace.name]
        )
        facility_organization_ids = list(
            FacilityOrganizationUser.objects.filter(
                user=user, role_id__in=roles
            ).values_list("organization_id", flat=True)
        )
        write_roles = self.get_role_from_permissions(
            [WorkspacePermissions.can_write_workspace.name]
        )
        writable_facility_ids = FacilityOrganizationUser.objects.filter(
            user=user,
            role_id__in=write_roles,
            organization__org_type="root",
        ).values_list("organization__facility_id", flat=True)
        return qs.filter(
            Q(auth_context="instance")
            | Q(internal_organization_cache__overlap=facility_organization_ids)
            | Q(auth_context="user", created_by=user)
            | Q(auth_context="facility", facility_id__in=writable_facility_ids)
        )


AuthorizationController.register_internal_controller(WorkspaceAccess)
import inspect

from care.emr.models.organization import FacilityOrganizationUser, OrganizationUser
from care.security.models import RolePermission


class PermissionDeniedError(Exception):
    pass


class AuthorizationHandler:
    """
    Base class for Authorization Handlers.

    Handlers must define a list of actions that can be performed and implement
    the corresponding ``can_<action>()`` or ``get_<query>()`` methods that
    perform the authorization logic.

    All authorization methods use the signature ``(user, obj, **kwargs)``.
    ``obj`` refers to the target object for which permission is being
    evaluated. It may also be a string or any other type as long as the logic
    accounts for it.

    Notes:
    * Actions (``can_`` prefixed) return booleans.
    * Queries (``get_`` prefixed) return querysets or collections.
    """

    actions = []
    queries = []

    def check_permission_in_organization(self, permissions, user, orgs=None):
        if user.is_superuser:
            return True
        roles = self.get_role_from_permissions(permissions)
        filters = {"role_id__in": roles, "user": user}
        if orgs:
            filters["organization_id__in"] = orgs
        return OrganizationUser.objects.filter(**filters).exists()

    def check_permission_in_facility_organization(
        self, permissions, user, orgs=None, facility=None, root=None
    ):
        if user.is_superuser:
            return True

        for perm in permissions:
            roles = self.get_role_from_permissions([perm])
            filters = {"role_id__in": roles, "user": user}
            if orgs is not None:
                filters["organization_id__in"] = orgs
            if facility is not None:
                filters["organization__facility"] = facility
            if root:
                filters["organization__org_type"] = "root"
            if not FacilityOrganizationUser.objects.filter(**filters).exists():
                return False

        return True

    def get_role_from_permissions(self, permissions):
        # TODO Cache this endpoint
        return list(
            set(
                RolePermission.objects.filter(
                    permission__slug__in=permissions
                ).values_list("role_id", flat=True)
            )
        )


class AuthorizationController:
    """
    Someone please write this because i honestly forgot what this does
    """

    override_authz_controllers: list[
        AuthorizationHandler
    ] = []  # The order is important
    # Override Security Controllers will be defined from plugs
    internal_authz_controllers: list[AuthorizationHandler] = []

    cache = {"actions": {}, "queries": {}}

    @classmethod
    def build_cache(cls):
        for controller in (
            cls.internal_authz_controllers + cls.override_authz_controllers
        ):
            for method in inspect.getmembers(controller(), predicate=inspect.ismethod):
                if method[0].startswith("can_"):
                    cls.cache["actions"][method[0]] = controller
                if method[0].startswith("get_"):
                    cls.cache["queries"][method[0]] = controller

    @classmethod
    def call(cls, item, *args, **kwargs):
        if not cls.cache["actions"]:
            cls.build_cache()
        if item.startswith("can_"):
            if item in cls.cache["actions"]:
                return getattr(cls.cache["actions"][item](), item)(*args, **kwargs)
            raise ValueError("Invalid Action")
        if item.startswith("get_"):
            if item in cls.cache["queries"]:
                return getattr(cls.cache["queries"][item](), item)(*args, **kwargs)
            raise ValueError("Invalid Query")
        raise ValueError("Invalid Item")

    @classmethod
    def register_internal_controller(cls, controller):
        # TODO : Do some deduplication Logic
        cls.internal_authz_controllers.append(controller)

    @classmethod
    def register_override_controller(cls, controller):
        cls.override_authz_controllers.append(controller)

