}

async function mockEncounterWorkspaceApi(
  page: Page,
  options: { clinicalRead?: boolean; defaultLoadFailures?: number } = {},
) {
  let defaultLoadFailures = options.defaultLoadFailures ?? 0;
  const actor = user();
  const facility = {
    id: faker.string.uuid(),
    name: `Facility ${faker.word.words(2)}`,
    permissions: [
      "can_read_workspace",
      "can_list_patients",
      "can_list_encounter",
    ],
    root_org_permissions: [],
    features: [],
  };
  const facilities = [facility];
  const patient = {
    id: faker.string.uuid(),
    name: faker.person.fullName(),
    gender: "female",
    phone_number: "+919999999999",
    year_of_birth: 1980,
    date_of_birth: "1980-01-01",
    blood_group: "O+",
    deceased_datetime: null,
    created_date: "2026-01-01T00:00:00Z",
    modified_date: "2026-01-01T00:00:00Z",
    instance_tags: [],
    facility_tags: [],
    instance_identifiers: [],
    facility_identifiers: [],
    permissions:
      options.clinicalRead === false ? [] : ["can_view_clinical_data"],
  };
  const currentEncounter = {
    id: faker.string.uuid(),
    patient,
    facility,
    encounter_class: "amb",
    status: "in_progress",
    period: { start: "2026-10-01T08:00:00Z" },
