import { usePermissions } from "@/context/PermissionContext";
import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";
import { WorkspaceScope } from "@/types/workspace/workspace";

export function useWorkspacePermissions(scope: WorkspaceScope) {
  const { hasPermission, isSuperAdmin } = usePermissions();
  const { facility, facilityId, isFacilityLoading } =
    useCurrentFacilitySilently();

  const isFacility =
    scope.authContext === "facility" &&
    facilityId === scope.facilityId &&
    !!facility;
  const canCreateFacility =
    isFacility &&
    hasPermission("can_write_workspace", facility.root_org_permissions ?? []);
  const canWriteInFacility =
    isFacility &&
    hasPermission("can_write_workspace", facility.permissions ?? []);

  return {
    canWrite:
      scope.authContext === "instance" ? isSuperAdmin : canCreateFacility,
    canCreateFacility,
    canCreateDepartment: canWriteInFacility,
    canCreatePersonal: canWriteInFacility,
    isLoading: scope.authContext === "facility" && isFacilityLoading,
  };
}
import { useQuery } from "@tanstack/react-query";
import { ArrowLeft } from "lucide-react";
import { Link, useQueryParams } from "raviger";
import { useTranslation } from "react-i18next";

import Page from "@/components/Common/Page";
import { FormSkeleton } from "@/components/Common/SkeletonLoading";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import useAuthUser from "@/hooks/useAuthUser";

import {
  WorkspaceAuthContext,
  WorkspaceScope,
} from "@/types/workspace/workspace";

import { WorkspaceForm } from "./WorkspaceForm";
import { loadScopedWorkspace } from "./loadScopedWorkspace";
import { useWorkspacePermissions } from "./useWorkspacePermissions";

interface WorkspaceEditorProps {
  scope: WorkspaceScope;
  id?: string;
}

export function WorkspaceEditor({ scope, id }: WorkspaceEditorProps) {
  const { t } = useTranslation();
  const user = useAuthUser();
  const permissions = useWorkspacePermissions(scope);
  const { canWrite, isLoading: isPermissionLoading } = permissions;
  const [{ context }] = useQueryParams<{ context?: string }>();
  const allowedContexts: WorkspaceAuthContext[] =
    scope.authContext === "instance"
      ? canWrite
        ? ["instance"]
        : []
      : [
          ...(permissions.canCreateFacility ? ["facility" as const] : []),
          ...(permissions.canCreateDepartment
            ? ["facility_organization" as const]
            : []),
          ...(permissions.canCreatePersonal ? ["user" as const] : []),
        ];
  const initialContext =
    allowedContexts.find((option) => option === context) ?? allowedContexts[0];
  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: [
      "workspace",
      "configuration",
      "scoped",
      user.id,
      scope.authContext,
      scope.facilityId,
      id,
    ],
    queryFn: ({ signal }) => loadScopedWorkspace(scope, id ?? "", signal),
    enabled: !!id,
    retry: false,
  });

  if (isPermissionLoading || (id && isLoading)) {
    return <FormSkeleton rows={6} />;
  }

  if ((id && !data) || (!id && !initialContext)) {
    return (
      <Page title={t("workspaces")} hideTitleOnPage>
        <div className="mx-auto max-w-5xl space-y-4 p-4">
          <Alert variant="destructive">
            <AlertTitle>{t("error")}</AlertTitle>
            <AlertDescription>
              {t(id ? "workspace_load_error" : "workspace_create_forbidden")}
            </AlertDescription>
          </Alert>
          <div className="flex gap-2">
            <Button asChild variant="outline">
              <Link href={scope.basePath} basePath="/">
                <ArrowLeft className="size-4" />
                {t("back")}
              </Link>
            </Button>
            {id && (
              <Button variant="outline" onClick={() => refetch()}>
                {t("try_again")}
              </Button>
            )}
          </div>
        </div>
      </Page>
    );
  }

  return (
    <>
      {isError && (
        <Alert variant="destructive">
          <AlertDescription>{t("workspace_refresh_error")}</AlertDescription>
        </Alert>
      )}
      <WorkspaceForm
        key={`${user.id}:${scope.authContext}:${scope.facilityId ?? ""}:${id ?? initialContext}`}
        scope={scope}
        existing={id ? data?.workspace : undefined}
        existingContext={data?.authContext}
        canWrite={
          id
            ? data?.authContext === "instance"
              ? canWrite
              : data?.authContext === "facility"
                ? permissions.canCreateFacility
                : data?.authContext === "user"
                  ? permissions.canCreatePersonal &&
                    data.workspace.created_by?.id === user.id
                  : false
            : !!initialContext
        }
        initialContext={initialContext}
        allowedContexts={allowedContexts}
      />
    </>
  );
}

