    mutationFn: mutate(workspaceApi.delete, {
      pathParams: { id: existing?.id ?? "" },
    }),
    onSuccess: () => {
      queryClient.removeQueries({
        queryKey: [
          "workspace",
          "configuration",
          "scoped",
          user.id,
          scope.authContext,
          scope.facilityId,
          existing?.id,
        ],
      });
