import { UserReadMinimal } from "@/types/user/user";

export const WORKSPACE_AUTH_CONTEXTS = [
  "instance",
  "facility",
  "facility_organization",
  "user",
] as const;

export type WorkspaceAuthContext = (typeof WORKSPACE_AUTH_CONTEXTS)[number];

export type WorkspaceAdminScope = Extract<
  WorkspaceAuthContext,
  "instance" | "facility"
>;

export type WorkspaceScope =
  | {
      authContext: "instance";
      basePath: string;
      facilityId?: never;
    }
  | {
      authContext: "facility";
      basePath: string;
      facilityId: string;
    };

export const INSTANCE_WORKSPACE_SCOPE: WorkspaceScope = {
  authContext: "instance",
  basePath: "/admin/workspaces",
};

export function workspaceScopeForFacility(facilityId: string): WorkspaceScope {
  return {
    authContext: "facility",
    facilityId,
    basePath: `/facility/${facilityId}/settings/workspaces`,
  };
}

/** The backend accepts an arbitrary JSON object without prescribing its keys. */
export type WorkspaceTemplate = Record<string, unknown>;

export interface WorkspaceBase {
  name: string;
  description: string;
  template: WorkspaceTemplate;
}

export interface WorkspaceMinimalRead extends WorkspaceBase {
  id: string;
}

export interface WorkspaceRead extends WorkspaceMinimalRead {
  created_by: UserReadMinimal | null;
  updated_by: UserReadMinimal | null;
}

export interface WorkspaceCreate extends WorkspaceBase {
  auth_context: WorkspaceAuthContext;
  inherited: false;
  /** Required for facility and user workspaces. */
  facility?: string | null;
  /** Required for facility_organization workspaces. */
  facility_organization?: string | null;
}

/** Scope and facility cannot be changed after creation. */
export type WorkspaceUpdate = WorkspaceBase;

export interface WorkspaceFacilityOrganizationsUpdate {
  /** Replaces the entire association list with organizations from this facility. */
  facility_organizations: string[];
}

export interface WorkspaceDefaultAttributesUpdate {
  attribute?: string | null;
  value: string;
}

export interface WorkspaceUserDefaultAttributes {
  attribute: string | null;
  value: string | null;
  workspace: WorkspaceMinimalRead;
}
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { ArrowLeft, Braces, Loader2, Trash2 } from "lucide-react";
import { Link, navigate, useNavigationPrompt } from "raviger";
import { useState } from "react";
import { flushSync } from "react-dom";
import { useForm, useWatch } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import Page from "@/components/Common/Page";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

import useAuthUser from "@/hooks/useAuthUser";
import { useCareAppTabs } from "@/hooks/useCareApps";
import FacilityOrganizationSelector from "@/pages/Facility/settings/organizations/components/FacilityOrganizationSelector";

import mutate from "@/Utils/request/mutate";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";
import {
  WORKSPACE_AUTH_CONTEXTS,
  WorkspaceAuthContext,
  WorkspaceRead,
  WorkspaceScope,
  WorkspaceTemplate,
} from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";

import { WorkspaceOrganizationsField } from "./WorkspaceOrganizationsField";

interface WorkspaceFormValues {
  name: string;
  description: string;
  template: string;
  authContext: WorkspaceAuthContext;
  departmentId: string;
}

interface WorkspaceFormProps {
  scope: WorkspaceScope;
  existing?: WorkspaceRead;
  existingContext?: WorkspaceAuthContext;
  initialContext?: WorkspaceAuthContext;
  allowedContexts: WorkspaceAuthContext[];
}

function parseTemplate(value: string): WorkspaceTemplate {
  const parsed: unknown = JSON.parse(value);
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Expected a JSON object");
  }
  return parsed as WorkspaceTemplate;
}

export function WorkspaceForm({
  scope,
  existing,
  existingContext,
  initialContext,
  allowedContexts,
}: WorkspaceFormProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const user = useAuthUser();
  const pluginTabs = useCareAppTabs("encounterTabs");
  const [accessState, setAccessState] = useState({
    dirty: false,
    pending: false,
  });
  const [deleteOpen, setDeleteOpen] = useState(false);
  const schema = z
    .object({
      name: z
        .string()
        .trim()
        .min(1, t("workspace_name_required"))
        .max(255, t("workspace_name_too_long")),
      description: z.string(),
      template: z.string().superRefine((value, ctx) => {
        try {
          const template = parseTemplate(value);
          if ("schema_version" in template || "pages" in template) {
            const parsed = parseEncounterWorkspaceTemplate(
              template,
              Object.keys(pluginTabs),
            );
            if (!parsed.success) {
              ctx.addIssue({
                code: "custom",
                message: t("encounter_workspace_template_invalid"),
              });
            }
          }
        } catch {
          ctx.addIssue({
            code: "custom",
            message: t("workspace_template_invalid"),
          });
        }
      }),
      authContext: z.enum(WORKSPACE_AUTH_CONTEXTS),
      departmentId: z.string(),
    })
    .superRefine((values, ctx) => {
      if (
        !existing &&
        values.authContext === "facility_organization" &&
        !values.departmentId
      ) {
        ctx.addIssue({
          code: "custom",
          path: ["departmentId"],
          message: t("workspace_department_required"),
        });
      }
    });
  const form = useForm<WorkspaceFormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      name: existing?.name ?? "",
      description: existing?.description ?? "",
      template: JSON.stringify(existing?.template ?? {}, null, 2),
      authContext: existingContext ?? initialContext ?? scope.authContext,
      departmentId: "",
    },
  });
  const authContext = useWatch({ control: form.control, name: "authContext" });
  const templateValue = useWatch({ control: form.control, name: "template" });
  let unsupportedWidgets: string[] = [];
  try {
    const parsed = parseEncounterWorkspaceTemplate(
      JSON.parse(templateValue),
      Object.keys(pluginTabs),
    );
    if (parsed.success) unsupportedWidgets = parsed.unsupportedWidgetTypes;
  } catch {
    // JSON validation is shown on submission or when Format JSON is used.
  }
  const returnPath =
    scope.authContext === "facility" && authContext !== "facility"
      ? `${scope.basePath}?context=${authContext}`
      : scope.basePath;
  const contextLabel = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };
  const contextDescription = {
    instance: t("workspace_instance_description"),
    facility: t("workspace_facility_description"),
    facility_organization: t("workspace_department_description"),
    user: t("workspace_personal_description"),
  };

  const title = t(existing ? "edit_workspace" : "create_workspace");
  const dirty = form.formState.isDirty || accessState.dirty;
  useNavigationPrompt(dirty, t("unsaved_changes_warning"));

  const save = useMutation({
    mutationFn: (values: WorkspaceFormValues) => {
      const body = {
        name: values.name,
        description: values.description,
        template: parseTemplate(values.template),
      };
      return existing
        ? mutate(workspaceApi.update, { pathParams: { id: existing.id } })(body)
        : mutate(workspaceApi.create)({
            ...body,
            auth_context: values.authContext,
            inherited: false,
            ...(scope.authContext === "facility"
              ? { facility: scope.facilityId }
              : {}),
            ...(values.authContext === "facility_organization"
              ? { facility_organization: values.departmentId }
              : {}),
          });
    },
    onSuccess: (data, values) => {
      // Responses omit ownership metadata; preserve the submitted scope and
      // refresh exact-ID membership before mounting the saved editor.
      queryClient.invalidateQueries({
        queryKey: [
          "workspace",
          "configuration",
          "scoped",
          user.id,
          scope.authContext,
          scope.facilityId,
          data.id,
        ],
      });
      queryClient.invalidateQueries({ queryKey: ["workspaces"] });
      flushSync(() =>
        form.reset({
          name: data.name,
          description: data.description,
          template: JSON.stringify(data.template, null, 2),
          authContext: values.authContext,
          departmentId: values.departmentId,
        }),
      );
      toast.success(t(existing ? "workspace_updated" : "workspace_created"));
      if (!existing) navigate(`${scope.basePath}/${data.id}/edit`);
    },
  });

  const remove = useMutation({
    mutationFn: mutate(workspaceApi.delete, {
      pathParams: { id: existing?.id ?? "" },
    }),
    onSuccess: () => {
      queryClient.removeQueries({
        queryKey: [
          "workspace",
          "configuration",
          "scoped",
          user.id,
          scope.authContext,
          scope.facilityId,
          existing?.id,
        ],
      });
      queryClient.invalidateQueries({ queryKey: ["workspaces"] });
      flushSync(() => {
        form.reset(form.getValues());
        setAccessState({ dirty: false, pending: false });
        setDeleteOpen(false);
      });
      queryClient.invalidateQueries({ queryKey: ["workspace-user-defaults"] });
      toast.success(t("workspace_deleted"));
      navigate(returnPath);
    },
  });
  const busy = save.isPending || remove.isPending || accessState.pending;

  const formatTemplate = () => {
    try {
      form.setValue(
        "template",
        JSON.stringify(parseTemplate(form.getValues("template")), null, 2),
        { shouldDirty: true, shouldValidate: true },
      );
    } catch {
      form.setError(
        "template",
        { message: t("workspace_template_invalid") },
        { shouldFocus: true },
      );
    }
  };

  return (
    <Page title={title} hideTitleOnPage>
      <div className="mx-auto max-w-6xl space-y-6 px-3 py-6 sm:px-0">
        <div className="flex flex-wrap items-center gap-3">
          <Button asChild variant="outline" size="sm" disabled={busy}>
            <Link
              href={returnPath}
              basePath="/"
              onClick={(event) => {
                if (busy) event.preventDefault();
              }}
            >
              <ArrowLeft className="size-4" />
              {t("back")}
            </Link>
