import { AlertCircle, History } from "lucide-react";
import { Link, useFullPath, useQueryParams } from "raviger";
import { ReactNode } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import { EncounterAccordionLayout } from "@/components/Patient/EncounterAccordionLayout";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";

interface ClinicalQueryState {
  isPending: boolean;
  isError: boolean;
  isFetching: boolean;
  isFetchingNextPage: boolean;
  hasNextPage: boolean;
  data?: { pages: { results: unknown[] }[] };
  refetch: () => unknown;
  fetchNextPage: () => unknown;
}

interface WorkspaceClinicalWidgetPanelProps {
  title: string;
  questionnaire: "allergy_intolerance" | "symptom" | "diagnosis";
  history: "allergies" | "symptoms" | "diagnoses";
  emptyMessage: string;
  queryState: ClinicalQueryState;
  children: ReactNode;
}

export function WorkspaceClinicalWidgetPanel({
  title,
  questionnaire,
  history,
  emptyMessage,
  queryState,
  children,
}: WorkspaceClinicalWidgetPanelProps) {
  const { t } = useTranslation();
  const { facilityId, patientId, selectedEncounterId, canWriteClinicalData } =
    useEncounter();
  const fullPath = useFullPath();
  const [queryParams] = useQueryParams<Record<string, string>>();
  const search = new URLSearchParams(queryParams).toString();
  const sourceUrl = search ? `${fullPath}?${search}` : fullPath;
  const editSearch = `?${new URLSearchParams({ return_page: fullPath.split("/").pop() ?? "updates" })}`;
  const patientPath = facilityId
    ? `/facility/${facilityId}/patient/${patientId}`
    : `/patient/${patientId}`;
  const hasData = queryState.data?.pages.some((page) => page.results.length);

  return (
    <section aria-label={title} className="min-w-0">
      <EncounterAccordionLayout
        presentation="panel"
        title={title}
        readOnly={!canWriteClinicalData}
        className="min-w-0 overflow-hidden"
        editLink={
          canWriteClinicalData
            ? `${patientPath}/encounter/${selectedEncounterId}/questionnaire/${questionnaire}${editSearch}`
            : undefined
        }
        actionButton={
          <Button variant="ghost" size="icon" asChild>
            <Link
              href={`${patientPath}/history/${history}?sourceUrl=${encodeURIComponent(sourceUrl)}`}
              aria-label={t("view_history")}
            >
              <History className="size-4" aria-hidden="true" />
            </Link>
          </Button>
        }
      >
        {queryState.isPending ? (
          <div
            className="space-y-2 p-2"
            role="status"
            aria-label={t("loading")}
          >
            <Skeleton className="h-14 w-full" />
            <Skeleton className="h-14 w-full" />
          </div>
        ) : (
          <div className="space-y-3">
            {queryState.isError && (
              <Alert variant="destructive">
                <AlertCircle aria-hidden="true" />
                <AlertDescription>
                  <p>{t("encounter_workspace_clinical_load_error")}</p>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    disabled={queryState.isFetching}
                    onClick={() => queryState.refetch()}
                  >
                    {t("try_again")}
                  </Button>
                </AlertDescription>
              </Alert>
            )}
            {hasData ? (
              // Existing clinical tables expose cards first and the table second.
              // Use the panel width to choose the presentation in custom columns.
              <div className="@container/clinical-widget">
                <div className="[&>div:first-child]:block [&>div:last-child]:hidden @3xl/clinical-widget:[&>div:first-child]:hidden @3xl/clinical-widget:[&>div:last-child]:block">
                  {children}
                </div>
              </div>
            ) : (
              !queryState.isError && (
                <p className="px-2 py-5 text-sm text-gray-500">
                  {emptyMessage}
                </p>
              )
            )}
            {queryState.hasNextPage && (
              <div className="flex justify-center">
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  disabled={queryState.isFetchingNextPage}
                  onClick={() => queryState.fetchNextPage()}
                >
                  {queryState.isFetchingNextPage
                    ? t("loading")
                    : t("load_more")}
                </Button>
              </div>
            )}
          </div>
        )}
      </EncounterAccordionLayout>
    </section>
  );
}
import { Blocks, ShieldAlert } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import {
  EncounterWorkspaceWidget as WorkspaceWidgetConfig,
  normalizeEncounterWidgetType,
} from "@/types/workspace/encounterWorkspace";

import { WorkspaceAllergiesWidget } from "./WorkspaceAllergiesWidget";
import { WorkspaceDiagnosisWidget } from "./WorkspaceDiagnosisWidget";
import { WorkspaceSymptomsWidget } from "./WorkspaceSymptomsWidget";

interface EncounterWorkspaceWidgetProps {
  widget: WorkspaceWidgetConfig;
}

export function EncounterWorkspaceWidget({
  widget,
}: EncounterWorkspaceWidgetProps) {
  const { t } = useTranslation();
  const { canReadClinicalData, isSelectedEncounterLoading, selectedEncounter } =
    useEncounter();
  const type = normalizeEncounterWidgetType(widget.type);

  if (!type) {
    return (
      <Alert>
        <Blocks aria-hidden="true" />
        <AlertTitle className="line-clamp-none break-words">
          {widget.title ?? widget.type}
        </AlertTitle>
        <AlertDescription>
          {t("encounter_workspace_widget_unavailable")}
        </AlertDescription>
      </Alert>
    );
  }

  if (isSelectedEncounterLoading) {
    return (
      <div role="status" aria-label={t("loading")}>
        <Skeleton className="h-40 w-full rounded-xl" />
      </div>
    );
  }

  if (!canReadClinicalData || !selectedEncounter) {
    return (
      <EmptyState
        icon={<ShieldAlert className="size-8 text-gray-400" />}
        title={t("no_permission_to_view_clinical_data")}
        description={t("no_permission_to_view_clinical_data_description")}
      />
    );
  }

  switch (type) {
    case "allergies":
      return <WorkspaceAllergiesWidget title={widget.title} />;
    case "symptoms":
      return <WorkspaceSymptomsWidget title={widget.title} />;
    case "diagnosis":
      return <WorkspaceDiagnosisWidget title={widget.title} />;
  }
}
