import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import {
  EncounterWorkspaceWidget as WorkspaceWidgetConfig,
  normalizeEncounterWidgetType,
} from "@/types/workspace/encounterWorkspace";

import { WorkspaceAllergiesWidget } from "./WorkspaceAllergiesWidget";
import { WorkspaceDiagnosisWidget } from "./WorkspaceDiagnosisWidget";
import { WorkspaceSymptomsWidget } from "./WorkspaceSymptomsWidget";

interface EncounterWorkspaceWidgetProps {
  widget: WorkspaceWidgetConfig;
}

export function EncounterWorkspaceWidget({
  widget,
}: EncounterWorkspaceWidgetProps) {
  const { t } = useTranslation();
  const { canReadClinicalData, isSelectedEncounterLoading, selectedEncounter } =
    useEncounter();
  const type = normalizeEncounterWidgetType(widget.type);

  if (!type) {
    return (
      <Alert>
        <Blocks aria-hidden="true" />
        <AlertTitle className="line-clamp-none break-words">
          {widget.title ?? widget.type}
        </AlertTitle>
        <AlertDescription>
          {t("encounter_workspace_widget_unavailable")}
        </AlertDescription>
      </Alert>
    );
  }

  if (isSelectedEncounterLoading) {
    return (
      <div role="status" aria-label={t("loading")}>
        <Skeleton className="h-40 w-full rounded-xl" />
      </div>
    );
  }

  if (!canReadClinicalData || !selectedEncounter) {
    return (
      <EmptyState
        icon={<ShieldAlert className="size-8 text-gray-400" />}
        title={t("no_permission_to_view_clinical_data")}
        description={t("no_permission_to_view_clinical_data_description")}
      />
    );
  }

  switch (type) {
    case "allergies":
      return <WorkspaceAllergiesWidget title={widget.title} />;
    case "symptoms":
      return <WorkspaceSymptomsWidget title={widget.title} />;
    case "diagnosis":
      return <WorkspaceDiagnosisWidget title={widget.title} />;
  }
}
