import { ShieldAlert } from "lucide-react";
import { useTranslation } from "react-i18next";

import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";

import { AllergyList } from "@/components/Patient/allergy/list";
import { DiagnosisList } from "@/components/Patient/diagnosis/list";
import { SymptomsList } from "@/components/Patient/symptoms/list";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";

interface EncounterClinicalWidgetProps {
  type: "allergies" | "symptoms" | "diagnosis";
  title?: string;
  showEmpty?: boolean;
}

export function EncounterClinicalWidget({
  type,
  title,
  showEmpty = false,
}: EncounterClinicalWidgetProps) {
  const { t } = useTranslation();
  const {
    facilityId,
    patientId,
    selectedEncounterId,
    selectedEncounter,
    isSelectedEncounterLoading,
    canReadClinicalData,
    canWriteClinicalData,
  } = useEncounter();

  if (isSelectedEncounterLoading) {
    return (
      <div role="status" aria-label={t("loading")}>
        <Skeleton className="h-40 w-full rounded-xl" />
      </div>
    );
  }

  if (!canReadClinicalData || !selectedEncounter) {
    return (
      <EmptyState
        icon={<ShieldAlert className="size-8 text-gray-400" />}
        title={t("no_permission_to_view_clinical_data")}
        description={t("no_permission_to_view_clinical_data_description")}
      />
    );
  }

  const props = {
    facilityId,
    patientId,
    encounterId: selectedEncounterId,
    readOnly: !canWriteClinicalData,
    title,
    showEmpty,
    showViewEncounter: false,
    presentation: "panel" as const,
  };

  switch (type) {
    case "allergies":
      return (
        <AllergyList {...props} encounterStatus={selectedEncounter.status} />
      );
    case "symptoms":
      return <SymptomsList {...props} />;
    case "diagnosis":
      return <DiagnosisList {...props} />;
  }
}

