 *  branch that refuses to mount a form uses it, so "we could not open this"
 *  always reads the same and always announces (the ui Alert is
 *  role="alert"). */
function FillErrorPage({
  message,
  exitTarget,
}: {
  message: string;
  exitTarget: string;
}) {
