import { z } from "zod";

import { EncounterStatus } from "@/types/emr/encounter/encounter";

/** Existing encounter pages keep their application-owned layout and behavior. */
export const ENCOUNTER_SYSTEM_PAGE_KEYS = [
  "updates",
  "responses",
  "observations",
  "medicines",
  "service_requests",
  "diagnostic_reports",
  "plots",
  "files",
  "notes",
  "devices",
  "consents",
] as const;

const RESERVED_ENCOUNTER_ROUTE_KEYS = [
  "prescriptions",
  "questionnaire",
  "questionnaire_response",
  "type",
  "report",
];

export type SupportedEncounterWidgetType =
  "allergies" | "symptoms" | "diagnosis";

/** Plugin widget ids use the enabled plugin's slug, followed by a local name. */
export const PLUGIN_ENCOUNTER_WIDGET_TYPE_PATTERN =
  /^[a-z0-9][a-z0-9_-]{0,63}\.[a-z][a-z0-9_]{0,63}$/;

export interface EncounterWorkspaceWidget {
  type: string;
  title?: string;
  config?: Record<string, unknown>;
  visible_when?: { "encounter.status": EncounterStatus[] };
}

export interface EncounterWorkspaceColumn {
  span: number;
  widgets: EncounterWorkspaceWidget[];
}

export interface EncounterWorkspaceCustomPage {
  key: string;
  kind: "custom";
  title: string;
  icon?: string;
  columns: EncounterWorkspaceColumn[];
}

export interface EncounterWorkspaceSystemPage {
  key: string;
  kind: "system";
  hidden?: boolean;
}

export type EncounterWorkspacePage =
  EncounterWorkspaceCustomPage | EncounterWorkspaceSystemPage;

export interface EncounterWorkspaceTemplate {
  schema_version: 1;
  pages: EncounterWorkspacePage[];
}

export type EncounterWorkspaceParseResult =
  | {
      success: true;
      template: EncounterWorkspaceTemplate;
      unsupportedWidgetTypes: string[];
    }
  | {
      success: false;
      error: "invalid_template" | "unsupported_schema";
    };

export function normalizeEncounterSystemPageKey(key: string): string {
  return key === "medications" ? "medicines" : key;
}

/** A single tab segment cannot redirect into a questionnaire or another route. */
export function isEncounterWorkspaceRouteKey(key: string): boolean {
  return (
    /^[a-z][a-z0-9_-]{0,63}$/.test(key) &&
    !RESERVED_ENCOUNTER_ROUTE_KEYS.includes(key)
  );
}

/** Aliases keep templates readable without creating separate clinical widgets. */
export function normalizeEncounterWidgetType(
  type: string,
): SupportedEncounterWidgetType | undefined {
  switch (type) {
    case "allergy":
    case "allergies":
      return "allergies";
    case "symptom":
    case "symptoms":
      return "symptoms";
    case "diagnosis":
    case "diagnoses":
    case "active_problems":
      return "diagnosis";
    default:
      return undefined;
  }
}

export function isEncounterWidgetVisible(
  widget: EncounterWorkspaceWidget,
  encounterStatus: string | undefined,
): boolean {
  const statuses = widget.visible_when?.["encounter.status"];
  return !statuses || statuses.some((status) => status === encounterStatus);
}

const titleSchema = z.string().trim().min(1).max(120);
const widgetSchema = z
  .object({
    type: z
      .string()
      .refine(
        (type) =>
          /^[a-z][a-z0-9_]{0,63}$/.test(type) ||
          PLUGIN_ENCOUNTER_WIDGET_TYPE_PATTERN.test(type),
      ),
    title: titleSchema.optional(),
    config: z.record(z.string(), z.unknown()).optional(),
    visible_when: z
      .object({
        "encounter.status": z
          .array(z.enum(EncounterStatus))
          .min(1)
          .max(Object.values(EncounterStatus).length),
      })
      .strict()
      .optional(),
  })
  .strict();

const customPageSchema = z
  .object({
    key: z.string().regex(/^[a-z][a-z0-9_-]{0,63}$/),
    kind: z.literal("custom"),
    title: titleSchema,
    icon: z.string().min(1).max(64).optional(),
    columns: z
      .array(
        z
          .object({
            span: z.number().int().min(1).max(12),
            widgets: z.array(widgetSchema).max(50),
          })
          .strict(),
      )
      .min(1)
      .max(12)
      .refine(
        (columns) => columns.reduce((sum, col) => sum + col.span, 0) <= 12,
      ),
  })
  .strict();

const systemPageSchema = z
  .object({
    key: z.string().min(1).max(64),
    kind: z.literal("system"),
    hidden: z.boolean().optional(),
  })
  .strict();

const templateSchema = z
  .object({
    schema_version: z.literal(1),
    pages: z
      .array(z.discriminatedUnion("kind", [customPageSchema, systemPageSchema]))
      .min(1)
      .max(50),
  })
  .strict();

/**
 * Invalid templates leave the caller free to show the standard encounter.
 * Unknown widgets stay in the result so they can render an explicit placeholder.
 * System pages may be ordered or hidden, but cannot override their content.
 */
export function parseEncounterWorkspaceTemplate(
  input: unknown,
  additionalSystemPageKeys: readonly string[] = [],
  additionalWidgetTypes: readonly string[] = [],
): EncounterWorkspaceParseResult {
  if (
    input !== null &&
    typeof input === "object" &&
    !Array.isArray(input) &&
    "schema_version" in input &&
    input.schema_version !== 1
  ) {
    return { success: false, error: "unsupported_schema" };
  }

  const parsed = templateSchema.safeParse(input);
  if (!parsed.success) {
    return { success: false, error: "invalid_template" };
  }

  const systemKeys = new Set<string>([
    ...ENCOUNTER_SYSTEM_PAGE_KEYS,
    ...additionalSystemPageKeys.map(normalizeEncounterSystemPageKey),
  ]);
  const reservedCustomKeys = new Set([
    ...systemKeys,
    "medications",
    ...RESERVED_ENCOUNTER_ROUTE_KEYS,
  ]);
  const pageKeys = new Set<string>();
  const unsupportedWidgetTypes = new Set<string>();
  const pluginWidgetTypes = new Set(additionalWidgetTypes);
  const pages: EncounterWorkspacePage[] = [];
  let widgetCount = 0;

  for (const page of parsed.data.pages) {
    const key = normalizeEncounterSystemPageKey(page.key);
    if (pageKeys.has(key)) {
      return { success: false, error: "invalid_template" };
    }
    pageKeys.add(key);

    if (page.kind === "system") {
      if (!systemKeys.has(key)) {
        return { success: false, error: "invalid_template" };
      }
      pages.push({ ...page, key });
      continue;
    }

    if (reservedCustomKeys.has(page.key)) {
      return { success: false, error: "invalid_template" };
    }
    for (const column of page.columns) {
      widgetCount += column.widgets.length;
      if (widgetCount > 200) {
        return { success: false, error: "invalid_template" };
      }
      for (const widget of column.widgets) {
        if (
          !normalizeEncounterWidgetType(widget.type) &&
          !pluginWidgetTypes.has(widget.type)
        ) {
          unsupportedWidgetTypes.add(widget.type);
        }
      }
    }
    pages.push(page);
  }

  return {
    success: true,
    template: { schema_version: 1, pages },
    unsupportedWidgetTypes: [...unsupportedWidgetTypes],
  };
}

