import {
  Activity,
  ClipboardList,
  HeartPulse,
  LayoutDashboard,
  PanelsTopLeft,
  Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};

interface EncounterWorkspaceContentProps {
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const initializedEncounter = useRef<string | undefined>(undefined);
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const parsed = workspace
    ? parseEncounterWorkspaceTemplate(
        workspace.template,
        Object.keys(systemTabs),
      )
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed?.success) {
    for (const page of parsed.template.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon:
            page.icon && Object.hasOwn(customPageIcons, page.icon)
              ? customPageIcons[page.icon]
              : LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      }
    }
  } else {
    Object.assign(tabs, systemTabs);
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection =
    defaults.isLoading || list.isLoading || isSelectedEncounterLoading;

  const navigateToTab = (tab: string, replace = false) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (isLoadingSelection) return;
    if (!defaults.isError && !list.isError) {
      const firstVisit = initializedEncounter.current !== selectedEncounter?.id;
      if (firstVisit && (defaults.isFetching || list.isFetching)) return;
      initializedEncounter.current = selectedEncounter?.id;
      // Encounter entry links use /updates. Apply the saved layout on entry,
      // while allowing an explicit Overview tab selection during the visit.
      if (
        firstVisit &&
        currentTab === "updates" &&
        parsed?.success &&
        firstVisibleTab
      ) {
        navigateToTab(firstVisibleTab, true);
        return;
      }
      if (firstVisibleTab && activeTab !== currentTab) {
        navigateToTab(activeTab, true);
        return;
      }
    }
    if (new URLSearchParams(window.location.search).has("workspace"))
      navigateToTab(currentTab, true);
  });

  return (
    <div className="space-y-3">
      {(defaults.isError || list.isError) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                defaults.refetch();
                list.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.error === "unsupported_schema"
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { navigate } from "raviger";
import { useLayoutEffect, useRef } from "react";

import useAuthUser from "@/hooks/useAuthUser";

import { EncounterTab } from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { EncounterClass } from "@/types/emr/encounter/encounter";
import { parseEncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";
import { WorkspaceRead } from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";
import { callApi } from "@/Utils/request/query";

import { EncounterWorkspacePicker } from "./EncounterWorkspacePicker";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

export function EncounterWorkspaceSwitcher({
  systemTabs,
}: {
  systemTabs: Record<string, EncounterTab>;
}) {
  const user = useAuthUser();
  const queryClient = useQueryClient();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const selectionKey = selectedEncounter
    ? `${selectedEncounter.id}:${selectedEncounter.encounter_class}`
    : undefined;
  const currentEncounter = useRef(selectionKey);
  useLayoutEffect(() => {
    currentEncounter.current = selectionKey;
    return () => {
      currentEncounter.current = undefined;
    };
  }, [selectionKey]);
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const save = useMutation({
    mutationFn: ({
      choice,
      encounterClass,
    }: {
      choice: WorkspaceRead;
      encounterClass: EncounterClass;
      encounterId: string;
    }) =>
      callApi(workspaceApi.setDefaultAttributes, {
        pathParams: { id: choice.id },
        body: { attribute: "encounter_class", value: encounterClass },
        silent: true,
      }),
    onSuccess: async (_, { choice, encounterId, encounterClass }) => {
      await queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", user.id],
      });
      if (currentEncounter.current !== `${encounterId}:${encounterClass}`)
        return;
      const parsed = parseEncounterWorkspaceTemplate(
        choice.template,
        Object.keys(systemTabs),
      );
      const firstPage =
        parsed.success &&
        parsed.template.pages.find(
          (page) =>
            page.kind === "custom" ||
            (!page.hidden && systemTabs[page.key]?.visible !== false),
        );
      const target = new URL(
        firstPage ? firstPage.key : "updates",
        window.location.href,
      );
      target.search = window.location.search;
      target.searchParams.delete("workspace");
      navigate(`${target.pathname}${target.search}`);
    },
  });

  return (
    <EncounterWorkspacePicker
      key={selectedEncounter?.id}
      workspaces={(list.data ?? []).filter(
        (choice) =>
          parseEncounterWorkspaceTemplate(
            choice.template,
            Object.keys(systemTabs),
          ).success,
      )}
      workspaceId={workspace?.id}
      encounterClass={selectedEncounter?.encounter_class}
      isLoading={
        defaults.isLoading || list.isLoading || isSelectedEncounterLoading
      }
      isError={defaults.isError || list.isError}
      onRetry={() => {
        defaults.refetch();
        list.refetch();
      }}
      onSelect={(choice) => {
        if (!selectedEncounter || isSelectedEncounterLoading || save.isPending)
          return;
        save.mutate({
          choice,
          encounterClass: selectedEncounter.encounter_class,
          encounterId: selectedEncounter.id,
        });
      }}
      isSaving={save.isPending}
      saveError={
        save.isError &&
        save.variables?.encounterId === selectedEncounter?.id &&
        save.variables?.encounterClass === selectedEncounter?.encounter_class
      }
    />
  );
}
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Expected a JSON object");
  }
  return parsed as WorkspaceTemplate;
}

export function WorkspaceForm({
  scope,
  existing,
  allowedContexts,
}: WorkspaceFormProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const user = useAuthUser();
  const pluginTabs = useCareAppTabs("encounterTabs");
  const { widgets: pluginWidgets, loadingPlugins } =
    useCareAppEncounterWidgets();
  const [accessState, setAccessState] = useState({
    dirty: false,
    pending: false,
  });
  const [deleteOpen, setDeleteOpen] = useState(false);
  const schema = z
    .object({
      name: z
        .string()
        .trim()
        .min(1, t("workspace_name_required"))
        .max(255, t("workspace_name_too_long")),
      description: z.string(),
      template: z.string().superRefine((value, ctx) => {
        try {
          const template = parseTemplate(value);
          if ("schema_version" in template || "pages" in template) {
            const parsed = parseEncounterWorkspaceTemplate(
              template,
              Object.keys(pluginTabs),
            );
            if (!parsed.success) {
              ctx.addIssue({
                code: "custom",
                message: t("encounter_workspace_template_invalid"),
              });
            }
          }
        } catch {
          ctx.addIssue({
            code: "custom",
            message: t("workspace_template_invalid"),
          });
        }
      }),
      authContext: z.enum(WORKSPACE_AUTH_CONTEXTS),
      departmentId: z.string(),
    })
    .superRefine((values, ctx) => {
      if (
        !existing &&
        values.authContext === "facility_organization" &&
        !values.departmentId
      ) {
        ctx.addIssue({
          code: "custom",
          path: ["departmentId"],
          message: t("workspace_department_required"),
        });
      }
    });
  const form = useForm<WorkspaceFormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      name: existing?.name ?? "",
      description: existing?.description ?? "",
      template: JSON.stringify(existing?.template ?? {}, null, 2),
      authContext: scope.authContext,
      departmentId: "",
    },
  });
  const authContext = useWatch({ control: form.control, name: "authContext" });
  const templateValue = useWatch({ control: form.control, name: "template" });
  let unsupportedWidgets: string[] = [];
  try {
    const parsed = parseEncounterWorkspaceTemplate(
      JSON.parse(templateValue),
      Object.keys(pluginTabs),
      [...pluginWidgets.keys()],
    );
    if (parsed.success) {
      unsupportedWidgets = parsed.unsupportedWidgetTypes.filter(
        (type) => !loadingPlugins.has(type.split(".")[0]),
      );
    }
  } catch {
    // JSON validation is shown on submission or when Format JSON is used.
  }
  const returnPath = scope.basePath;
  const contextLabel = {
    instance: t("workspace_instance_scope"),
    facility: t("workspace_facility_scope"),
    facility_organization: t("workspace_department_scope"),
    user: t("workspace_personal_scope"),
  };
  const contextDescription = {
    instance: t("workspace_instance_description"),
    facility: t("workspace_facility_description"),
    facility_organization: t("workspace_department_description"),
    user: t("workspace_personal_description"),
  };

  const title = t(existing ? "edit_workspace" : "create_workspace");
  const dirty = form.formState.isDirty || accessState.dirty;
  useNavigationPrompt(dirty, t("unsaved_changes_warning"));

 * the loaded session itself is `FillPageBody`.
 */
export function QuestionnaireFillPage({
  subject,
  questionnaireId,
  pickerSubjectType = subject.type,
}: FillPageProps) {
  const { t } = useTranslation();
  const [
    {
      continue_draft: continueDraftParam,
      resume_local_draft: resumeLocalDraftParam,
      prescription,
      toDischarge,
      return_page: requestedReturnPage,
    },
  ] = useQueryParams();
  const patientBound = isPatientBound(subject) ? subject : undefined;
  // Server drafts are patient/encounter records — a resource subject can
  // only have local drafts, so the query param is ignored there.
  const continueDraftId = patientBound ? continueDraftParam : undefined;
  const resumeLocalDraft = resumeLocalDraftParam === "true" && !continueDraftId;

  const {
    questionnaire,
    patient,
    encounter,
    encounterId,
    serverDraft,
    isQuestionnaireLoading,
    isQuestionnaireError,
    isEncounterLoading,
    isEncounterError,
    isPatientError,
    isServerDraftLoading,
    isServerDraftError,
    contextRefreshFailed,
    isRetryingContext,
    retryContext,
  } = useFillPageQueries({ subject, questionnaireId, continueDraftId });
  const { scope, sessionKey, localDraft, serverDraftState } = useFillPageDrafts(
    {
      subject,
      questionnaire,
      continueDraftId,
      serverDraft,
      resumeLocalDraft,
      prescription,
      toDischarge,
    },
  );

  const defaultExitTarget = exitTargetOf(subject);
  const returnPage =
    requestedReturnPage && isEncounterWorkspaceRouteKey(requestedReturnPage)
      ? requestedReturnPage
      : "updates";
  const exitTarget =
    subject.type === "encounter"
      ? `${defaultExitTarget.slice(0, defaultExitTarget.lastIndexOf("/") + 1)}${returnPage}`
      : defaultExitTarget;

  if (!questionnaireId) {
    return (
      <FillShell onClose={() => navigate(exitTarget)}>
        <div className="flex flex-1 flex-col items-center justify-center gap-4 p-6 text-center">
          <h2 className="text-lg font-semibold text-gray-900">
            {t("select_questionnaire_to_fill")}
          </h2>
          {/* Default onSelect navigates to `questionnaire/{id}` relative to
              the current path, which lands on this mount's :questionnaireId
              route for every subject. The trigger is supplied rather than
              defaulted for the same reason the in-session picker's is: a
              `role="combobox"` takes no accessible name from its contents,
              so the only control on this screen would reach screen readers
              unnamed. The role stays (this IS the picker), the name comes
              from aria-label. */}
          <QuestionnaireSearch
            subjectType={pickerSubjectType}
            facilityId={subject.facilityId}
            trigger={
              <Button
                type="button"
                variant="outline"
                role="combobox"
                aria-label={t("select_questionnaire_to_fill")}
                className="w-full border border-primary-600 text-primary-800"
              >
                <Plus className="size-4" />
                {t("add_forms")}
              </Button>
            }
          />
        </div>

