          {selectedEncounter && (
            <PLUGIN_Component
              __name="EncounterActions"
              encounter={selectedEncounter}
              className={cn(
                buttonVariants({ variant: "outline" }),
                "justify-start sm:@sm:justify-center sm:@sm:flex-1 w-full",
              )}
            />
          )}
        </div>
        <div className="flex xl:hidden flex-col space-y-2 mt-3">
          <Account />
          <EncounterTags />
          <Locations />
          <ManageCareTeam />
          <DepartmentsAndTeams />
          <HospitalizationDetails />
          <DischargeDetails />
        </div>
        {selectedEncounter && (
          <div className="sm:@sm:flex-1 flex flex-col gap-2 border-t border-gray-300 border-dashed sm:@sm:border-none pt-3 sm:@sm:pt-0 mt-3">
            <Button
              variant="outline_primary"
              className="justify-start sm:@sm:justify-center"
              onClick={() => markAsCompleted()}
            >
              <CheckIcon />
              {encounterRequiresDischarge(selectedEncounter)
                ? t("mark_for_discharge")
                : t("mark_as_completed")}
            </Button>
          </div>
        )}
      </div>
    </div>
  );
};
import { useQuery } from "@tanstack/react-query";
import { FileText } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { PERMISSION_LIST_TEMPLATE } from "@/common/Permissions";
import { CardListSkeleton } from "@/components/Common/SkeletonLoading";
import { useHasPermission } from "@/context/PermissionContext";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";
import templateApi from "@/types/emr/template/templateApi";
import query from "@/Utils/request/query";

export const SummaryPanelReportsTab = ({
  activeTab,
}: {
  activeTab: string;
}) => {
  const { selectedEncounterId, facilityId } = useEncounter();
  const { facility } = useCurrentFacilitySilently();
  const { t } = useTranslation();
  const canListTemplate = useHasPermission(
    PERMISSION_LIST_TEMPLATE,
    facility?.permissions,
  );

  const isActive = activeTab === "reports";

  const { data: templatesData, isLoading: isLoadingTemplates } = useQuery({
    queryKey: ["templates", facilityId],
    queryFn: query(templateApi.listTemplates, {
      queryParams: {
        facility: facilityId,
        template_type: "discharge_summary",
        status: "active",
      },
    }),
    enabled: isActive && canListTemplate,
  });

  const templates = templatesData?.results ?? [];

  if (isLoadingTemplates) {
    return <CardListSkeleton count={1} />;
  }

  return (
    <div className="flex flex-col gap-3 rounded-xl border border-gray-200 bg-white p-3 @sm:overflow-x-auto">
      <div className="-mx-3 -mt-3 flex border-b border-gray-200 px-3 py-3 @xs:hidden">
        <h6 className="text-sm font-bold uppercase tracking-wide text-gray-600">
          {t("reports")}
        </h6>
      </div>
      <div className="flex flex-col @md:grid @md:grid-cols-2 gap-3">
        {templates.map((template) => (
          <Button
            key={template.id}
            variant="outline"
            className="justify-start w-full"
            asChild
          >
            <Link
              href={`../${selectedEncounterId}/report/template/${template.slug}`}
            >
              <FileText className="size-4 shrink-0" />
              <span className="truncate">{template.name}</span>
            </Link>
          </Button>
        ))}
      </div>
    </div>
  );
};
import query from "@/Utils/request/query";
