interface LeftPanelProps {
  encounterId?: string;
  patientId: string;
  canAccess: boolean;
  responseId?: string;
  questionnaireTitle: string;
  questionnaireSlug?: string;
  handleQuestionnaireChange: (
    questionnaireSlug?: string,
    questionnaireTitle?: string,
  ) => void;
  onResponseClick: (response: QuestionnaireResponse) => void;
}

function LeftPanel({
  encounterId,
  patientId,
  canAccess,
  responseId,
  questionnaireTitle,
  questionnaireSlug,
  handleQuestionnaireChange,
  onResponseClick,
}: LeftPanelProps) {
  const { t } = useTranslation();

  return (
    <>
      <div className="relative w-full pb-2">
        <QuestionnaireSearch
          placeholder={
            questionnaireSlug ? questionnaireTitle : t("select_forms")
          }
          subjectType="encounter"
          onSelect={(q) => {
            handleQuestionnaireChange(q.slug, q.title);
          }}
          trigger={
            <Button
              variant="outline"
              role="combobox"
              className="w-full border border-primary-600 justify-between h-auto min-h-[2.5rem] py-2"
            >
              <div className="flex justify-start items-center gap-2 text-primary-800 flex-1">
                <span className="text-left whitespace-normal break-words">
                  {questionnaireSlug ? questionnaireTitle : t("select_forms")}
                </span>
              </div>
              <div className="flex items-center gap-1 flex-shrink-0 ml-2">
                {questionnaireSlug && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleQuestionnaireChange();
                    }}
                    className="h-5 w-5 p-0 hover:bg-gray-100"
                  >
                    <X className="size-4" />
                  </Button>
                )}
                {!questionnaireSlug && (
                  <ChevronDown className="size-4 flex-shrink-0" />
                )}
              </div>
            </Button>
          }
        />
      </div>
      <div className="flex-1 overflow-y-auto">
        <QuestionnaireResponsesList
          encounterId={encounterId}
          patientId={patientId}
          canAccess={canAccess}
          questionnaireSlug={questionnaireSlug}
          renderItem={(response: QuestionnaireResponse) => (
            <LeftCard
              response={response}
              isActive={responseId === response.id}
              onClick={() => onResponseClick(response)}
              showTitle={!questionnaireSlug}
            />
          )}
        />
      </div>
    </>
  );
}

interface EncounterResponsesTabProps {
  patientId: string;
  encounterId?: string;
  canAccess?: boolean;
}

export const EncounterResponsesTab = ({
  patientId,
  encounterId,
  canAccess = true,
}: EncounterResponsesTabProps) => {
  const { t } = useTranslation();
  const [qParams, setQueryParams] = useQueryParams<{
    questionnaireSlug?: string;
    questionnaireTitle?: string;
    responseId?: string;
  }>();

  const { questionnaireSlug, questionnaireTitle, responseId } = qParams;

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const isMobile = useBreakpoints({ default: true, md: false });

  const handleResponseClick = (response: QuestionnaireResponse) => {
    setQueryParams({ ...qParams, responseId: response.id });
    window.location.hash = `#response-${response.id}`;
    if (isMobile) setIsDrawerOpen(false);
  };

  const handleQuestionnaireChange = (
    questionnaireSlug?: string,
    questionnaireTitle?: string,
  ) => {
    if (questionnaireSlug && questionnaireTitle) {
      setQueryParams({ ...qParams, questionnaireSlug, questionnaireTitle });
    } else {
      const {
        questionnaireSlug: _questionnaireSlug,
        questionnaireTitle: _questionnaireTitle,
        ...rest
      } = qParams;
      setQueryParams(rest);
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-full">
      <div className="hidden md:flex md:w-1/5 flex flex-col gap-3 pt-1 md:h-full md:overflow-y-auto">
        <LeftPanel
          encounterId={encounterId}
          patientId={patientId}
          canAccess={canAccess}
          responseId={responseId}
          questionnaireSlug={questionnaireSlug}
          questionnaireTitle={questionnaireTitle || ""}
          handleQuestionnaireChange={handleQuestionnaireChange}
          onResponseClick={handleResponseClick}
        />
      </div>
      {isMobile && (
        <div className="p-3 border-b md:hidden flex justify-center">
          <Drawer open={isDrawerOpen} onOpenChange={setIsDrawerOpen}>
            <DrawerTrigger asChild>
              <Button variant="outline" size="sm" className="w-full">
                <Menu className="size-4 mr-2" />
                {t("view_responses")}
              </Button>
            </DrawerTrigger>
            <DrawerContent
              className="h-[85vh]"
              onCloseAutoFocus={(e) => e.preventDefault()}
            >
              <ScrollArea className="h-full">
                <div className="p-3 h-full">
                  <LeftPanel
                    encounterId={encounterId}
                    patientId={patientId}
                    canAccess={canAccess}
                    responseId={responseId}
                    questionnaireSlug={questionnaireSlug}
                    questionnaireTitle={questionnaireTitle || ""}
                    handleQuestionnaireChange={handleQuestionnaireChange}
                    onResponseClick={handleResponseClick}
                  />
                </div>
              </ScrollArea>
            </DrawerContent>
          </Drawer>
        </div>
      )}
      <div className="flex-1 h-full overflow-y-auto">
        <ScrollArea key={questionnaireSlug} className="h-full">
          <div className="space-y-4 p-3 overflow-anchor-auto">
            <QuestionnaireResponsesList
              encounterId={encounterId}
              patientId={patientId}
              canAccess={canAccess}
              questionnaireSlug={questionnaireSlug}
              renderItem={(response: QuestionnaireResponse) => {
                return (
                  <div
                    key={response.id}
                    id={`response-${response.id}`}
                    className="scroll-mt-24 [overflow-anchor:auto]"
                  >
                    <Card
                      className={cn(
                        "shadow-sm border rounded-lg",
                        responseId === response.id && "ring-2 ring-primary-500",
                      )}
                    >
                      <ResponseCard
                        item={response}
                        patientId={patientId}
                        showTitle={!questionnaireSlug}
                        onTitleClick={() => {
                          setQueryParams({
                            ...qParams,
                            questionnaireSlug: response.questionnaire?.slug,
                            questionnaireTitle: response.questionnaire?.title,
                          });
                        }}
                      />
                    </Card>
                  </div>
                );
              }}
            />
          </div>
        </ScrollArea>
      </div>
    </div>
  );
};
import {
  ChevronDown,
  ClipboardList,
  HeartPulse,
  Microscope,
  Stethoscope,
} from "lucide-react";
import { Link } from "raviger";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button, buttonVariants } from "@/components/ui/button";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { cn } from "@/lib/utils";

import { AllergyIcon, MedicineIcon } from "@/CAREUI/icons/CustomIcons";

import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";

import { FormDialog } from "./FormsDialog";

export const QuickActions = (props: React.ComponentProps<"div">) => {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState(false);

  return (
    <div {...props} className={cn("@container", props.className)}>
      <Collapsible
        open={expanded}
        onOpenChange={setExpanded}
        className="flex w-full items-start gap-1.5 rounded-xl border border-gray-300 bg-gray-100 p-1.5"
      >
        <CollapsibleTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            className="h-11 w-8 shrink-0 self-center rounded-lg p-0 text-gray-600 hover:bg-gray-200 hover:text-gray-950"
            aria-label={expanded ? t("show_less") : t("more_actions")}
            title={expanded ? t("show_less") : t("more_actions")}
            onKeyDown={(event) => {
              if (
                event.key === "Enter" &&
                !event.shiftKey &&
                !event.ctrlKey &&
                !event.metaKey &&
                !event.altKey
              ) {
                // Let Enter activate this button instead of the global shortcut.
                event.stopPropagation();
              }
            }}
          >
            <ChevronDown
              aria-hidden="true"
              className={cn("transition-transform", expanded && "rotate-180")}
            />
          </Button>
        </CollapsibleTrigger>
        <div className="grid min-w-0 flex-1 grid-cols-2 gap-1.5 @min-[38rem]:grid-cols-[repeat(4,auto)]">
          <QuickAction
            compact
            icon={<AllergyIcon className="text-amber-700" />}
            title={t("allergy")}
            aria-label={t("add_allergy", { count: 1 })}
            actionId="add-allergy"
            href={`questionnaire/allergy_intolerance`}
          />
          <QuickAction
            compact
            icon={<Microscope className="text-pink-600" strokeWidth={1.5} />}
            title={t("service_request")}
            actionId="add-service-request"
            href={`questionnaire/service_request`}
          />
          <QuickAction
            compact
            icon={<MedicineIcon className="text-teal-700" />}
            title={t("medication")}
            aria-label={t("add_medication")}
            href={`questionnaire/medication_request`}
            actionId="add-medication-request"
          />
          <FormDialog
            subjectType="encounter"
            trigger={
              <QuickAction
                compact
                icon={
                  <ClipboardList className="text-teal-700" strokeWidth={1.5} />
                }
                title={t("forms")}
                actionId="add-questionnaire"
              />
            }
          />
          <CollapsibleContent className="col-span-full grid grid-cols-2 gap-1.5 data-[state=closed]:hidden">
            <QuickAction
              compact
              icon={
                <HeartPulse className="text-orange-700" strokeWidth={1.5} />
              }
              title={t("symptoms")}
              aria-label={t("add_symptom")}
              href="questionnaire/symptom"
              actionId="add-symptoms"
            />
            <QuickAction
              compact
              icon={
                <Stethoscope className="text-purple-700" strokeWidth={1.5} />
              }
              title={t("diagnosis")}
              aria-label={t("add_diagnosis")}
              href="questionnaire/diagnosis"
              actionId="add-diagnosis"
            />
          </CollapsibleContent>
        </div>
      </Collapsible>
    </div>
  );
};

export function QuickAction({
  icon,
  title,
  actionId,
  href,
  basePath,
  onClick,
  hidden,
  compact = false,
  ...props
}: {
  icon: React.ReactNode;
  title: string;
  actionId?: string;
  href?: string;
  basePath?: string;
  onClick?: () => void;
  hidden?: boolean;
  compact?: boolean;
} & React.ComponentProps<"button">) {
  const className = cn(
    compact
      ? cn(
          buttonVariants({ variant: "outline" }),
          "h-auto min-h-11 min-w-0 w-full justify-start gap-1.5 rounded-lg border-gray-200 bg-white px-2 py-2 text-left font-semibold text-gray-950 whitespace-normal shadow-xs transition-[background-color,border-color,box-shadow] hover:border-gray-300 hover:bg-white hover:shadow-sm active:bg-gray-50 active:shadow-none focus-visible:ring-2 focus-visible:ring-primary-600 focus-visible:ring-offset-2 [&_svg]:size-6",
        )
      : "flex-1 flex flex-row md:flex-col gap-1.25 p-1 pb-2 rounded-lg shadow bg-white",
    hidden && "hidden",
  );

  const content = compact ? (
    <>
      <span
        aria-hidden="true"
        className="flex size-6 shrink-0 items-center justify-center [&_svg]:size-6"
      >
        {icon}
      </span>
      <span className="min-w-0 flex-1 leading-5">{title}</span>
      {actionId && (
        <ShortcutBadge
          actionId={actionId}
          variant="secondary"
          className="h-5 min-w-5 shrink-0 items-center rounded-md border-gray-200 border-b-2 px-1 font-normal text-gray-600 shadow-xs"
        />
      )}
    </>
  ) : (
    <QuickActionContent icon={icon} title={title} actionId={actionId} />
  );

  if (href) {
    return (
      <Link
        basePath={basePath}
        href={href}
