              presentation === "panel"
                ? "gap-2 space-y-0 px-3 py-2"
                : "py-2 px-3",
              presentation === "panel" &&
                isExpanded &&
                "border-b border-gray-200",
              isEnteredInError && "hover:bg-gray-50",
