          >
            {showTitle && (
              <CardTitle
                className={cn(
                  presentation === "panel"
                    ? "text-sm font-bold tracking-wide text-gray-600 uppercase"
                    : "text-base font-medium",
                  onTitleClick &&
                    !isEnteredInError &&
                    "cursor-pointer hover:bg-gray-100 rounded px-1.5 py-0.5",
