import { Blocks, ShieldAlert } from "lucide-react";
import { Suspense } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";

import { PluginErrorBoundary } from "@/components/Common/PluginErrorBoundary";
import { AllergyList } from "@/components/Patient/allergy/list";
import { DiagnosisList } from "@/components/Patient/diagnosis/list";
import { SymptomsList } from "@/components/Patient/symptoms/list";

import { useCareAppEncounterWidgets } from "@/hooks/useCareAppEncounterWidgets";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { ENCOUNTER_WIDGET_TYPES } from "@/types/workspace/encounterWorkspace";

interface EncounterWidgetProps {
  type: string;
  title?: string;
  config?: Record<string, unknown>;
  showEmpty?: boolean;
}

export function EncounterWidget({
  type,
  title,
  config = {},
  showEmpty = false,
}: EncounterWidgetProps) {
  const { t } = useTranslation();
  const { widgets, loadingPlugins } = useCareAppEncounterWidgets();
  const {
    facilityId,
    patientId,
    selectedEncounterId,
    selectedEncounter,
    isSelectedEncounterLoading,
    canReadClinicalData,
    canWriteClinicalData,
  } = useEncounter();

  const loading = (
    <div role="status" aria-label={t("loading")}>
      <Skeleton className="h-40 w-full rounded-xl" />
    </div>
  );
  const isCoreWidget = ENCOUNTER_WIDGET_TYPES.includes(type);
  const pluginWidget = widgets.get(type);
  const isPluginLoading =
    type.includes(".") && loadingPlugins.has(type.split(".")[0]);

  if (!isCoreWidget && !pluginWidget && !isPluginLoading) {
    return (
      <Alert>
        <Blocks aria-hidden="true" />
        <AlertTitle className="line-clamp-none break-words">
          {title ?? type}
        </AlertTitle>
        <AlertDescription>
          {t("encounter_workspace_widget_unavailable")}
        </AlertDescription>
      </Alert>
    );
  }

  if (isSelectedEncounterLoading) return loading;

  if (!canReadClinicalData || !selectedEncounter) {
    return (
      <EmptyState
        icon={<ShieldAlert className="size-8 text-gray-400" />}
        title={t("no_permission_to_view_clinical_data")}
        description={t("no_permission_to_view_clinical_data_description")}
      />
    );
  }

  if (selectedEncounter.patient.id !== patientId) {
    return (
      <Alert variant="destructive">
        <AlertDescription>
          {t("fill_patient_encounter_mismatch")}
        </AlertDescription>
      </Alert>
    );
  }

  const props = {
    facilityId,
    patientId,
    encounterId: selectedEncounterId,
    readOnly: !canWriteClinicalData,
    title,
    showEmpty,
    showViewEncounter: false,
    presentation: "panel" as const,
  };

  switch (type) {
    case "allergies":
      return (
        <AllergyList {...props} encounterStatus={selectedEncounter.status} />
      );
    case "symptoms":
      return <SymptomsList {...props} />;
    case "diagnosis":
      return <DiagnosisList {...props} />;
  }

  if (!pluginWidget) return loading;

  const Component = pluginWidget.component;
  return (
    <div className="min-w-0 @container/encounter-widget">
      <PluginErrorBoundary
        key={`${type}:${patientId}:${selectedEncounterId}:${JSON.stringify(config)}`}
        pluginName={pluginWidget.pluginSlug}
        resetKey={Component}
        fallback={
          <Alert variant="destructive">
            <AlertTitle>{title ?? type}</AlertTitle>
            <AlertDescription>
              {t("encounter_workspace_widget_error")}
            </AlertDescription>
          </Alert>
        }
      >
        <Suspense fallback={loading}>
          <Component
            patientId={patientId}
            encounterId={selectedEncounterId}
            encounter={selectedEncounter}
            facilityId={facilityId}
            title={title}
            config={config}
            readOnly={!canWriteClinicalData}
          />
        </Suspense>
      </PluginErrorBoundary>
    </div>
  );
}
import careConfig from "@careConfig";
import { useQuery } from "@tanstack/react-query";
import { ShieldAlert } from "lucide-react";
import { useTranslation } from "react-i18next";

import { PLUGIN_Component } from "@/PluginEngine";

import { EmptyState } from "@/components/ui/empty-state";

import QuestionnaireResponsesList from "@/components/Facility/ConsultationDetails/QuestionnaireResponsesList";
import { VitalsList } from "@/components/Patient/vitals/list";
import { ObservationPlotConfig } from "@/types/emr/observation/observation";

import { ClinicalHistoryOverview } from "@/pages/Encounters/tabs/overview/clinical-history-overview";
import { FavoriteFormsQuickActions } from "@/pages/Encounters/tabs/overview/FavoriteFormsQuickActions";
import { FormSubmissionDrafts } from "@/pages/Encounters/tabs/overview/FormSubmissionDrafts";
import { QuickActions } from "@/pages/Encounters/tabs/overview/quick-actions";
import { SummaryPanel } from "@/pages/Encounters/tabs/overview/summary-panel";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { EncounterWidget } from "@/pages/Encounters/widgets/EncounterWidget";
import EncounterOverviewDevices from "@/pages/Facility/settings/devices/components/EncounterOverviewDevices";
import { inactiveEncounterStatus } from "@/types/emr/encounter/encounter";

export const EncounterOverviewTab = () => {
  const { t } = useTranslation();
  const {
    selectedEncounter: encounter,
    patientId,
    selectedEncounterId: encounterId,
    canReadSelectedEncounter: canAccess,
    canWriteSelectedEncounter: canWrite,
    canReadClinicalData,
  } = useEncounter();

  const { data: plotsConfig } = useQuery<ObservationPlotConfig>({
    queryKey: ["plots-config"],
    queryFn: () => fetch(careConfig.plotsConfigUrl).then((res) => res.json()),
    enabled: canReadClinicalData,
  });

  const vitalGroups =
    plotsConfig?.find((plot) => plot.id === "primary-parameters")?.groups || [];

  return (
    <div className="flex items-start gap-3 @max-md:w-full">
      <div className="min-w-0 flex-1">
        <div className="mb-2 flex min-h-10 flex-wrap items-center justify-between gap-2">
          <h1 className="text-lg font-semibold tracking-tight text-gray-950">
            {t("ENCOUNTER_TAB__updates")}
          </h1>
          {canReadClinicalData && <ClinicalHistoryOverview />}
        </div>
        {canReadClinicalData ? (
          <div className="flex flex-col gap-3">
            {canWrite && <QuickActions />}
            {canWrite && <FavoriteFormsQuickActions />}
            {encounter && (
              <PLUGIN_Component
                __name="EncounterOverviewTop"
                encounter={encounter}
                patientId={patientId}
                encounterId={encounterId}
              />
            )}

            <div className="xl:hidden">
              <SummaryPanel />
            </div>

            {
              <div className="flex flex-col gap-3 overflow-x-auto">
                {/* Show preview of devices associated with the encounter */}
                {encounter && (
                  <EncounterOverviewDevices encounter={encounter} />
                )}
                {encounter &&
                  !inactiveEncounterStatus.includes(encounter.status) && (
                    <FormSubmissionDrafts
                      facilityId={encounter.facility.id}
                      patientId={patientId}
                      encounterId={encounterId}
                    />
                  )}
                {/* Clinical informations */}
                <EncounterWidget type="allergies" />
                <EncounterWidget type="symptoms" />
                <EncounterWidget type="diagnosis" />
                <VitalsList
                  presentation="panel"
                  patientId={patientId}
                  encounterId={encounterId}
                  codeGroups={vitalGroups}
                />
                <QuestionnaireResponsesList
                  presentation="panel"
                  encounterId={encounterId}
                  patientId={patientId}
                  canAccess={canAccess}
                />
              </div>
            }
          </div>
        ) : (
          <div className="flex-1 xl:pr-3 flex items-center justify-center">
            <EmptyState
              icon={<ShieldAlert className="text-gray-400 size-8" />}
              title={t("no_permission_to_view_clinical_data")}
              description={t("no_permission_to_view_clinical_data_description")}
              className="h-full w-full bg-transparent"
            />
          </div>
        )}
      </div>

      <aside className="hidden w-72 shrink-0 xl:block">
        <SummaryPanel />
      </aside>
    </div>
  );
};

