    useInfiniteQuery<PaginatedResponse<ObservationListRead>, HTTPError>({
      queryKey: ["infinite-observations", patientId, encounterId],
      queryFn: async ({ pageParam = 0, signal }) => {
        const response = await query(observationApi.list, {
