import { useMutation, useQueryClient } from "@tanstack/react-query";
import { navigate } from "raviger";
import { useLayoutEffect, useRef } from "react";

import useAuthUser from "@/hooks/useAuthUser";

import { EncounterTab } from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { EncounterClass } from "@/types/emr/encounter/encounter";
import { createEncounterWorkspaceSchema } from "@/types/workspace/encounterWorkspace";
import { WorkspaceRead } from "@/types/workspace/workspace";
import workspaceApi from "@/types/workspace/workspaceApi";
import { callApi } from "@/Utils/request/query";

import { EncounterWorkspacePicker } from "./EncounterWorkspacePicker";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

export function EncounterWorkspaceSwitcher({
  systemTabs,
}: {
  systemTabs: Record<string, EncounterTab>;
}) {
  const user = useAuthUser();
  const workspaceSchema = createEncounterWorkspaceSchema(
    Object.keys(systemTabs),
  );
  const queryClient = useQueryClient();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const selectionKey = selectedEncounter
    ? `${selectedEncounter.id}:${selectedEncounter.encounter_class}`
    : undefined;
  const currentEncounter = useRef(selectionKey);
  useLayoutEffect(() => {
    currentEncounter.current = selectionKey;
    return () => {
      currentEncounter.current = undefined;
    };
  }, [selectionKey]);
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const save = useMutation({
    mutationFn: ({
      choice,
      encounterClass,
    }: {
      choice: WorkspaceRead;
      encounterClass: EncounterClass;
      encounterId: string;
    }) =>
      callApi(workspaceApi.setDefaultAttributes, {
        pathParams: { id: choice.id },
        body: { attribute: "encounter_class", value: encounterClass },
        silent: true,
      }),
    onSuccess: async (_, { choice, encounterId, encounterClass }) => {
      await queryClient.invalidateQueries({
        queryKey: ["workspace-user-defaults", user.id],
      });
      if (currentEncounter.current !== `${encounterId}:${encounterClass}`)
        return;
      const parsed = workspaceSchema.safeParse(choice.template);
      const firstPage =
        parsed.success &&
        parsed.data.pages.find(
          (page) =>
            page.kind === "custom" ||
            (!page.hidden && systemTabs[page.key]?.visible !== false),
        );
      const target = new URL(
        firstPage ? firstPage.key : "updates",
        window.location.href,
      );
      target.search = window.location.search;
      target.searchParams.delete("workspace");
      navigate(`${target.pathname}${target.search}`);
    },
  });

  return (
    <EncounterWorkspacePicker
      key={selectedEncounter?.id}
      workspaces={(list.data ?? []).filter(
        (choice) => workspaceSchema.safeParse(choice.template).success,
      )}
      workspaceId={workspace?.id}
      encounterClass={selectedEncounter?.encounter_class}
      isLoading={
        defaults.isLoading || list.isLoading || isSelectedEncounterLoading
      }
      isError={defaults.isError || list.isError}
      onRetry={() => {
        defaults.refetch();
        list.refetch();
      }}
      onSelect={(choice) => {
        if (!selectedEncounter || isSelectedEncounterLoading || save.isPending)
          return;
        save.mutate({
          choice,
          encounterClass: selectedEncounter.encounter_class,
          encounterId: selectedEncounter.id,
        });
      }}
      isSaving={save.isPending}
      saveError={
        save.isError &&
        save.variables?.encounterId === selectedEncounter?.id &&
        save.variables?.encounterClass === selectedEncounter?.encounter_class
      }
    />
  );
}
import { Check, Loader2 } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

import { EncounterClass } from "@/types/emr/encounter/encounter";
import { WorkspaceRead } from "@/types/workspace/workspace";

interface EncounterWorkspacePickerProps {
  workspaces: WorkspaceRead[];
  workspaceId?: string;
  isLoading: boolean;
  isError: boolean;
  onRetry: () => void;
  onSelect: (workspace: WorkspaceRead) => void;
  isSaving: boolean;
  saveError: boolean;
  encounterClass?: EncounterClass;
}

export function EncounterWorkspacePicker({
  workspaces,
  workspaceId,
  isLoading,
  isError,
  onRetry,
  onSelect,
  isSaving,
  saveError,
  encounterClass,
}: EncounterWorkspacePickerProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const wasSaving = useRef(false);
  const currentWorkspace = workspaces.find(({ id }) => id === workspaceId);
  const currentName = workspaceId
    ? (currentWorkspace?.name ?? t("encounter_workspace_unavailable"))
    : t("encounter_workspace_standard");
  const busy = isLoading || isError || isSaving;
  useEffect(() => {
    if (wasSaving.current && !isSaving && !saveError) setOpen(false);
    wasSaving.current = isSaving;
  }, [isSaving, saveError]);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="outline"
              size="icon"
              aria-label={t("encounter_workspace")}
              className="size-9 shrink-0 rounded-lg border-gray-200 bg-white text-sm font-bold text-gray-700 shadow-none"
            >
              {isSaving ? (
                <Loader2 className="size-4 animate-spin" aria-hidden="true" />
              ) : (
                <span aria-hidden="true">W</span>
              )}
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent side="bottom">
          {isLoading
            ? t("encounter_workspace_loading")
            : t("encounter_workspace_current", { name: currentName })}
        </TooltipContent>
      </Tooltip>
      <PopoverContent
        align="end"
        className="w-80 max-w-[calc(100vw-2rem)] p-0"
        aria-label={t("encounter_workspace")}
      >
        <div className="border-b px-3 py-2.5">
          <h2 className="text-sm font-semibold">{t("encounter_workspace")}</h2>
          <p className="mt-1 truncate text-xs text-gray-700">
            {t("encounter_workspace_current", { name: currentName })}
          </p>
          <p className="mt-0.5 text-xs text-gray-500">
            {t("encounter_workspace_picker_hint", {
              encounterClass: encounterClass
                ? t(`encounter_class__${encounterClass}`)
                : t("encounter"),
            })}
          </p>
        </div>
        {isError && (
          <div className="p-2">
            <Alert variant="destructive">
              <AlertDescription className="space-y-2">
                <p>{t("encounter_workspace_list_error")}</p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={onRetry}
                >
                  {t("try_again")}
                </Button>
              </AlertDescription>
            </Alert>
          </div>
        )}
        {saveError && (
          <div className="p-2">
            <Alert variant="destructive">
              <AlertDescription>
                {t("encounter_workspace_select_error")}
              </AlertDescription>
            </Alert>
          </div>
        )}
        <Command>
          <CommandInput
            placeholder={t("search_workspaces")}
            aria-label={t("search_workspaces")}
            disabled={isLoading || isSaving}
          />
          <CommandList aria-label={t("workspaces")}>
            {isLoading ? (
              <div
                className="space-y-2 p-3"
                role="status"
                aria-label={t("encounter_workspace_loading")}
              >
                <Skeleton className="h-12 w-full" />
                <Skeleton className="h-12 w-full" />
              </div>
            ) : (
              <>
                <CommandEmpty>{t("no_workspaces_found")}</CommandEmpty>
                <CommandGroup>
                  {workspaces.map((workspace) => (
                    <CommandItem
                      key={workspace.id}
                      value={workspace.id}
                      keywords={[workspace.name, workspace.description]}
                      disabled={busy}
                      onSelect={() => {
                        if (busy) return;
                        if (workspace.id === workspaceId) setOpen(false);
                        else onSelect(workspace);
                      }}
                      className="items-start gap-2 px-3 py-2.5"
                    >
                      <div className="min-w-0 flex-1">
                        <p className="break-words text-sm font-medium">
                          {workspace.name}
                        </p>
                        {workspace.description && (
                          <p className="mt-1 line-clamp-2 break-words text-xs text-gray-600">
                            {workspace.description}
                          </p>
                        )}
                      </div>
                      {workspace.id === workspaceId && (
                        <Check
                          className="mt-0.5 size-4 text-primary-600"
                          aria-label={t("selected")}
                        />
                      )}
                    </CommandItem>
                  ))}
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
import { useQuery } from "@tanstack/react-query";

import useAuthUser from "@/hooks/useAuthUser";

import { EncounterClass } from "@/types/emr/encounter/encounter";
import workspaceApi from "@/types/workspace/workspaceApi";
import query from "@/Utils/request/query";

/** The backend owns access; saved choices apply across facilities by class. */
export function useEncounterWorkspaces(encounterClass?: EncounterClass) {
  const user = useAuthUser();
  const defaults = useQuery({
    queryKey: ["workspace-user-defaults", user.id, "encounter"],
    queryFn: query(workspaceApi.getUserDefaultAttributes, { silent: true }),
    retry: false,
  });
  const list = useQuery({
    queryKey: ["workspaces", user.id, "encounter"],
    queryFn: async ({ signal }) => {
      const response = await query.paginated(workspaceApi.list, {
        silent: true,
      })({ signal });
      return response.results;
    },
    retry: false,
  });
  const accessibleWorkspaces = new Map(
    (list.data ?? []).map((workspace) => [workspace.id, workspace]),
  );
  // Keep the defaults API's order and skip deleted or revoked workspaces.
  const firstMatch = defaults.data?.results.find(
    ({ attribute, value, workspace }) =>
      attribute === "encounter_class" &&
      value === encounterClass &&
      accessibleWorkspaces.has(workspace.id),
  );

  return {
    defaults,
    list,
    workspace:
      !defaults.isError && !list.isError && firstMatch
        ? accessibleWorkspaces.get(firstMatch.workspace.id)
        : undefined,
  };
}
