import {
  Activity,
  ClipboardList,
  HeartPulse,
  LayoutDashboard,
  PanelsTopLeft,
  Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { createEncounterWorkspaceSchema } from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};

interface EncounterWorkspaceContentProps {
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const initializedEncounter = useRef<string | undefined>(undefined);
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const parsed = workspace
    ? createEncounterWorkspaceSchema(Object.keys(systemTabs)).safeParse(
        workspace.template,
      )
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed?.success) {
    for (const page of parsed.data.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon:
            page.icon && Object.hasOwn(customPageIcons, page.icon)
              ? customPageIcons[page.icon]
              : LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      }
    }
  } else {
    Object.assign(tabs, systemTabs);
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection =
    defaults.isLoading || list.isLoading || isSelectedEncounterLoading;

  const navigateToTab = (tab: string, replace = false) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (isLoadingSelection) return;
    if (!defaults.isError && !list.isError) {
      const firstVisit = initializedEncounter.current !== selectedEncounter?.id;
      if (firstVisit && (defaults.isFetching || list.isFetching)) return;
      initializedEncounter.current = selectedEncounter?.id;
      // Encounter entry links use /updates. Apply the saved layout on entry,
      // while allowing an explicit Overview tab selection during the visit.
      if (
        firstVisit &&
        currentTab === "updates" &&
        parsed?.success &&
        firstVisibleTab
      ) {
        navigateToTab(firstVisibleTab, true);
        return;
      }
      if (firstVisibleTab && activeTab !== currentTab) {
        navigateToTab(activeTab, true);
        return;
      }
    }
    if (new URLSearchParams(window.location.search).has("workspace"))
      navigateToTab(currentTab, true);
  });

  return (
    <div className="space-y-3">
      {(defaults.isError || list.isError) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                defaults.refetch();
                list.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.error.issues.some(
                (issue) => issue.path[0] === "schema_version",
              )
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
import { useTranslation } from "react-i18next";

import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { EncounterWidget } from "@/pages/Encounters/widgets/EncounterWidget";
import { EncounterWorkspaceCustomPage } from "@/types/workspace/encounterWorkspace";

interface EncounterWorkspacePageProps {
  page: EncounterWorkspaceCustomPage;
}

export function EncounterWorkspacePage({ page }: EncounterWorkspacePageProps) {
  const { t } = useTranslation();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();

  if (isSelectedEncounterLoading) {
    return <Skeleton className="h-64 w-full" />;
  }
  if (!selectedEncounter) {
    return <p role="alert">{t("encounter_not_found")}</p>;
  }

  const columns = page.columns
    .map((column) => ({
      ...column,
      widgets: column.widgets.filter((widget) => {
        const statuses = widget.visible_when?.["encounter.status"];
        return !statuses || statuses.includes(selectedEncounter.status);
      }),
    }))
    .filter((column) => column.widgets.length > 0);

  if (!columns.length) {
    return (
      <p className="rounded-lg border border-dashed p-6 text-sm text-gray-600">
        {t("encounter_workspace_empty_page")}
      </p>
    );
  }

  return (
    <div className="@container">
      <div
        className={cn(
          "grid min-w-0 grid-cols-1 items-start gap-3 @4xl:grid-cols-[var(--workspace-columns)]",
          columns.length > 1 && "@xl:grid-cols-2",
        )}
        style={
          {
            "--workspace-columns": columns
              .map(({ span }) => `minmax(0, ${span}fr)`)
              .join(" "),
          } as React.CSSProperties
        }
      >
        {columns.map((column, columnIndex) => (
          <div key={columnIndex} className="min-w-0 space-y-3">
            {column.widgets.map((widget, widgetIndex) => (
              <EncounterWidget
                key={`${widgetIndex}:${widget.type}`}
                type={widget.type}
                title={widget.title}
                config={widget.config}
                showEmpty
              />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}
import { Blocks, ShieldAlert } from "lucide-react";
import { useFullPath } from "raviger";
import { Suspense } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";

import { PluginErrorBoundary } from "@/components/Common/PluginErrorBoundary";
import { AllergyList } from "@/components/Patient/allergy/list";
import { DiagnosisList } from "@/components/Patient/diagnosis/list";
import { SymptomsList } from "@/components/Patient/symptoms/list";

import { useCareAppEncounterWidgets } from "@/hooks/useCareAppEncounterWidgets";
import { FavoriteFormsQuickActions } from "@/pages/Encounters/tabs/overview/FavoriteFormsQuickActions";
import { FormSubmissionDrafts } from "@/pages/Encounters/tabs/overview/FormSubmissionDrafts";
import { QuickActions } from "@/pages/Encounters/tabs/overview/quick-actions";
import { SummaryPanelActionsTab } from "@/pages/Encounters/tabs/overview/summary-panel-actions.tab";
import { AuditLogs } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/auditlogs";
import { DepartmentsAndTeams } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/department-and-team";
import { DischargeDetails } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/discharge-summary";
import { EncounterTags } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/encounter-tags";
import { HospitalizationDetails } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/hospitalisation";
import { Locations } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/locations";
import { ManageCareTeam } from "@/pages/Encounters/tabs/overview/summary-panel-details-tab/manage-care-team";
import { SummaryPanelReportsTab } from "@/pages/Encounters/tabs/overview/summary-panel-reports-tab";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import {
  ENCOUNTER_WIDGET_TYPES,
  encounterPageKeySchema,
} from "@/types/workspace/encounterWorkspace";

import { EncounterResponsesWidget } from "./EncounterResponsesWidget";
import { EncounterServiceRequestsWidget } from "./EncounterServiceRequestsWidget";
import { EncounterVitalsWidget } from "./EncounterVitalsWidget";

interface EncounterWidgetProps {
  type: string;
  title?: string;
  config?: Record<string, unknown>;
  showEmpty?: boolean;
}

export function EncounterWidget({
  type,
  title,
  config = {},
  showEmpty = false,
}: EncounterWidgetProps) {
  const { t } = useTranslation();
  const fullPath = useFullPath();
  const returnPage =
    encounterPageKeySchema.safeParse(fullPath.split("/").pop()).data ??
    "updates";
  const { widgets, loadingPlugins } = useCareAppEncounterWidgets();
  const {
    facilityId,
    patientId,
    selectedEncounterId,
    selectedEncounter,
    isSelectedEncounterLoading,
    canReadSelectedEncounter,
    canReadClinicalData,
    canWriteClinicalData,
  } = useEncounter();

  const loading = (
    <div role="status" aria-label={t("loading")}>
      <Skeleton className="h-40 w-full rounded-xl" />
    </div>
  );
  const isCoreWidget = ENCOUNTER_WIDGET_TYPES.includes(type);
  const pluginWidget = widgets.get(type);
  const isPluginLoading =
    type.includes(".") && loadingPlugins.has(type.split(".")[0]);

  if (!isCoreWidget && !pluginWidget && !isPluginLoading) {
    return (
      <Alert>
        <Blocks aria-hidden="true" />
        <AlertTitle className="line-clamp-none break-words">
          {title ?? type}
        </AlertTitle>
        <AlertDescription>
          {t("encounter_workspace_widget_unavailable")}
        </AlertDescription>
      </Alert>
    );
  }

  if (isSelectedEncounterLoading) return loading;

  const noClinicalAccess = (
    <EmptyState
      icon={<ShieldAlert className="size-8 text-gray-400" />}
      title={t("no_permission_to_view_clinical_data")}
      description={t("no_permission_to_view_clinical_data_description")}
    />
  );

  if (!selectedEncounter) return noClinicalAccess;

  if (selectedEncounter.patient.id !== patientId) {
    return (
      <Alert variant="destructive">
        <AlertDescription>
          {t("fill_patient_encounter_mismatch")}
        </AlertDescription>
      </Alert>
    );
  }

  // These cards contain encounter metadata and retain their own edit controls.
  if (canReadSelectedEncounter || canReadClinicalData) {
    switch (type) {
      case "encounter_tags":
        return <EncounterTags title={title} />;
      case "locations":
        return <Locations title={title} />;
      case "care_team":
        return <ManageCareTeam key={selectedEncounterId} title={title} />;
      case "departments":
        return <DepartmentsAndTeams title={title} />;
      case "hospitalization":
        return <HospitalizationDetails title={title} />;
      case "discharge":
        return <DischargeDetails title={title} />;
      case "audit_logs":
        return <AuditLogs title={title} />;
    }
  }

  if (!canReadClinicalData) return noClinicalAccess;

  const actionProps = { title, showEmpty, returnPage };
  switch (type) {
    case "quick_actions":
      return facilityId && canWriteClinicalData ? (
        <QuickActions {...actionProps} />
      ) : null;
    case "favorite_forms":
      return facilityId && canWriteClinicalData ? (
        <FavoriteFormsQuickActions {...actionProps} />
      ) : null;
    case "draft_forms":
      return facilityId && canWriteClinicalData ? (
        <FormSubmissionDrafts
          {...actionProps}
          facilityId={facilityId}
          patientId={patientId}
          encounterId={selectedEncounterId}
        />
      ) : null;
    case "encounter_actions":
      return facilityId && canWriteClinicalData ? (
        <SummaryPanelActionsTab title={title} embedded />
      ) : null;
    case "reports":
      return (
        <SummaryPanelReportsTab title={title} activeTab="reports" embedded />
      );
    case "vitals":
      return <EncounterVitalsWidget title={title} showEmpty={showEmpty} />;
    case "service_requests":
      return (
        <EncounterServiceRequestsWidget
          title={title}
          showEmpty={showEmpty}
          config={config}
        />
      );
    case "questionnaire_responses":
      return (
        <EncounterResponsesWidget
          title={title}
          showEmpty={showEmpty}
          config={config}
        />
      );

