  if (!selectedEncounter) return noClinicalAccess;

  if (selectedEncounter.patient.id !== patientId) {
    return (
      <Alert variant="destructive">
        <AlertDescription>
          {t("fill_patient_encounter_mismatch")}
        </AlertDescription>
      </Alert>
    );
