      return <EncounterVitalsWidget title={title} showEmpty={showEmpty} />;
    case "service_requests":
      return (
        <EncounterServiceRequestsWidget
          title={title}
          showEmpty={showEmpty}
          config={config}
        />
      );
    case "questionnaire_responses":
      return (
        <EncounterResponsesWidget
          title={title}
          showEmpty={showEmpty}
          config={config}
        />
      );

