import { EncounterStatus } from "@/types/emr/encounter/encounter";

const SYSTEM_PAGE_KEYS = [
  "updates",
  "responses",
  "observations",
  "medicines",
  "service_requests",
  "diagnostic_reports",
  "plots",
  "files",
  "notes",
  "devices",
  "consents",
];

const RESERVED_ROUTE_KEYS = [
  "prescriptions",
  "questionnaire",
  "questionnaire_response",
  "type",
  "report",
];

export const ENCOUNTER_WIDGET_TYPES: readonly string[] = [
  "allergies",
  "symptoms",
  "diagnosis",
  "vitals",
  "questionnaire_responses",
  "service_requests",
  "quick_actions",
  "favorite_forms",
  "draft_forms",
  "encounter_tags",
  "locations",
  "care_team",
  "departments",
  "hospitalization",
  "discharge",
  "audit_logs",
  "encounter_actions",
  "reports",
];

export const PLUGIN_ENCOUNTER_WIDGET_TYPE_PATTERN =
  /^[a-z0-9][a-z0-9_-]{0,63}\.[a-z][a-z0-9_]{0,63}$/;

// Shared by custom page keys and questionnaire return links.
export const encounterPageKeySchema = z
  .string()
  .regex(/^[a-z][a-z0-9_-]{0,63}$/)
  .refine((key) => !RESERVED_ROUTE_KEYS.includes(key));

const titleSchema = z.string().trim().min(1).max(120);
const widgetSchema = z.strictObject({
  type: z
    .string()
    .refine(
      (type) =>
        /^[a-z][a-z0-9_]{0,63}$/.test(type) ||
        PLUGIN_ENCOUNTER_WIDGET_TYPE_PATTERN.test(type),
    ),
  title: titleSchema.optional(),
  config: z.record(z.string(), z.unknown()).optional(),
  visible_when: z
    .strictObject({
      "encounter.status": z
        .array(z.enum(EncounterStatus))
        .min(1)
        .max(Object.values(EncounterStatus).length),
    })
    .optional(),
});

const customPageSchema = z.strictObject({
  key: encounterPageKeySchema,
  kind: z.literal("custom"),
  title: titleSchema,
  icon: z.string().min(1).max(64).optional(),
  columns: z
    .array(
      z.strictObject({
        span: z.number().int().min(1).max(12),
        widgets: z.array(widgetSchema).max(50),
      }),
    )
    .min(1)
    .max(12)
    .refine((columns) => columns.reduce((sum, col) => sum + col.span, 0) <= 12),
});

const systemPageSchema = z.strictObject({
  key: z.string().min(1).max(64),
  kind: z.literal("system"),
  hidden: z.boolean().optional(),
});

const workspaceSchema = z
  .strictObject({
    schema_version: z.literal(1),
    pages: z
      .array(z.discriminatedUnion("kind", [customPageSchema, systemPageSchema]))
      .min(1)
      .max(50),
  })
  .refine(
    ({ pages }) => new Set(pages.map((page) => page.key)).size === pages.length,
    { message: "Page keys must be unique" },
  )
  .refine(
    ({ pages }) =>
      pages.reduce(
        (count, page) =>
          count +
          (page.kind === "custom"
            ? page.columns.reduce(
                (sum, column) => sum + column.widgets.length,
                0,
              )
            : 0),
        0,
      ) <= 200,
    { message: "A workspace can contain at most 200 widgets" },
  );

export type EncounterWorkspaceWidget = z.infer<typeof widgetSchema>;
export type EncounterWorkspaceCustomPage = z.infer<typeof customPageSchema>;
export type EncounterWorkspaceTemplate = z.infer<typeof workspaceSchema>;

/** Widget availability is a rendering concern; unknown widget types remain valid. */
export function createEncounterWorkspaceSchema(
  additionalSystemPageKeys: readonly string[] = [],
) {
  const systemKeys = new Set([
    ...SYSTEM_PAGE_KEYS,
    ...additionalSystemPageKeys,
  ]);
  return workspaceSchema.refine(
    ({ pages }) =>
      pages.every((page) =>
        page.kind === "system"
          ? systemKeys.has(page.key)
          : !systemKeys.has(page.key),
      ),
    { message: "System pages must exist and custom pages cannot replace them" },
  );
}
import {
  Activity,
  ClipboardList,
  HeartPulse,
  LayoutDashboard,
  PanelsTopLeft,
  Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { createEncounterWorkspaceSchema } from "@/types/workspace/encounterWorkspace";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};

interface EncounterWorkspaceContentProps {
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const initializedEncounter = useRef<string | undefined>(undefined);
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const parsed = workspace
    ? createEncounterWorkspaceSchema(Object.keys(systemTabs)).safeParse(
        workspace.template,
      )
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed?.success) {
    for (const page of parsed.data.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon:
            page.icon && Object.hasOwn(customPageIcons, page.icon)
              ? customPageIcons[page.icon]
              : LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      }
    }
  } else {
    Object.assign(tabs, systemTabs);
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection =
    defaults.isLoading || list.isLoading || isSelectedEncounterLoading;

  const navigateToTab = (tab: string, replace = false) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (isLoadingSelection) return;
    if (!defaults.isError && !list.isError) {
      const firstVisit = initializedEncounter.current !== selectedEncounter?.id;
      if (firstVisit && (defaults.isFetching || list.isFetching)) return;
      initializedEncounter.current = selectedEncounter?.id;
      // Encounter entry links use /updates. Apply the saved layout on entry,
      // while allowing an explicit Overview tab selection during the visit.
      if (
        firstVisit &&
        currentTab === "updates" &&
        parsed?.success &&
        firstVisibleTab
      ) {
        navigateToTab(firstVisibleTab, true);
        return;
      }
      if (firstVisibleTab && activeTab !== currentTab) {
        navigateToTab(activeTab, true);
        return;
      }
    }
    if (new URLSearchParams(window.location.search).has("workspace"))
      navigateToTab(currentTab, true);
  });

  return (
    <div className="space-y-3">
      {(defaults.isError || list.isError) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                defaults.refetch();
                list.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && !parsed.success && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.error.issues.some(
                (issue) => issue.path[0] === "schema_version",
              )
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
