import {
  EncounterWorkspaceWidget,
  SYSTEM_PAGE_KEYS,
  encounterPageKeySchema,
  titleSchema,
  widgetSchema,
} from "@/types/workspace/encounterWorkspace";

export type RenderWidget =
  EncounterWorkspaceWidget | { error: true; title?: string };

export interface RenderColumn {
  span: number;
  widgets: RenderWidget[];
  invalid: boolean;
}

export type RenderPage =
  | {
      kind: "custom";
      key: string;
      title: string;
      icon?: string;
      columns: RenderColumn[];
      invalid: boolean;
    }
  | { kind: "system"; key: string; hidden?: boolean }
  | { kind: "invalid"; key: string; title: string };

interface RenderWorkspace {
  pages: RenderPage[];
  unsupportedVersion: boolean;
  invalid: boolean;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function hasExtraFields(value: Record<string, unknown>, fields: string[]) {
  return Object.keys(value).some((key) => !fields.includes(key));
}

/** Keep malformed configuration local while preserving safe configured routes. */
export function parseEncounterWorkspace(
  template: unknown,
  systemPageKeys: readonly string[],
): RenderWorkspace {
  const result: RenderWorkspace = {
    pages: [],
    unsupportedVersion: false,
    invalid: false,
  };
  if (!isRecord(template)) return { ...result, invalid: true };

  result.unsupportedVersion =
    Object.hasOwn(template, "schema_version") && template.schema_version !== 1;
  result.invalid =
    !Object.hasOwn(template, "schema_version") ||
    hasExtraFields(template, ["schema_version", "pages"]);
  if (!Array.isArray(template.pages)) return { ...result, invalid: true };
  if (template.pages.length > 50) result.invalid = true;

  const availableSystemKeys = new Set(systemPageKeys);
  const reservedSystemKeys = new Set([...SYSTEM_PAGE_KEYS, ...systemPageKeys]);
  const pageKeys = new Set<string>();
  let widgetCount = 0;

  const parseColumn = (value: unknown): RenderColumn => {
    const column: RenderColumn = { span: 1, widgets: [], invalid: false };
    if (!isRecord(value)) return { ...column, invalid: true };

    column.invalid = hasExtraFields(value, ["span", "widgets"]);
    if (
      typeof value.span === "number" &&
      Number.isInteger(value.span) &&
      value.span >= 1 &&
      value.span <= 12
    ) {
      column.span = value.span;
    } else {
      column.invalid = true;
    }
    if (!Array.isArray(value.widgets)) return { ...column, invalid: true };

    const remaining = Math.min(50, 200 - widgetCount);
    if (value.widgets.length > remaining) {
      column.invalid = true;
      result.invalid = true;
    }
    for (const rawWidget of value.widgets.slice(0, remaining)) {
      widgetCount += 1;
      const parsed = widgetSchema.safeParse(rawWidget);
      column.widgets.push(
        parsed.success
          ? parsed.data
          : {
              error: true,
              title: isRecord(rawWidget)
                ? titleSchema.safeParse(rawWidget.title).data
                : undefined,
            },
      );
    }
    return column;
  };

  for (const value of template.pages.slice(0, 50)) {
    if (!isRecord(value)) {
      result.invalid = true;
      continue;
    }
    const parsedKey = encounterPageKeySchema.safeParse(value.key);
    if (
      !parsedKey.success ||
      pageKeys.has(parsedKey.data) ||
      (value.kind === "custom" && reservedSystemKeys.has(parsedKey.data))
    ) {
      result.invalid = true;
      continue;
    }
    const key = parsedKey.data;
    pageKeys.add(key);
    const title = titleSchema.safeParse(value.title).data;

    if (value.kind === "system" && availableSystemKeys.has(key)) {
      if (value.hidden !== undefined && typeof value.hidden !== "boolean") {
        result.pages.push({ kind: "invalid", key, title: title ?? key });
      } else {
        if (hasExtraFields(value, ["key", "kind", "hidden"]))
          result.invalid = true;
        result.pages.push({ kind: "system", key, hidden: value.hidden });
      }
      continue;
    }
    if (value.kind !== "custom") {
      result.pages.push({ kind: "invalid", key, title: title ?? key });
      continue;
    }

    const page: Extract<RenderPage, { kind: "custom" }> = {
      kind: "custom",
      key,
      title: title ?? key,
      columns: [],
      invalid:
        title === undefined ||
        hasExtraFields(value, ["key", "kind", "title", "icon", "columns"]),
    };
    if (value.icon !== undefined) {
      if (
        typeof value.icon === "string" &&
        value.icon.length > 0 &&
        value.icon.length <= 64
      )
        page.icon = value.icon;
      else page.invalid = true;
    }
    if (Array.isArray(value.columns)) {
      if (!value.columns.length || value.columns.length > 12)
        page.invalid = true;
      if (value.columns.length > 12) result.invalid = true;
      page.columns = value.columns.slice(0, 12).map(parseColumn);
      // Bounded positive fractions remain usable even if their sum exceeds 12.
      if (page.columns.reduce((sum, column) => sum + column.span, 0) > 12)
        page.invalid = true;
    } else {
      page.invalid = true;
    }
    result.pages.push(page);
  }
  return result;
}
import {
  Activity,
  ClipboardList,
  HeartPulse,
  LayoutDashboard,
  PanelsTopLeft,
  Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import ErrorBoundary from "@/components/Common/ErrorBoundary";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { parseEncounterWorkspace } from "./parseEncounterWorkspace";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};

interface EncounterWorkspaceContentProps {
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const initializedEncounter = useRef<string | undefined>(undefined);
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const parsed = workspace
    ? parseEncounterWorkspace(workspace.template, Object.keys(systemTabs))
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed) {
    for (const page of parsed.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else if (page.kind === "custom") {
        tabs[page.key] = {
          label: page.title,
          icon:
            page.icon && Object.hasOwn(customPageIcons, page.icon)
              ? customPageIcons[page.icon]
              : LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon: LayoutDashboard,
          component: (
            <Alert>
              <AlertDescription>
                {t("encounter_workspace_page_unavailable")}
              </AlertDescription>
            </Alert>
          ),
        };
      }
    }
  } else {
    Object.assign(tabs, systemTabs);
  }

  if (workspace) {
    const resetKey = `${workspace.id}:${selectedEncounter?.id}:${JSON.stringify(workspace.template)}`;
    for (const [key, tab] of Object.entries(tabs)) {
      tab.component = (
        <ErrorBoundary
          key={`${key}:${resetKey}`}
          fallback={
            <Alert variant="destructive">
              <AlertDescription>
                {t("encounter_workspace_page_error")}
              </AlertDescription>
            </Alert>
          }
        >
          {tab.component}
        </ErrorBoundary>
      );
    }
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection =
    defaults.isLoading || list.isLoading || isSelectedEncounterLoading;

  const navigateToTab = (tab: string, replace = false) => {
    const target = new URL(tab, window.location.href);
    target.search = window.location.search;
    target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (isLoadingSelection) return;
    if (!defaults.isError && !list.isError) {
      const firstVisit = initializedEncounter.current !== selectedEncounter?.id;
      if (firstVisit && (defaults.isFetching || list.isFetching)) return;
      initializedEncounter.current = selectedEncounter?.id;
      // Encounter entry links use /updates. Apply the saved layout on entry,
      // while allowing an explicit Overview tab selection during the visit.
      if (firstVisit && currentTab === "updates" && parsed && firstVisibleTab) {
        navigateToTab(firstVisibleTab, true);
        return;
      }
      if (firstVisibleTab && activeTab !== currentTab) {
        navigateToTab(activeTab, true);
        return;
      }
    }
    if (new URLSearchParams(window.location.search).has("workspace"))
      navigateToTab(currentTab, true);
  });

  return (
    <div className="space-y-3">
      {(defaults.isError || list.isError) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                defaults.refetch();
                list.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && (parsed.invalid || parsed.unsupportedVersion) && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.unsupportedVersion
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";

import ErrorBoundary from "@/components/Common/ErrorBoundary";

import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { EncounterWidget } from "@/pages/Encounters/widgets/EncounterWidget";

import { RenderPage } from "./parseEncounterWorkspace";

interface EncounterWorkspacePageProps {
  page: Extract<RenderPage, { kind: "custom" }>;
}

export function EncounterWorkspacePage({ page }: EncounterWorkspacePageProps) {
  const { t } = useTranslation();
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();

  if (isSelectedEncounterLoading) {
    return <Skeleton className="h-64 w-full" />;
  }
  if (!selectedEncounter) {
    return <p role="alert">{t("encounter_not_found")}</p>;
  }

  const columns = page.columns
    .map((column) => ({
      ...column,
      widgets: column.widgets.filter((widget) => {
        if ("error" in widget) return true;
        const statuses = widget.visible_when?.["encounter.status"];
        return !statuses || statuses.includes(selectedEncounter.status);
      }),
    }))
    .filter((column) => column.invalid || column.widgets.length > 0);

  return (
    <div className="@container space-y-3">
      {page.invalid && (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_page_invalid")}
          </AlertDescription>
        </Alert>
      )}
      {columns.length ? (
        <div
          className={cn(
            "grid min-w-0 grid-cols-1 items-start gap-3 @4xl:grid-cols-[var(--workspace-columns)]",
            columns.length > 1 && "@xl:grid-cols-2",
          )}
          style={
            {
              "--workspace-columns": columns
                .map(({ span }) => `minmax(0, ${span}fr)`)
                .join(" "),
            } as React.CSSProperties
          }
        >
          {columns.map((column, columnIndex) => (
            <div key={columnIndex} className="min-w-0 space-y-3">
              {column.invalid && (
                <Alert>
                  <AlertDescription>
                    {t("encounter_workspace_column_invalid")}
                  </AlertDescription>
                </Alert>
              )}
              {column.widgets.map((widget, widgetIndex) =>
                "error" in widget ? (
                  <Alert key={widgetIndex}>
                    {widget.title && <AlertTitle>{widget.title}</AlertTitle>}
                    <AlertDescription>
                      {t("encounter_widget_config_invalid")}
                    </AlertDescription>
                  </Alert>
                ) : (
                  <ErrorBoundary
                    key={`${selectedEncounter.id}:${widgetIndex}:${JSON.stringify(widget)}`}
                    fallback={
                      <Alert variant="destructive">
                        <AlertTitle>{widget.title ?? widget.type}</AlertTitle>
                        <AlertDescription>
                          {t("encounter_workspace_widget_error")}
                        </AlertDescription>
                      </Alert>
                    }
                  >
                    <EncounterWidget
                      type={widget.type}
                      title={widget.title}
                      config={widget.config}
                      showEmpty
                    />
                  </ErrorBoundary>
                ),
              )}
            </div>
          ))}
        </div>
      ) : (
        !page.invalid && (
          <p className="rounded-lg border border-dashed p-6 text-sm text-gray-600">
            {t("encounter_workspace_empty_page")}
          </p>
        )
      )}
    </div>
  );
}

