  };

  for (const value of template.pages.slice(0, 50)) {
    if (!isRecord(value)) {
      result.invalid = true;
      continue;
    }
    const parsedKey = encounterPageKeySchema.safeParse(value.key);
    if (
      !parsedKey.success ||
      pageKeys.has(parsedKey.data) ||
      (value.kind === "custom" && reservedSystemKeys.has(parsedKey.data))
    ) {
