import { useQuery } from "@tanstack/react-query";
import { FileText } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { PERMISSION_LIST_TEMPLATE } from "@/common/Permissions";
import { CardListSkeleton } from "@/components/Common/SkeletonLoading";
import { ClinicalListError } from "@/components/Patient/Common/ClinicalListError";
import { useHasPermission } from "@/context/PermissionContext";
import { cn } from "@/lib/utils";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";
import templateApi from "@/types/emr/template/templateApi";
import query from "@/Utils/request/query";

interface SummaryPanelReportsTabProps {
  activeTab: string;
  title?: string;
  embedded?: boolean;
}

export const SummaryPanelReportsTab = ({
  activeTab,
  title,
  embedded = false,
}: SummaryPanelReportsTabProps) => {
  const { selectedEncounter, facilityId: routeFacilityId } = useEncounter();
  const { facility } = useCurrentFacilitySilently();
  const facilityId = selectedEncounter?.facility.id;
  const { t } = useTranslation();
  const canListTemplate = useHasPermission(
    PERMISSION_LIST_TEMPLATE,
    facility?.permissions,
  );

  const isActive = activeTab === "reports";
  const hasFacilityContext =
    !!facilityId &&
    routeFacilityId === facilityId &&
    facility?.id === facilityId;

  const {
    data: templatesData,
    isLoading: isLoadingTemplates,
    isError,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: ["templates", facilityId, "discharge_summary"],
    queryFn: query(templateApi.listTemplates, {
      queryParams: {
        facility: facilityId,
        template_type: "discharge_summary",
        status: "active",
      },
    }),
    enabled: isActive && hasFacilityContext && canListTemplate,
  });

  const templates = templatesData?.results ?? [];

  if (!hasFacilityContext || !canListTemplate || !selectedEncounter)
    return null;

  if (isLoadingTemplates) {
    return <CardListSkeleton count={1} />;
  }

  return (
    <section
      aria-label={title ?? t("reports")}
      className="flex min-w-0 flex-col gap-3 rounded-xl border border-gray-200 bg-white p-3"
    >
      <div
        className={cn(
          "-mx-3 -mt-3 flex border-b border-gray-200 px-3 py-3",
          !embedded && "@xs:hidden",
        )}
      >
        <h3 className="min-w-0 text-sm font-bold uppercase tracking-wide text-gray-600 [overflow-wrap:anywhere]">
          {title ?? t("reports")}
        </h3>
      </div>
      {isError && (
        <ClinicalListError isFetching={isFetching} onRetry={refetch} />
      )}
      <div
        className={cn(
          "flex min-w-0 flex-col gap-3",
          !embedded && "@md:grid @md:grid-cols-2",
        )}
      >
        {!isError && templates.length === 0 && (
          <p className="text-sm text-gray-500">{t("no_templates_found")}</p>
        )}
        {templates.map((template) => (
          <Button
            key={template.id}
            variant="outline"
            className="h-auto min-h-9 justify-start w-full whitespace-normal"
            asChild
          >
            <Link
              href={`/facility/${facilityId}/patient/${selectedEncounter.patient.id}/encounter/${selectedEncounter.id}/report/template/${template.slug}`}
            >
              <FileText className="size-4 shrink-0" />
              <span className="min-w-0 text-left [overflow-wrap:anywhere]">
                {template.name}
              </span>
            </Link>
          </Button>
        ))}
      </div>
    </section>
  );
};
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { SquarePen } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import { CardListSkeleton } from "@/components/Common/SkeletonLoading";
import { AccountSheetButton } from "@/components/Patient/AccountSheetButton";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { ACCOUNT_BILLING_STATUS_COLORS } from "@/types/billing/account/Account";
import accountApi from "@/types/billing/account/accountApi";

import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { SummaryPanelEmptyState as EmptyState } from "./empty-state";

export const Account = () => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const {
    selectedEncounter: encounter,
    patientId,
    facilityId,
  } = useEncounter();

  const { data: response, isLoading } = useQuery({
    queryKey: ["defaultAccount", facilityId, patientId, encounter?.id],
    queryFn: query(accountApi.defaultAccount, {
      pathParams: { facilityId: facilityId || "" },
      body: {
        patient: patientId,
        facility: facilityId || "",
        encounter: encounter?.id || "",
      },
      silent: true,
    }),
    enabled: !!facilityId && !!encounter?.id,
  });

  const account = response;
  const accountId = account?.id;

  const { mutate: setPrimaryEncounter, isPending } = useMutation({
    mutationFn: mutate(accountApi.updateAccount, {
      pathParams: {
        facilityId: facilityId || "",
        accountId: accountId || "",
      },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["defaultAccount"] });
      toast.success(t("encounter_set_as_primary_success"));
    },
  });

  if (!encounter) return <CardListSkeleton count={3} />;

  if (isLoading) {
    return <CardListSkeleton count={1} />;
  }

  if (facilityId !== encounter.facility.id) return null;

  const handleSetPrimaryEncounter = () => {
    if (!account) return;

    setPrimaryEncounter({
      id: account.id,
      name: account.name,
      description: account.description,
      status: account.status,
      billing_status: account.billing_status,
      service_period: account.service_period,
      patient: patientId || "",
      primary_encounter: encounter.id,
      extensions: account.extensions,
    });
  };

  const isCurrentEncounterPrimary =
    account?.primary_encounter?.id === encounter.id;

  return (
    <div className="w-full rounded-xl border border-gray-200 bg-white">
      <div className="flex min-h-11 items-center justify-between gap-2 border-b border-gray-200 px-3 py-1">
        <span className="text-sm font-bold uppercase tracking-wide text-gray-600">
          {t("account")}:
        </span>
        <AccountSheetButton
          encounter={encounter}
          trigger={
            <Button variant="ghost" size="sm">
              <SquarePen className="cursor-pointer" strokeWidth={1.5} />
            </Button>
          }
        />
      </div>

      <div className="p-3">
        {!account ? (
          <EmptyState message={t("no_account_found")} />
        ) : (
          <Link href={`/facility/${facilityId}/billing/account/${account.id}`}>
            <div
              className={cn(
                "flex flex-row bg-gray-100 rounded-md p-2 border border-gray-200 justify-between",
                !isCurrentEncounterPrimary ? "bg-red-100" : "bg-green-100",
              )}
            >
              <span className="text-sm text-black font-semibold">
                {account.name}
              </span>

              <Badge
                variant={ACCOUNT_BILLING_STATUS_COLORS[account.billing_status]}
              >
                {t(account.billing_status)}
              </Badge>
            </div>
          </Link>
        )}
      </div>
      {account && !isCurrentEncounterPrimary && (
        <Button
          variant="outline"
          size="sm"
          onClick={handleSetPrimaryEncounter}
          disabled={isPending}
          className="mx-3 mb-3 w-[calc(100%-1.5rem)] text-xs text-muted-foreground font-medium shadow-none"
        >
          {t("assign_this_encounter")}
        </Button>
      )}
    </div>
  );
};

