import type { RendererSubject } from "@/components/QuestionnaireV2/form/types";

/**
 * What a fill session is being filled for. Each subject carries exactly the
 * ids its route can supply, which keeps rendering, submit routing, draft
 * scoping and exit navigation typed from the same union.
 */
export type FillSubject =
  | {
      type: "encounter";
      facilityId: string;
      patientId: string;
      encounterId: string;
    }
  | { type: "patient"; patientId: string; facilityId?: string }
  | { type: "location"; facilityId: string; locationId: string }
  | { type: "device"; facilityId: string; deviceId: string }
  | { type: "facility"; facilityId: string };

/** The subjects that carry a patient — the clinical legs' precondition. */
export type PatientBoundSubject = Extract<
  FillSubject,
  { type: "encounter" | "patient" }
>;

export function isPatientBound(
  subject: FillSubject,
): subject is PatientBoundSubject {
  return subject.type === "encounter" || subject.type === "patient";
}

/** The id the backend records the response against (`resource_id`). */
export function subjectResourceId(subject: FillSubject): string {
  switch (subject.type) {
    case "encounter":
      return subject.encounterId;
    case "patient":
      return subject.patientId;
    case "location":
      return subject.locationId;
    case "device":
      return subject.deviceId;
    case "facility":
      return subject.facilityId;
  }
}

/** Draft scope key. The type prefix keeps two subjects that happen to
 *  share an id (nothing guarantees they cannot) in separate drafts. */
export function subjectKeyOf(subject: FillSubject): string {
  return `${subject.type}:${subjectResourceId(subject)}`;
}

/** The renderer's flat view of the subject — what structured inputs read
 *  to decide whether they have the context they require. */
export function rendererSubjectOf(subject: FillSubject): RendererSubject {
  const resourceId = subjectResourceId(subject);
  if (subject.type === "encounter") {
    return {
      patientId: subject.patientId,
      encounterId: subject.encounterId,
      facilityId: subject.facilityId,
      resourceId,
    };
  }
  if (subject.type === "patient") {
    return {
      patientId: subject.patientId,
      facilityId: subject.facilityId,
      resourceId,
    };
  }
  return { facilityId: subject.facilityId, resourceId };
}

/** Where Close/Cancel and a completed submission land. */
export function exitTargetOf(subject: FillSubject): string {
  switch (subject.type) {
    case "encounter":
      return `/facility/${subject.facilityId}/patient/${subject.patientId}/encounter/${subject.encounterId}/updates`;
    case "patient":
      return subject.facilityId
        ? `/facility/${subject.facilityId}/patient/${subject.patientId}/updates`
        : `/patient/${subject.patientId}/updates`;
    case "location":
      return `/facility/${subject.facilityId}/locations/${subject.locationId}/responses`;
    case "device":
      return `/facility/${subject.facilityId}/settings/devices/${subject.deviceId}/responses`;
    case "facility":
      return `/facility/${subject.facilityId}/settings/responses`;
  }
}
import { useEffect, useMemo, useState } from "react";

import useAuthUser from "@/hooks/useAuthUser";
import type { FormSubmissionRead } from "@/types/questionnaire/formSubmission";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

import { sweepExpiredFillDrafts } from "./draft/fillDraftCache";
import { fillDraftScopeKey } from "./draft/fillDraftCore";
import { loadFillDraft, type FillDraftScope } from "./draft/fillDraftStore";
import { parseServerDraft, type ServerDraftState } from "./draft/serverDraft";
import { subjectKeyOf, type FillSubject } from "./subject";

interface FillPageDraftsOptions {
  subject: FillSubject;
  questionnaire?: QuestionnaireRead;
  continueDraftId?: string;
  serverDraft?: FormSubmissionRead;
  resumeLocalDraft: boolean;
  prescription?: string;
  toDischarge?: string;
}

/** Resolve draft recovery for a session without rereading autosaved edits on refetch. */
export function useFillPageDrafts({
  subject,
  questionnaire,
  continueDraftId,
  serverDraft,
  resumeLocalDraft,
  prescription,
  toDischarge,
}: FillPageDraftsOptions) {
  const user = useAuthUser();
  useEffect(() => {
    sweepExpiredFillDrafts();
  }, []);

  // Server draft (continue_draft) supersedes any local draft.
  const serverDraftState = useMemo<ServerDraftState | undefined>(
    () =>
      continueDraftId && serverDraft && questionnaire
        ? parseServerDraft(serverDraft, questionnaire)
        : undefined,
    [continueDraftId, serverDraft, questionnaire],
  );

  // These query parameters change the record or workflow a widget edits,
  // even when the encounter and questionnaire remain the same.
  const contextParams = new URLSearchParams();
  if (prescription) contextParams.set("prescription", prescription);
  if (toDischarge === "true") contextParams.set("toDischarge", "true");
  const contextKey = contextParams.toString() || undefined;
  const scope: FillDraftScope | undefined = questionnaire
    ? {
        userId: user.id,
        subjectKey: subjectKeyOf(subject),
        entryQuestionnaireId: questionnaire.id,
        contextKey,
      }
    : undefined;

  // Load once per user, subject, questionnaire and editing context.
  // Autosave writes do not change these dependencies.
  const scopeKey = scope ? fillDraftScopeKey(scope) : undefined;
  const sessionKey = `${scopeKey}--${continueDraftId ?? ""}--${resumeLocalDraft}`;
  const readLocalDraft = () =>
    scopeKey && scope && questionnaire && !continueDraftId
      ? loadFillDraft(scope, questionnaire.questions)
      : undefined;
  const [snapshot, setSnapshot] = useState(() => ({
    sessionKey,
    draft: readLocalDraft(),
  }));
  let localDraft = snapshot.draft;
  if (snapshot.sessionKey !== sessionKey) {
    localDraft = readLocalDraft();
    setSnapshot({ sessionKey, draft: localDraft });
  }

  return { scope, sessionKey, localDraft, serverDraftState };
}
