import type { TFunction } from "i18next";

import type { EncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";

export type WorkspacePage = EncounterWorkspaceTemplate["pages"][number];
export interface WidgetSelection {
  column: number;
  widget: number;
}

export function systemPageLabel(key: string, t: TFunction) {
  if (key === "medicines") return t("medications");
  if (key === "responses") return t("ENCOUNTER_TAB__qnr_responses");
  return t("ENCOUNTER_TAB__" + key, { defaultValue: key });
}

export function moveItem<T>(items: T[], from: number, to: number): T[] {
  const next = [...items];
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
}

export function pageWidgetCount(page: WorkspacePage) {
  return page.kind === "custom"
    ? page.columns.reduce((count, column) => count + column.widgets.length, 0)
    : 0;
}

import { Blocks, Plus, Search } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { useCareAppEncounterWidgets } from "@/hooks/useCareAppEncounterWidgets";

import { CORE_WIDGET_CATALOG } from "./workspaceEditorCatalog";

interface WorkspaceWidgetLibraryProps { onClose: () => void; onAdd: (type: string) => void }

export function WorkspaceWidgetLibrary({ onClose, onAdd }: WorkspaceWidgetLibraryProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const { widgets: plugins, loadingPlugins } = useCareAppEncounterWidgets();
  const options = [
    ...CORE_WIDGET_CATALOG.map((item) => ({ ...item, label: t(item.labelKey), description: t(item.descriptionKey) })),
    ...[...plugins.keys()].map((type) => ({ type, label: type, description: t("workspace_builder_plugin_widget_hint"), icon: Blocks, group: "plugins" })),
  ].filter((item) => (item.label + " " + item.description + " " + item.type).toLowerCase().includes(search.toLowerCase()));

  return <Dialog open onOpenChange={(open) => { if (!open) onClose(); }}><DialogContent className="max-h-[85dvh] gap-0 overflow-hidden p-0 sm:max-w-2xl">
    <DialogHeader className="px-6 pt-6 pb-4"><DialogTitle>{t("workspace_builder_add_widget")}</DialogTitle><DialogDescription>{t("workspace_builder_library_hint")}</DialogDescription></DialogHeader>
    <div className="relative mx-6 mb-4"><Search className="absolute left-3 top-3 size-4 text-gray-400" /><Input autoFocus value={search} onChange={(event) => setSearch(event.target.value)} aria-label={t("workspace_builder_search_widgets")} placeholder={t("workspace_builder_search_widgets")} className="pl-9" /></div>
    <div className="max-h-[55dvh] space-y-6 overflow-y-auto border-t bg-gray-50/70 p-6">
      {["clinical", "workflow", "details", "plugins"].map((group) => {
        const items = options.filter((item) => item.group === group);
        return items.length > 0 && <section key={group} className="space-y-2"><h3 className="text-xs font-semibold uppercase tracking-wider text-gray-500">{t("workspace_builder_group_" + group)}</h3><div className="grid gap-2 sm:grid-cols-2">
          {items.map(({ type, label, description, icon: Icon }) => <Button key={type} type="button" variant="outline" aria-label={label} onClick={() => onAdd(type)} className="group h-auto min-h-24 justify-start gap-3 whitespace-normal bg-white p-3 text-left shadow-none hover:border-primary-400 hover:bg-primary-50/50"><span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-gray-100 text-gray-600 group-hover:bg-primary-100 group-hover:text-primary-700"><Icon className="size-4" /></span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold text-gray-900 break-words">{label}</span><span className="mt-1 block text-xs font-normal leading-relaxed text-gray-500">{description}</span></span><Plus className="size-4 shrink-0 text-gray-400" /></Button>)}
        </div></section>;
      })}
      {!options.length && <p className="py-8 text-center text-sm text-gray-500">{t("workspace_builder_no_widgets")}</p>}
      {loadingPlugins.size > 0 && <p role="status" className="text-xs text-gray-500">{t("workspace_builder_plugins_loading")}</p>}
    </div>
  </DialogContent></Dialog>;
}

import { LayoutDashboard, LockKeyhole } from "lucide-react";
import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { encounterPageKeySchema, titleSchema } from "@/types/workspace/encounterWorkspace";

import { systemPageLabel, type WorkspacePage } from "./workspaceEditorUtils";

interface WorkspacePageDialogProps {
  page?: Extract<WorkspacePage, { kind: "custom" }>;
  pages: WorkspacePage[];
  systemKeys: string[];
  onClose: () => void;
  onSave: (page: WorkspacePage) => void;
}

export function WorkspacePageDialog({ page, pages, systemKeys, onClose, onSave }: WorkspacePageDialogProps) {
  const { t } = useTranslation();
  const id = useId();
  const [kind, setKind] = useState<"custom" | "system">("custom");
  const [title, setTitle] = useState(page?.title ?? "");
  const [key, setKey] = useState(page?.key ?? "");
  const [keyEdited, setKeyEdited] = useState(!!page);
  const [icon, setIcon] = useState(page?.icon ?? "layout-dashboard");
  const availableSystems = systemKeys.filter((key) => !pages.some((page) => page.key === key));
  const [systemKey, setSystemKey] = useState(availableSystems[0] ?? "");
  const [showErrors, setShowErrors] = useState(false);
  const validTitle = titleSchema.safeParse(title).success;
  const validKey = encounterPageKeySchema.safeParse(key).success && !systemKeys.includes(key) && !pages.some((item) => item.key === key && item.key !== page?.key);
  const submit = () => {
    if (kind === "system" && availableSystems.includes(systemKey)) {
      onSave({ kind: "system", key: systemKey });
    } else if (kind === "custom" && validTitle && validKey) {
      onSave({ ...(page ?? { columns: [{ span: 1, widgets: [] }] }), kind: "custom", key, title: title.trim(), icon });
    } else setShowErrors(true);
  };

  return (
    <Dialog open onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t(page ? "workspace_builder_page_settings" : "workspace_builder_add_page")}</DialogTitle>
          <DialogDescription>{t("workspace_builder_page_dialog_hint")}</DialogDescription>
        </DialogHeader>
        {!page && <div className="grid grid-cols-2 gap-2 rounded-lg bg-gray-100 p-1" role="group" aria-label={t("workspace_builder_page_type")}>
          {(["custom", "system"] as const).map((value) => <Button key={value} type="button" variant="ghost" aria-pressed={kind === value} onClick={() => setKind(value)} className={cn(kind === value && "bg-white shadow-sm")}>
            {value === "custom" ? <LayoutDashboard /> : <LockKeyhole />}{t("workspace_builder_" + value + "_page")}
          </Button>)}
        </div>}
        {kind === "custom" ? <div className="space-y-4">
          <div className="space-y-2"><Label htmlFor={id + "-title"}>{t("workspace_builder_page_title")}</Label><Input id={id + "-title"} value={title} autoFocus maxLength={120} onChange={(event) => {
            setTitle(event.target.value);
            if (!keyEdited) setKey(event.target.value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 64));
          }} aria-invalid={showErrors && !validTitle} /></div>
          <div className="space-y-2"><Label htmlFor={id + "-key"}>{t("workspace_builder_page_key")}</Label><Input id={id + "-key"} value={key} onChange={(event) => { setKeyEdited(true); setKey(event.target.value); }} aria-invalid={showErrors && !validKey} className="font-mono text-sm" /><p className="text-xs leading-relaxed text-gray-500">{t("workspace_builder_page_key_hint")}</p></div>
          <div className="space-y-2"><Label htmlFor={id + "-icon"}>{t("workspace_builder_page_icon")}</Label><Select value={icon} onValueChange={setIcon}><SelectTrigger id={id + "-icon"}><SelectValue /></SelectTrigger><SelectContent>
            {["layout-dashboard", "stethoscope", "clipboard-list", "panels-top-left", "activity", "heart-pulse", ...(!["layout-dashboard", "stethoscope", "clipboard-list", "panels-top-left", "activity", "heart-pulse"].includes(icon) ? [icon] : [])].map((value) => <SelectItem key={value} value={value}>{t("workspace_builder_icon_" + value, { defaultValue: value })}</SelectItem>)}
          </SelectContent></Select></div>
          {showErrors && (!validTitle || !validKey) && <Alert variant="destructive"><AlertDescription>{t("workspace_builder_page_invalid")}</AlertDescription></Alert>}
        </div> : <div className="space-y-3">
          <Label htmlFor={id + "-system"}>{t("workspace_builder_system_page")}</Label>
          <Select value={systemKey} onValueChange={setSystemKey} disabled={!availableSystems.length}><SelectTrigger id={id + "-system"}><SelectValue /></SelectTrigger><SelectContent>{availableSystems.map((key) => <SelectItem key={key} value={key}>{systemPageLabel(key, t)}</SelectItem>)}</SelectContent></Select>
          <p className="text-sm leading-relaxed text-gray-500">{t(availableSystems.length ? "workspace_builder_system_hint" : "workspace_builder_all_system_pages_added")}</p>
        </div>}
        <DialogFooter><Button type="button" variant="outline" onClick={onClose}>{t("cancel")}</Button><Button type="button" onClick={submit} disabled={kind === "system" && !availableSystems.length}>{t(page ? "workspace_builder_apply_changes" : "workspace_builder_add_page")}</Button></DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

