import { ArrowDown, ArrowUp, Braces, Check, Columns3, EyeOff, LayoutDashboard, LockKeyhole, Monitor, Plus, Redo2, Settings2, Trash2, Undo2, WandSparkles } from "lucide-react";
import { useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useCareAppTabs } from "@/hooks/useCareApps";
import { cn } from "@/lib/utils";
import { createEncounterWorkspaceSchema, SYSTEM_PAGE_KEYS, type EncounterWorkspaceTemplate } from "@/types/workspace/encounterWorkspace";

import { WorkspacePageCanvas } from "./WorkspacePageCanvas";
import { WorkspacePageDialog } from "./WorkspacePageDialog";
import { WorkspaceWidgetInspector } from "./WorkspaceWidgetInspector";
import { WorkspaceWidgetLibrary } from "./WorkspaceWidgetLibrary";
import { moveItem, pageWidgetCount, systemPageLabel, type WidgetSelection, type WorkspacePage } from "./workspaceEditorUtils";

interface EncounterWorkspaceEditorProps {
  value: string;
  onChange: (value: string) => void;
  disabled?: boolean;
  onValidityChange?: (valid: boolean) => void;
}

export function EncounterWorkspaceEditor({ value, onChange, disabled = false, onValidityChange }: EncounterWorkspaceEditorProps) {
  const { t } = useTranslation();
  const id = useId();
  const pluginTabs = useCareAppTabs("encounterTabs");
  const systemKeys = [...new Set([...SYSTEM_PAGE_KEYS, ...Object.keys(pluginTabs)])];
