    page?.kind === "custom" && selection
      ? page.columns[selection.column]?.widgets[selection.widget]
      : undefined;
  const commit = (next: string) => {
    if (disabled || next === value) return;
    setHistory({
      past: [...history.past, value].slice(-30),
      future: [],
      lastValue: next,
    });
    onChange(next);
  };
