import { EncounterStatus } from "@/types/emr/encounter/encounter";
import { Status } from "@/types/emr/serviceRequest/serviceRequest";
import {
  encounterWidgetLimitSchema,
  responsesConfigSchema,
  serviceRequestsConfigSchema,
} from "@/types/workspace/encounterWidgetConfig";
import { EncounterWorkspaceWidget } from "@/types/workspace/encounterWorkspace";

import {
  CORE_WIDGET_CATALOG,
  workspaceWidgetLabel,
} from "./workspaceEditorCatalog";

const serviceStatuses = Object.values(Status).filter(
  (status) => status !== Status.unknown,
);

export interface WorkspaceWidgetInspectorProps {
  widget: EncounterWorkspaceWidget;
  onChange: (widget: EncounterWorkspaceWidget) => void;
  disabled?: boolean;
  onValidityChange?: (valid: boolean) => void;
}

/** Key by widget identity so local, incomplete input belongs to its selection. */
export function WorkspaceWidgetInspector({
  widget,
  onChange,
  disabled = false,
  onValidityChange,
}: WorkspaceWidgetInspectorProps) {
  const { t } = useTranslation();
  const id = useId();
  const [configDraft, setConfigDraft] = useState<string | null>(null);
  const [limitDraft, setLimitDraft] = useState<string | null>(null);
  const config = widget.config ?? {};
  const catalogItem = CORE_WIDGET_CATALOG.find(
    (item) => item.type === widget.type,
  );
  const Icon = catalogItem?.icon ?? Puzzle;
  const isResponses = widget.type === "questionnaire_responses";
  const isRequests = widget.type === "service_requests";
  const hasContentControls = isResponses || isRequests;
  const configText = configDraft ?? JSON.stringify(config, null, 2);
  let jsonError = false;
  try {
    const parsed: unknown = JSON.parse(configText);
    jsonError =
      parsed === null || typeof parsed !== "object" || Array.isArray(parsed);
  } catch {
    jsonError = true;
  }
  const configSchema = isResponses
    ? responsesConfigSchema
    : isRequests
      ? serviceRequestsConfigSchema
      : undefined;
  const configError = !!configSchema && !configSchema.safeParse(config).success;
  const limitValue =
    limitDraft ?? (config.limit === undefined ? "" : String(config.limit));
  const limitError =
    hasContentControls &&
    limitValue !== "" &&
    (!/^\d+$/.test(limitValue) ||
      !encounterWidgetLimitSchema.safeParse(Number(limitValue)).success);
  const valid = !jsonError && !configError && !limitError;
  const statuses = widget.visible_when?.["encounter.status"];

  useEffect(() => {
    onValidityChange?.(valid);
  }, [onValidityChange, valid]);
  useEffect(() => () => onValidityChange?.(true), [onValidityChange]);

  const updateConfig = (key: string, value: unknown) => {
    if (disabled || jsonError) return;
    const nextConfig = { ...config };
    if (value === undefined) delete nextConfig[key];
    else nextConfig[key] = value;
    setConfigDraft(null);
    onChange({ ...widget, config: nextConfig });
  };

  return (
    <section
      aria-label={t("workspace_widget_settings")}
      className="min-w-0 bg-white"
    >
      <div className="flex items-start gap-3 border-b border-gray-200 p-4">
        <div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-primary-50 text-primary-700 ring-1 ring-inset ring-primary-100">
          <Icon className="size-4" aria-hidden="true" />
        </div>
        <div className="min-w-0">
          <h3 className="text-sm font-semibold text-gray-950 break-words">
            {workspaceWidgetLabel(widget.type, t)}
          </h3>
          <p className="mt-1 text-xs leading-5 text-gray-500">
            {catalogItem
              ? t(catalogItem.descriptionKey)
              : t("workspace_widget_plugin_description")}
          </p>
        </div>
      </div>

      <div className="space-y-4 border-b border-gray-200 p-4">
        <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
          {t("workspace_widget_appearance")}
        </h4>
        <div className="space-y-2">
          <Label htmlFor={`${id}-title`} className="text-sm font-medium">
            {t("workspace_widget_title")}
          </Label>
          <Input
            id={`${id}-title`}
            value={widget.title ?? ""}
            placeholder={workspaceWidgetLabel(widget.type, t)}
            maxLength={120}
            disabled={disabled}
            aria-describedby={`${id}-title-help`}
            onChange={(event) => {
              const next = { ...widget };
              if (event.target.value.trim()) next.title = event.target.value;
              else delete next.title;
              onChange(next);
            }}
            className="h-9 text-sm shadow-none"
          />
          <p
            id={`${id}-title-help`}
            className="text-xs leading-5 text-gray-500"
          >
            {t("workspace_widget_title_hint")}
          </p>
        </div>
      </div>

      {hasContentControls && (
        <fieldset
          disabled={disabled || jsonError}
          className="min-w-0 space-y-4 border-b border-gray-200 p-4"
        >
          <h4 className="flex items-center gap-2 text-xs font-semibold text-gray-500 uppercase tracking-wide">
            <SlidersHorizontal className="size-3.5" aria-hidden="true" />
            {t("workspace_widget_content")}
          </h4>
          {isResponses && (
            <div className="space-y-2">
              <Label htmlFor={`${id}-slug`}>
                {t("workspace_widget_form_slug")}
              </Label>
              <Input
                id={`${id}-slug`}
                value={
                  typeof config.questionnaire_slug === "string"
                    ? config.questionnaire_slug
                    : ""
                }
                placeholder={t("workspace_widget_form_slug_placeholder")}
                disabled={disabled || jsonError}
                aria-describedby={`${id}-slug-help`}
                onChange={(event) =>
                  updateConfig(
                    "questionnaire_slug",
                    event.target.value.trim() || undefined,
                  )
                }
                className="h-9 text-sm shadow-none"
              />
              <p
                id={`${id}-slug-help`}
                className="text-xs leading-5 text-gray-500"
              >
                {t("workspace_widget_form_slug_hint")}
              </p>
            </div>
          )}
          {isRequests && (
            <div className="space-y-2">
              <Label htmlFor={`${id}-status`}>
                {t("workspace_widget_request_status")}
              </Label>
              <Select
                value={
                  typeof config.status === "string" ? config.status : "all"
                }
                disabled={disabled || jsonError}
                onValueChange={(value) =>
                  updateConfig("status", value === "all" ? undefined : value)
                }
              >
                <SelectTrigger
                  id={`${id}-status`}
                  className="h-9 w-full text-sm shadow-none"
                >
                  <SelectValue
                    placeholder={t("workspace_widget_all_statuses")}
                  />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">
                    {t("workspace_widget_all_statuses")}
                  </SelectItem>
                  {serviceStatuses.map((status) => (
                    <SelectItem key={status} value={status}>
                      {t(status)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
          <div className="space-y-2">
            <Label htmlFor={`${id}-limit`}>
              {t("workspace_widget_recent_limit")}
            </Label>
            <Input
              id={`${id}-limit`}
              type="text"
              inputMode="numeric"
              value={limitValue}
              placeholder={t("workspace_widget_no_limit")}
              disabled={disabled || jsonError}
              aria-invalid={limitError}
              aria-describedby={`${id}-limit-help`}
              onChange={(event) => {
                const value = event.target.value;
                setLimitDraft(value);
                if (!value) updateConfig("limit", undefined);
                else if (
                  /^\d+$/.test(value) &&
                  encounterWidgetLimitSchema.safeParse(Number(value)).success
                )
                  updateConfig("limit", Number(value));
              }}
              className="h-9 text-sm shadow-none"
            />
            <p
              id={`${id}-limit-help`}
              className={`text-xs leading-5 ${limitError ? "text-red-600" : "text-gray-500"}`}
            >
              {t(
                limitError
                  ? "workspace_widget_limit_error"
                  : "workspace_widget_limit_hint",
              )}
            </p>
          </div>
          {isResponses && (
            <div className="flex items-start justify-between gap-3 rounded-lg bg-gray-50 p-3">
              <div className="space-y-1">
                <Label
                  htmlFor={`${id}-unstructured`}
                  className="text-sm leading-5"
                >
                  {t("workspace_widget_unstructured")}
                </Label>
"}}
