      .fill("1");
    await inspector
      .getByRole("switch", { name: "Form responses only", exact: true })
      .check();

    await addWidget(1, "Vitals");
    await column(1)
      .getByRole("button", { name: "Remove Vitals", exact: true })
      .click();
    await expect(
      column(1).getByRole("button", { name: "Configure Vitals", exact: true }),
    ).toHaveCount(0);

    await addWidget(2, "Service Requests");
    await inspector
      .getByRole("textbox", { name: "Display title", exact: true })
      .fill("Active requests");
    await inspector
      .getByRole("combobox", { name: "Request status", exact: true })
      .click();
    await page.getByRole("option", { name: "Active", exact: true }).click();
    await inspector
      .getByRole("textbox", { name: "Latest results", exact: true })
      .fill("5");
    await page.getByRole("button", { name: "Add column", exact: true }).click();
    await column(3)
      .getByRole("button", { name: "Remove column 3", exact: true })
      .click();
    await expect(column(3)).toHaveCount(0);
    await column(2)
      .getByRole("button", { name: "Move column 2 left", exact: true })
      .click();
    await expect(
      column(1)
        .getByRole("button", {
          name: "Configure Active requests",
          exact: true,
        })
        .first(),
    ).toBeVisible();
    await expect(
      column(2)
        .getByRole("button", {
          name: "Configure Progress notes",
          exact: true,
        })
        .first(),
    ).toBeVisible();
  });

  await test.step("Add a fixed system page, hide it, and place it first", async () => {
    await page.getByRole("button", { name: "Add page", exact: true }).click();
    const dialog = page.getByRole("dialog", { name: "Add page", exact: true });
    await dialog
      .getByRole("button", { name: "System page", exact: true })
      .click();
    await dialog
      .getByRole("combobox", { name: "System page", exact: true })
      .click();
    await page
