import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import {
  encounterPageKeySchema,
  titleSchema,
} from "@/types/workspace/encounterWorkspace";

import { systemPageLabel, type WorkspacePage } from "./workspaceEditorUtils";

interface WorkspacePageDialogProps {
  page?: Extract<WorkspacePage, { kind: "custom" }>;
  pages: WorkspacePage[];
  systemKeys: string[];
  onClose: () => void;
  onSave: (page: WorkspacePage) => void;
}

export function WorkspacePageDialog({
  page,
  pages,
  systemKeys,
  onClose,
  onSave,
}: WorkspacePageDialogProps) {
  const { t } = useTranslation();
  const id = useId();
  const [kind, setKind] = useState<"custom" | "system">("custom");
  const [title, setTitle] = useState(page?.title ?? "");
  const [key, setKey] = useState(page?.key ?? "");
  const [keyEdited, setKeyEdited] = useState(!!page);
  const [icon, setIcon] = useState(page?.icon ?? "layout-dashboard");
  const availableSystems = systemKeys.filter(
    (key) => !pages.some((page) => page.key === key),
  );
  const [systemKey, setSystemKey] = useState(availableSystems[0] ?? "");
  const [showErrors, setShowErrors] = useState(false);
  const validTitle = titleSchema.safeParse(title).success;
  const validKey =
    encounterPageKeySchema.safeParse(key).success &&
    !systemKeys.includes(key) &&
    !pages.some((item) => item.key === key && item.key !== page?.key);
  const submit = () => {
    if (kind === "system" && availableSystems.includes(systemKey)) {
      onSave({ kind: "system", key: systemKey });
    } else if (kind === "custom" && validTitle && validKey) {
      onSave({
        ...(page ?? { columns: [{ span: 1, widgets: [] }] }),
        kind: "custom",
        key,
        title: title.trim(),
        icon,
      });
    } else setShowErrors(true);
  };

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent>
        <DialogHeader>
          <DialogTitle>
            {t(
              page
                ? "workspace_builder_page_settings"
                value={key}
                onChange={(event) => {
                  setKeyEdited(true);
                  setKey(event.target.value);
                }}
                aria-invalid={showErrors && !validKey}
                className="font-mono text-sm"
              />
              <p className="text-xs leading-relaxed text-gray-500">
                {t("workspace_builder_page_key_hint")}
              </p>
            </div>
            <div className="space-y-2">
              <Label htmlFor={id + "-icon"}>
                {t("workspace_builder_page_icon")}
              </Label>
              <Select value={icon} onValueChange={setIcon}>
                <SelectTrigger id={id + "-icon"}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {[
                    "layout-dashboard",
                    "stethoscope",
                    "clipboard-list",
                    "panels-top-left",
                    "activity",
                    "heart-pulse",
                    ...(![
                      "layout-dashboard",
                      "stethoscope",
                      "clipboard-list",
                      "panels-top-left",
                      "activity",
                      "heart-pulse",
                    ].includes(icon)
                      ? [icon]
                      : []),
                  ].map((value) => (
                    <SelectItem key={value} value={value}>
                      {t("workspace_builder_icon_" + value, {
                        defaultValue: value,
                      })}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            {showErrors && (!validTitle || !validKey) && (
              <Alert variant="destructive">
                <AlertDescription>
                  {t("workspace_builder_page_invalid")}
                </AlertDescription>
              </Alert>
            )}
          </div>
        ) : (
          <div className="space-y-3">
            <Label htmlFor={id + "-system"}>
              {t("workspace_builder_system_page")}
            </Label>
  const column = (index: number) =>
    page.getByRole("region", { name: `Column ${index}`, exact: true });
  const inspector = page.getByRole("region", {
    name: "Widget settings",
    exact: true,
  });
  const addWidget = async (columnIndex: number, label: string) => {
    await column(columnIndex)
      .getByRole("button", { name: "Add widget", exact: true })
      .click();
    const library = page.getByRole("dialog", {
      name: "Add widget",
      exact: true,
