import { Plus, Trash2 } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

const VALUE_TYPES = ["string", "number", "boolean", "array", "object", "null"] as const;
type ValueType = (typeof VALUE_TYPES)[number];

interface ConfigRow {
  id: string;
  key: string;
  type: ValueType;
  text: string;
}

interface WorkspaceConfigFieldsProps {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  excludedKeys?: readonly string[];
  disabled?: boolean;
  onValidityChange?: (valid: boolean) => void;
}

function valueType(value: unknown): ValueType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number") return "number";
  if (typeof value === "boolean") return "boolean";
  if (typeof value === "object") return "object";
  return "string";
}

function parseValue(type: ValueType, text: string): { valid: true; value: unknown } | { valid: false } {
  if (type === "string") return { valid: true, value: text };
  if (type === "null") return { valid: true, value: null };
  try {
    const value: unknown = JSON.parse(text);
    const valid =
      type === "number"
        ? typeof value === "number" && Number.isFinite(value)
        : type === "boolean"
          ? typeof value === "boolean"
          : type === "array"
            ? Array.isArray(value)
            : value !== null && typeof value === "object" && !Array.isArray(value);
    return valid ? { valid: true, value } : { valid: false };
  } catch {
    return { valid: false };
  }
}

const EMPTY_VALUE: Record<ValueType, string> = {
  string: "",
  number: "0",
  boolean: "false",
  array: "[]",
  object: "{}",
  null: "",
};

export function WorkspaceConfigFields({
  config,
  onChange,
  excludedKeys = [],
  disabled = false,
  onValidityChange,
}: WorkspaceConfigFieldsProps) {
  const { t } = useTranslation();
  const id = useId();
  const nextId = useRef(0);
  const [draft, setDraft] = useState<{
    rows: ConfigRow[];
    committed?: string;
  } | null>(null);
  const serialized = JSON.stringify(config);
  // Keep incomplete rows and editing focus locally. Committed rows follow a
  // later server or Advanced JSON change instead of masking refreshed values.
  const rows =
    draft && (draft.committed === undefined || draft.committed === serialized)
      ? draft.rows
      : Object.entries(config)
          .filter(([key]) => !excludedKeys.includes(key))
          .map(([key, value]) => ({
            id: `saved:${key}`,
            key,
            type: valueType(value),
            text: typeof value === "string" ? value : JSON.stringify(value, null, 2),
          }));
  const rowErrors = (row: ConfigRow, allRows: ConfigRow[]) => ({
    key: !row.key.trim()
      ? "workspace_config_key_required"
      : excludedKeys.includes(row.key)
        ? "workspace_config_key_reserved"
        : allRows.some((other) => other.id !== row.id && other.key === row.key)
          ? "workspace_config_key_duplicate"
          : undefined,
    value: !parseValue(row.type, row.text).valid,
  });
  const valid = rows.every((row) => {
    const errors = rowErrors(row, rows);
    return !errors.key && !errors.value;
  });

  useEffect(() => {
    onValidityChange?.(valid);
  }, [onValidityChange, valid]);
  useEffect(() => () => onValidityChange?.(true), [onValidityChange]);

  const updateRows = (nextRows: ConfigRow[]) => {
    if (disabled) return;
    const entries: [string, unknown][] = Object.entries(config).filter(([key]) =>
      excludedKeys.includes(key),
    );
    for (const row of nextRows) {
      const parsed = parseValue(row.type, row.text);
      if (rowErrors(row, nextRows).key || !parsed.valid) {
        setDraft({ rows: nextRows });
        return;
      }
      entries.push([row.key, parsed.value]);
    }
    const nextConfig = Object.fromEntries(entries);
    setDraft({ rows: nextRows, committed: JSON.stringify(nextConfig) });
