                  <Input
                    id={`${fieldId}-key`}
                    aria-label={t("workspace_config_key_number", { number })}
                    value={row.key}
                    disabled={disabled}
                    aria-invalid={!!errors.key}
                    aria-describedby={errors.key ? `${fieldId}-key-error` : undefined}
                    onChange={(event) => updateRow(row.id, { key: event.target.value })}
                    className="h-8 bg-white font-mono text-xs shadow-none"
                  />
                </div>
                <Button type="button" size="icon" variant="ghost" disabled={disabled} aria-label={t("workspace_config_remove", { number })} onClick={() => updateRows(rows.filter((item) => item.id !== row.id))} className="size-8 shrink-0 text-gray-400 hover:bg-red-50 hover:text-red-700">
                  <Trash2 className="size-3.5" />
                </Button>
              </div>
              {errors.key && <p id={`${fieldId}-key-error`} className="text-xs leading-5 text-red-600">{t(errors.key)}</p>}
              <div className="grid grid-cols-[96px_minmax(0,1fr)] items-start gap-2">
                <div className="space-y-1.5">
                  <Label htmlFor={`${fieldId}-type`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_type")}</Label>
                  <Select value={row.type} disabled={disabled} onValueChange={(type: ValueType) => updateRow(row.id, { type, text: parseValue(type, row.text).valid ? row.text : EMPTY_VALUE[type] })}>
                    <SelectTrigger id={`${fieldId}-type`} aria-label={t("workspace_config_type_number", { number })} className="h-8 w-full bg-white px-2 text-xs shadow-none"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {VALUE_TYPES.map((type) => <SelectItem key={type} value={type}>{t(`workspace_config_type_${type}`)}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                {!complex && (
                  <div className="min-w-0 space-y-1.5">
                    <Label htmlFor={`${fieldId}-value`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_value")}</Label>
                    {row.type === "boolean" ? (
                      <Select value={row.text.trim()} disabled={disabled} onValueChange={(text) => updateRow(row.id, { text })}>
                        <SelectTrigger id={`${fieldId}-value`} aria-label={valueLabel} className="h-8 w-full bg-white px-2 text-xs shadow-none"><SelectValue /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="true">{t("workspace_config_true")}</SelectItem>
                          <SelectItem value="false">{t("workspace_config_false")}</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : row.type === "null" ? (
                      <p className="flex h-8 items-center text-xs italic text-gray-400">{t("workspace_config_null_value")}</p>
                    ) : (
                      <Input id={`${fieldId}-value`} aria-label={valueLabel} value={row.text} disabled={disabled} inputMode={row.type === "number" ? "decimal" : undefined} aria-invalid={errors.value} aria-describedby={errors.value ? `${fieldId}-value-error` : undefined} onChange={(event) => updateRow(row.id, { text: event.target.value })} className="h-8 bg-white text-xs shadow-none" />
                    )}
                  </div>
                )}
              </div>
              {complex && (
                <div className="space-y-1.5">
                  <Label htmlFor={`${fieldId}-value`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_value")}</Label>
                  <Textarea id={`${fieldId}-value`} aria-label={valueLabel} value={row.text} disabled={disabled} rows={3} spellCheck={false} aria-invalid={errors.value} aria-describedby={errors.value ? `${fieldId}-value-error` : undefined} onChange={(event) => updateRow(row.id, { text: event.target.value })} className="min-h-20 resize-y bg-white font-mono text-xs leading-5 shadow-none" />
                </div>
              )}
