import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

const VALUE_TYPES = ["string", "number", "boolean", "array", "object", "null"] as const;
type ValueType = (typeof VALUE_TYPES)[number];

interface ConfigRow {
  id: string;
  key: string;
  type: ValueType;
  text: string;
}

interface WorkspaceConfigFieldsProps {
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  excludedKeys?: readonly string[];
  disabled?: boolean;
  onValidityChange?: (valid: boolean) => void;
}

function valueType(value: unknown): ValueType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number") return "number";
  if (typeof value === "boolean") return "boolean";
  if (typeof value === "object") return "object";
  return "string";
}

function parseValue(type: ValueType, text: string): { valid: true; value: unknown } | { valid: false } {
  if (type === "string") return { valid: true, value: text };
  if (type === "null") return { valid: true, value: null };
  try {
    const value: unknown = JSON.parse(text);
    const valid =
      type === "number"
        ? typeof value === "number" && Number.isFinite(value)
        : type === "boolean"
          ? typeof value === "boolean"
          : type === "array"
            ? Array.isArray(value)
            : value !== null && typeof value === "object" && !Array.isArray(value);
    return valid ? { valid: true, value } : { valid: false };
  } catch {
    return { valid: false };
  }
}

const EMPTY_VALUE: Record<ValueType, string> = {
  string: "",
  number: "0",
  boolean: "false",
  array: "[]",
  object: "{}",
  null: "",
};

export function WorkspaceConfigFields({
  config,
  onChange,
  excludedKeys = [],
  disabled = false,
  onValidityChange,
}: WorkspaceConfigFieldsProps) {
  const { t } = useTranslation();
  const id = useId();
  const nextId = useRef(0);
  const [draft, setDraft] = useState<{
    rows: ConfigRow[];
    committed?: string;
  } | null>(null);
  const serialized = JSON.stringify(config);
  // Keep incomplete rows and editing focus locally. Committed rows follow a
  // later server or Advanced JSON change instead of masking refreshed values.
  const rows =
    draft && (draft.committed === undefined || draft.committed === serialized)
      ? draft.rows
      : Object.entries(config)
          .filter(([key]) => !excludedKeys.includes(key))
          .map(([key, value]) => ({
            id: `saved:${key}`,
            key,
            type: valueType(value),
            text: typeof value === "string" ? value : JSON.stringify(value, null, 2),
          }));
  const rowErrors = (row: ConfigRow, allRows: ConfigRow[]) => ({
    key: !row.key.trim()
      ? "workspace_config_key_required"
      : excludedKeys.includes(row.key)
        ? "workspace_config_key_reserved"
        : allRows.some((other) => other.id !== row.id && other.key === row.key)
          ? "workspace_config_key_duplicate"
          : undefined,
    value: !parseValue(row.type, row.text).valid,
  });
  const valid = rows.every((row) => {
    const errors = rowErrors(row, rows);
    return !errors.key && !errors.value;
  });

  useEffect(() => {
    onValidityChange?.(valid);
  }, [onValidityChange, valid]);
  useEffect(() => () => onValidityChange?.(true), [onValidityChange]);

  const updateRows = (nextRows: ConfigRow[]) => {
    if (disabled) return;
    const entries: [string, unknown][] = Object.entries(config).filter(([key]) =>
      excludedKeys.includes(key),
    );
    for (const row of nextRows) {
      const parsed = parseValue(row.type, row.text);
      if (rowErrors(row, nextRows).key || !parsed.valid) {
        setDraft({ rows: nextRows });
        return;
      }
      entries.push([row.key, parsed.value]);
    }
    const nextConfig = Object.fromEntries(entries);
    setDraft({ rows: nextRows, committed: JSON.stringify(nextConfig) });
    onChange(nextConfig);
  };
  const updateRow = (rowId: string, update: Partial<ConfigRow>) =>
    updateRows(rows.map((row) => (row.id === rowId ? { ...row, ...update } : row)));
  const title = t(excludedKeys.length ? "workspace_config_additional" : "workspace_config_title");

  return (
    <section aria-label={title} className="space-y-3 border-b border-gray-200 p-4">
      <div className="flex items-center justify-between gap-2">
        <h4 className="text-xs font-semibold uppercase tracking-wide text-gray-500">{title}</h4>
        {!!rows.length && <span className="rounded bg-gray-100 px-1.5 py-0.5 text-[10px] text-gray-500">{rows.length}</span>}
      </div>
      {!rows.length && (
        <p className="text-xs leading-5 text-gray-500">
          {t(excludedKeys.length ? "workspace_config_additional_empty" : "workspace_config_empty")}
        </p>
      )}
      <div className="space-y-3">
        {rows.map((row, index) => {
          const number = index + 1;
          const fieldId = `${id}-${row.id}`;
          const errors = rowErrors(row, rows);
          const complex = row.type === "array" || row.type === "object";
          const valueLabel = t("workspace_config_value_number", { number });
          return (
            <div key={row.id} role="group" aria-label={t("workspace_config_entry", { number })} className="space-y-2.5 rounded-lg border border-gray-200 bg-gray-50/60 p-2.5">
              <div className="flex items-end gap-1.5">
                <div className="min-w-0 flex-1 space-y-1.5">
                  <Label htmlFor={`${fieldId}-key`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_key")}</Label>
                  <Input
                    id={`${fieldId}-key`}
                    aria-label={t("workspace_config_key_number", { number })}
                    value={row.key}
                    disabled={disabled}
                    aria-invalid={!!errors.key}
                    aria-describedby={errors.key ? `${fieldId}-key-error` : undefined}
                    onChange={(event) => updateRow(row.id, { key: event.target.value })}
                    className="h-8 bg-white font-mono text-xs shadow-none"
                  />
                </div>
                <Button type="button" size="icon" variant="ghost" disabled={disabled} aria-label={t("workspace_config_remove", { number })} onClick={() => updateRows(rows.filter((item) => item.id !== row.id))} className="size-8 shrink-0 text-gray-400 hover:bg-red-50 hover:text-red-700">
                  <Trash2 className="size-3.5" />
                </Button>
              </div>
              {errors.key && <p id={`${fieldId}-key-error`} className="text-xs leading-5 text-red-600">{t(errors.key)}</p>}
              <div className="grid grid-cols-[96px_minmax(0,1fr)] items-start gap-2">
                <div className="space-y-1.5">
                  <Label htmlFor={`${fieldId}-type`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_type")}</Label>
                  <Select value={row.type} disabled={disabled} onValueChange={(type: ValueType) => updateRow(row.id, { type, text: parseValue(type, row.text).valid ? row.text : EMPTY_VALUE[type] })}>
                    <SelectTrigger id={`${fieldId}-type`} aria-label={t("workspace_config_type_number", { number })} className="h-8 w-full bg-white px-2 text-xs shadow-none"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {VALUE_TYPES.map((type) => <SelectItem key={type} value={type}>{t(`workspace_config_type_${type}`)}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                {!complex && (
                  <div className="min-w-0 space-y-1.5">
                    <Label htmlFor={`${fieldId}-value`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_value")}</Label>
                    {row.type === "boolean" ? (
                      <Select value={row.text.trim()} disabled={disabled} onValueChange={(text) => updateRow(row.id, { text })}>
                        <SelectTrigger id={`${fieldId}-value`} aria-label={valueLabel} className="h-8 w-full bg-white px-2 text-xs shadow-none"><SelectValue /></SelectTrigger>
                        <SelectContent>
                          <SelectItem value="true">{t("workspace_config_true")}</SelectItem>
                          <SelectItem value="false">{t("workspace_config_false")}</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : row.type === "null" ? (
                      <p className="flex h-8 items-center text-xs italic text-gray-400">{t("workspace_config_null_value")}</p>
                    ) : (
                      <Input id={`${fieldId}-value`} aria-label={valueLabel} value={row.text} disabled={disabled} inputMode={row.type === "number" ? "decimal" : undefined} aria-invalid={errors.value} aria-describedby={errors.value ? `${fieldId}-value-error` : undefined} onChange={(event) => updateRow(row.id, { text: event.target.value })} className="h-8 bg-white text-xs shadow-none" />
                    )}
                  </div>
                )}
              </div>
              {complex && (
                <div className="space-y-1.5">
                  <Label htmlFor={`${fieldId}-value`} className="text-[10px] font-medium text-gray-500">{t("workspace_config_value")}</Label>
                  <Textarea id={`${fieldId}-value`} aria-label={valueLabel} value={row.text} disabled={disabled} rows={3} spellCheck={false} aria-invalid={errors.value} aria-describedby={errors.value ? `${fieldId}-value-error` : undefined} onChange={(event) => updateRow(row.id, { text: event.target.value })} className="min-h-20 resize-y bg-white font-mono text-xs leading-5 shadow-none" />
                </div>
              )}
              {errors.value && <p id={`${fieldId}-value-error`} className="text-xs leading-5 text-red-600">{t("workspace_config_value_invalid", { type: t(`workspace_config_type_${row.type}`) })}</p>}
            </div>
          );
        })}
      </div>
      <Button type="button" size="sm" variant="outline" disabled={disabled} onClick={() => updateRows([...rows, { id: `new:${nextId.current++}`, key: "", type: "string", text: "" }])} className="h-8 w-full border-dashed border-gray-300 bg-transparent text-xs text-gray-600 shadow-none">
        <Plus className="size-3.5" />{t("workspace_config_add")}
      </Button>
    </section>
  );
}
