          await route.fulfill({ status: 204 });
        } else {
          await route.abort();
        }
      } else {
        await route.abort();
      }
    },
  );

  return {
    facilityId,
    records,
    writes,
    reads,
    rejectedWrites,
    failures,
    organizations,
    assignments,
    user,
  };
}

