import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  encounterPageKeySchema,
  titleSchema,
} from "@/types/workspace/encounterWorkspace";

import { type WorkspacePage } from "./workspaceEditorUtils";

const PAGE_ICONS = [
  "layout-dashboard",
  "stethoscope",
  "clipboard-list",
  "panels-top-left",
  "activity",
  "heart-pulse",
];

interface WorkspacePageDialogProps {
  page?: Extract<WorkspacePage, { kind: "custom" }>;
  pages: WorkspacePage[];
  systemKeys: string[];
  onClose: () => void;
  onSave: (page: WorkspacePage) => void;
}

export function WorkspacePageDialog({
  page,
  pages,
  systemKeys,
  onClose,
  onSave,
}: WorkspacePageDialogProps) {
  const { t } = useTranslation();
  const id = useId();
  const [title, setTitle] = useState(page?.title ?? "");
  const [key, setKey] = useState(page?.key ?? "");
  const [keyEdited, setKeyEdited] = useState(!!page);
  const [icon, setIcon] = useState(page?.icon ?? "layout-dashboard");
  const [showErrors, setShowErrors] = useState(false);
  const validTitle = titleSchema.safeParse(title).success;
  const validKey =
    encounterPageKeySchema.safeParse(key).success &&
    !systemKeys.includes(key) &&
    !pages.some((item) => item.key === key && item.key !== page?.key);
  const submit = () => {
    if (validTitle && validKey) {
      onSave({
        ...(page ?? { columns: [{ span: 1, widgets: [] }] }),
        kind: "custom",
        key,
        title: title.trim(),
        icon,
      });
    } else setShowErrors(true);
  };

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent>
        <DialogHeader>
          <DialogTitle>
            {t(
              page
                ? "workspace_builder_page_settings"
                : "workspace_builder_add_page",
            )}
          </DialogTitle>
          <DialogDescription>
            {t("workspace_builder_page_dialog_hint")}
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor={id + "-title"}>
              {t("workspace_builder_page_title")}
            </Label>
            <Input
              id={id + "-title"}
              value={title}
              autoFocus
              maxLength={120}
              onChange={(event) => {
                setTitle(event.target.value);
                if (!keyEdited)
                  setKey(
                    event.target.value
                      .toLowerCase()
                      .replace(/[^a-z0-9]+/g, "-")
                      .replace(/^-|-$/g, "")
                      .slice(0, 64),
                  );
              }}
              aria-invalid={showErrors && !validTitle}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor={id + "-key"}>
              {t("workspace_builder_page_key")}
            </Label>
            <Input
              id={id + "-key"}
              value={key}
              onChange={(event) => {
                setKeyEdited(true);
                setKey(event.target.value);
              }}
              aria-invalid={showErrors && !validKey}
              className="font-mono text-sm"
            />
            <p className="text-xs leading-relaxed text-gray-500">
              {t("workspace_builder_page_key_hint")}
            </p>
          </div>
          <div className="space-y-2">
            <Label htmlFor={id + "-icon"}>
              {t("workspace_builder_page_icon")}
            </Label>
            <Select value={icon} onValueChange={setIcon}>
              <SelectTrigger id={id + "-icon"}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {[
                  ...PAGE_ICONS,
                  ...(!PAGE_ICONS.includes(icon) ? [icon] : []),
                ].map((value) => (
                  <SelectItem key={value} value={value}>
                    {t("workspace_builder_icon_" + value, {
                      defaultValue: value,
                    })}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          {showErrors && (!validTitle || !validKey) && (
            <Alert variant="destructive">
              <AlertDescription>
                {t("workspace_builder_page_invalid")}
              </AlertDescription>
            </Alert>
          )}
        </div>
        <DialogFooter>
          <Button type="button" variant="outline" onClick={onClose}>
            {t("cancel")}
          </Button>
          <Button type="button" onClick={submit}>
            {t(
              page
                ? "workspace_builder_apply_changes"
                : "workspace_builder_add_page",
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
import {
  Activity,
  ClipboardList,
  HeartPulse,
  LayoutDashboard,
  PanelsTopLeft,
  Stethoscope,
  type LucideIcon,
} from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useRef } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import ErrorBoundary from "@/components/Common/ErrorBoundary";

import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";

import { EncounterWorkspacePage } from "./EncounterWorkspacePage";
import { parseEncounterWorkspace } from "./parseEncounterWorkspace";
import { useEncounterWorkspaces } from "./useEncounterWorkspaces";

const customPageIcons: Record<string, LucideIcon> = {
  stethoscope: Stethoscope,
  "clipboard-list": ClipboardList,
  "layout-dashboard": LayoutDashboard,
  "panels-top-left": PanelsTopLeft,
  activity: Activity,
  "heart-pulse": HeartPulse,
};

interface EncounterWorkspaceContentProps {
  systemTabs: Record<string, EncounterTab>;
  currentTab: string;
}

export function EncounterWorkspaceContent({
  systemTabs,
  currentTab,
}: EncounterWorkspaceContentProps) {
  const { t } = useTranslation();
  const initializedEncounter = useRef<string | undefined>(undefined);
  const { selectedEncounter, isSelectedEncounterLoading } = useEncounter();
  const { defaults, list, workspace } = useEncounterWorkspaces(
    selectedEncounter?.encounter_class,
  );
  const parsed = workspace
    ? parseEncounterWorkspace(workspace.template, Object.keys(systemTabs))
    : undefined;
  const tabs: Record<string, EncounterTab> = {};

  if (parsed) {
    for (const page of parsed.pages) {
      if (page.kind === "system") {
        const systemTab = systemTabs[page.key];
        if (systemTab)
          tabs[page.key] = {
            ...systemTab,
            visible: !page.hidden && systemTab.visible !== false,
          };
      } else if (page.kind === "custom") {
        tabs[page.key] = {
          label: page.title,
          visible: !page.hidden,
          icon:
            page.icon && Object.hasOwn(customPageIcons, page.icon)
              ? customPageIcons[page.icon]
              : LayoutDashboard,
          component: <EncounterWorkspacePage page={page} />,
        };
      } else {
        tabs[page.key] = {
          label: page.title,
          icon: LayoutDashboard,
          visible: !page.hidden,
          component: (
            <Alert>
              <AlertDescription>
                {t("encounter_workspace_page_unavailable")}
              </AlertDescription>
            </Alert>
          ),
        };
      }
    }
  } else {
    Object.assign(tabs, systemTabs);
  }

  if (workspace) {
    const resetKey = `${workspace.id}:${selectedEncounter?.id}:${JSON.stringify(workspace.template)}`;
    for (const [key, tab] of Object.entries(tabs)) {
      tab.component = (
        <ErrorBoundary
          key={`${key}:${resetKey}`}
          fallback={
            <Alert variant="destructive">
              <AlertDescription>
                {t("encounter_workspace_page_error")}
              </AlertDescription>
            </Alert>
          }
        >
          {tab.component}
        </ErrorBoundary>
      );
    }
  }

  const firstVisibleTab = Object.keys(tabs).find(
    (key) => tabs[key].visible !== false,
  );
  const activeTab =
    tabs[currentTab]?.visible !== false && Object.hasOwn(tabs, currentTab)
      ? currentTab
      : (firstVisibleTab ?? "updates");
  const isLoadingSelection =
    defaults.isLoading || list.isLoading || isSelectedEncounterLoading;

  const navigateToTab = (tab: string, replace = false) => {
    const target = new URL(tab, window.location.href);
    if (tab === currentTab) {
      target.search = window.location.search;
    } else {
      const selectedEncounterParam = new URLSearchParams(
        window.location.search,
      ).get("selectedEncounter");
      target.search = selectedEncounterParam
        ? new URLSearchParams({
            selectedEncounter: selectedEncounterParam,
          }).toString()
        : "";
    }
    target.searchParams.delete("workspace");
    if (target.href !== window.location.href)
      navigate(`${target.pathname}${target.search}`, { replace });
  };

  useEffect(() => {
    if (isLoadingSelection) return;
    if (!defaults.isError && !list.isError) {
      const firstVisit = initializedEncounter.current !== selectedEncounter?.id;
      if (firstVisit && (defaults.isFetching || list.isFetching)) return;
      initializedEncounter.current = selectedEncounter?.id;
      // Encounter entry links use /updates. Apply the saved layout on entry,
      // while allowing an explicit Overview tab selection during the visit.
      if (firstVisit && currentTab === "updates" && parsed && firstVisibleTab) {
        navigateToTab(firstVisibleTab, true);
        return;
      }
      if (firstVisibleTab && activeTab !== currentTab) {
        navigateToTab(activeTab, true);
        return;
      }
    }
    if (new URLSearchParams(window.location.search).has("workspace"))
      navigateToTab(currentTab, true);
  });

  return (
    <div className="space-y-3">
      {(defaults.isError || list.isError) && (
        <Alert>
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                defaults.refetch();
                list.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && (parsed.invalid || parsed.unsupportedVersion) && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.unsupportedVersion
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}

