    for (const remaining of remainingPages) {
      await expect(
        page.getByRole("button", { name: remaining.title, exact: true }),
      ).toBeVisible();
    }
    await expect(save).toBeDisabled();
    expect(api.writes).toEqual([]);
  });
});

